-- Recipe: aloo-gobi (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('aloo-gobi', 'Aloo Gobi', '{"en": "Aloo Gobi", "hi": "आलू गोभी", "hi-Latn": "Aloo Gobi"}'::jsonb, 'A dry, homestyle sabzi of cauliflower florets and potato cubes cooked in their own steam with onion, tomato and everyday masalas, finished with a squeeze of tang from amchur. Goes with roti, paratha or dal-chawal.', '{"hi": "गोभी के फूल और आलू के टुकड़ों की सूखी, घर जैसी सब्ज़ी। इसे प्याज़, टमाटर और रोज़ के मसालों के साथ अपनी ही भाप में पकाया जाता है और आख़िर में अमचूर की हल्की खटास डाली जाती है। रोटी, पराठे या दाल-चावल के साथ खाएँ।", "hi-Latn": "Gobi ke phool aur aloo ke tukdon ki sookhi, ghar jaisi sabzi. Ise pyaaz, tamatar aur roz ke masalon ke saath apni hi bhaap mein pakaya jaata hai aur aakhir mein amchur ki halki khatas daali jaati hai. Roti, parathe ya dal-chawal ke saath khaayein."}'::jsonb, 'north_indian_punjabi_', 'main', 'veg', 4, 15, 25, 2, 2, array['kadai', 'gas_stove']::text[], array['comforting', 'tiffin', 'kids_friendly', 'one_pot']::text[], '{"acid": 0.2, "crunch": 0.2, "heat": 0.4, "rich": 0.3, "starch": 0.7, "sweet": 0}'::jsonb, array['sabzi']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
