insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'aloo-gobi'), 1, 'Cut the cauliflower into medium florets and soak them in warm salted water for 5 minutes, then drain; peel the potatoes and cut them into cubes the same size as the florets.', '{"en": "Cut the cauliflower into medium florets and soak them in warm salted water for 5 minutes, then drain; peel the potatoes and cut them into cubes the same size as the florets.", "hi": {"look": "गोभी के फूल और आलू के टुकड़े लगभग एक जितने बड़े हों।", "safety": "भिगोने के बाद गोभी में छोटे कीड़े देख लें और अच्छे से धो लें।", "text": "गोभी को मध्यम फूलों में काटकर 5 मिनट गुनगुने नमक वाले पानी में भिगोएँ, फिर पानी निकाल दें। आलू छीलकर गोभी के फूलों जितने ही टुकड़ों में काटें।"}, "hi-Latn": {"look": "Gobi ke phool aur aloo ke tukde lagbhag ek jitne bade hon.", "safety": "Bhigone ke baad gobi mein chhote keede dekh lein aur achhe se dho lein.", "text": "Gobi ko medium phoolon mein kaatkar 5 minute gungune namak waale paani mein bhigoyein, phir paani nikaal dein. Aloo chheelkar gobi ke phoolon jitne hi tukdon mein kaatein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 300, true, null, 'Florets and potato pieces are roughly the same size.', '{"en": "Florets and potato pieces are roughly the same size.", "look": "Florets and potato pieces are roughly the same size."}'::jsonb, null, 'Check the florets for small insects after soaking and rinse well.'),
  ((select id from public.recipes where household_id is null and slug = 'aloo-gobi'), 2, 'Heat the oil in a kadai and add the cumin seeds.', '{"en": "Heat the oil in a kadai and add the cumin seeds.", "hi": {"look": "जीरे का रंग थोड़ा गहरा हो जाए।", "sound": "जीरा चटकने लगे।", "text": "कड़ाही में तेल गरम करें और जीरा डालें।"}, "hi-Latn": {"look": "Jeere ka rang thoda gehra ho jaaye.", "sound": "Jeera chatakne lage.", "text": "Kadai mein tel garam karein aur jeera daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin turns a shade darker. The seeds crackle.', '{"en": "The cumin turns a shade darker. The seeds crackle.", "heat": "medium", "look": "The cumin turns a shade darker.", "sound": "The seeds crackle."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-gobi'), 3, 'Add the chopped onion, grated ginger and slit green chillies and fry until the onion turns light golden.', '{"en": "Add the chopped onion, grated ginger and slit green chillies and fry until the onion turns light golden.", "hi": {"look": "प्याज़ नरम हो और किनारों से हल्का सुनहरा दिखे।", "smell": "अदरक की कच्ची महक चली जाए।", "text": "कटा प्याज़, कसा हुआ अदरक और बीच से चिरी हरी मिर्च डालें और प्याज़ हल्का सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram ho aur kinaaron se halka sunehra dikhe.", "smell": "Adrak ki kachchi mehek chali jaaye.", "text": "Kata pyaaz, kasa hua adrak aur beech se chiri hari mirch daalein aur pyaaz halka sunehra hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 240, true, null, 'The onion is soft and light golden at the edges. The raw smell of ginger goes away.', '{"en": "The onion is soft and light golden at the edges. The raw smell of ginger goes away.", "heat": "medium", "look": "The onion is soft and light golden at the edges.", "smell": "The raw smell of ginger goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-gobi'), 4, 'Add the chopped tomato, turmeric, red chilli powder, coriander powder and a little salt, and cook the masala until the tomato is mushy.', '{"en": "Add the chopped tomato, turmeric, red chilli powder, coriander powder and a little salt, and cook the masala until the tomato is mushy.", "hi": {"look": "मसाले के किनारों से तेल अलग होने लगे।", "text": "कटा टमाटर, हल्दी, लाल मिर्च, धनिया पाउडर और थोड़ा नमक डालें और टमाटर गलने तक मसाला भूनें।", "touch": "टमाटर कलछी के पीछे से आसानी से मसल जाए।"}, "hi-Latn": {"look": "Masale ke kinaaron se tel alag hone lage.", "text": "Kata tamatar, haldi, laal mirch, dhaniya powder aur thoda namak daalein aur tamatar galne tak masala bhunein.", "touch": "Tamatar kalchhi ke peechhe se aasaani se masal jaaye."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 300, true, null, 'Oil starts to separate at the sides of the masala. The tomato mashes easily with the back of the spoon.', '{"en": "Oil starts to separate at the sides of the masala. The tomato mashes easily with the back of the spoon.", "heat": "medium", "look": "Oil starts to separate at the sides of the masala.", "touch": "The tomato mashes easily with the back of the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-gobi'), 5, 'Add the potatoes and cauliflower with the rest of the salt and toss until every piece is coated in masala.', '{"en": "Add the potatoes and cauliflower with the rest of the salt and toss until every piece is coated in masala.", "hi": {"look": "हर टुकड़ा पीला और मसाले में लिपटा दिखे।", "text": "आलू और गोभी के साथ बाकी नमक डालें और हर टुकड़े पर मसाला लगने तक अच्छे से मिलाएँ।"}, "hi-Latn": {"look": "Har tukda peela aur masale mein lipta dikhe.", "text": "Aloo aur gobi ke saath baaki namak daalein aur har tukde par masala lagne tak achhe se milaayein."}}'::jsonb, null, 120, false, null, 'Every piece looks yellow and coated in masala.', '{"en": "Every piece looks yellow and coated in masala.", "heat": "medium", "look": "Every piece looks yellow and coated in masala."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-gobi'), 6, 'Cover and cook without adding water, stirring gently every 5 minutes, until the potatoes are cooked through.', '{"en": "Cover and cook without adding water, stirring gently every 5 minutes, until the potatoes are cooked through.", "hi": {"look": "गोभी नरम हो जाए पर टूटे नहीं।", "text": "ढककर बिना पानी डाले पकाएँ और हर 5 मिनट में हल्के हाथ से चलाते रहें, जब तक आलू पूरे पक न जाएँ।", "touch": "चाकू आलू के टुकड़ों में आसानी से घुस जाए।"}, "hi-Latn": {"look": "Gobi naram ho jaaye par toote nahin.", "text": "Dhakkar bina paani daale pakaayein aur har 5 minute mein halke haath se chalaate rahein, jab tak aloo poore pak na jaayein.", "touch": "Chaaku aloo ke tukdon mein aasaani se ghus jaaye."}}'::jsonb, null, 900, true, null, 'The florets are tender but still hold their shape. A knife goes through the potato cubes easily.', '{"en": "The florets are tender but still hold their shape. A knife goes through the potato cubes easily.", "heat": "low", "look": "The florets are tender but still hold their shape.", "touch": "A knife goes through the potato cubes easily."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-gobi'), 7, 'Uncover, sprinkle the garam masala and amchur, and cook for 2 to 3 minutes to dry off any moisture, then garnish with coriander leaves.', '{"en": "Uncover, sprinkle the garam masala and amchur, and cook for 2 to 3 minutes to dry off any moisture, then garnish with coriander leaves.", "hi": {"look": "सब्ज़ी सूखी हो और कुछ किनारे हल्के भूरे हों।", "smell": "गरम मसाले की ख़ुशबू आने लगे।", "text": "ढक्कन हटाकर गरम मसाला और अमचूर छिड़कें और 2-3 मिनट पकाकर नमी सुखा दें, फिर हरा धनिया डालें।"}, "hi-Latn": {"look": "Sabzi sookhi ho aur kuchh kinaare halke bhoore hon.", "smell": "Garam masale ki khushboo aane lage.", "text": "Dhakkan hataakar garam masala aur amchur chhidkein aur 2-3 minute pakaakar nami sukha dein, phir hara dhaniya daalein."}}'::jsonb, null, 180, true, null, 'The sabzi is dry with a few lightly browned edges. The garam masala smells fragrant.', '{"en": "The sabzi is dry with a few lightly browned edges. The garam masala smells fragrant.", "heat": "medium", "look": "The sabzi is dry with a few lightly browned edges.", "smell": "The garam masala smells fragrant."}'::jsonb, null, null)
