  source, review_status, is_published) values
  ('aloo-matar', 'Aloo Matar', '{"en": "Aloo Matar", "hi": "आलू मटर", "hi-Latn": "Aloo Matar"}'::jsonb, 'An everyday North Indian curry of potato and green peas in a light onion-tomato gravy, cooked in the pressure cooker. Goes well with roti or rice.', '{"hi": "प्याज़-टमाटर की हल्की ग्रेवी में आलू और हरी मटर की रोज़ बनने वाली उत्तर भारतीय सब्ज़ी, प्रेशर कुकर में बनी। रोटी या चावल के साथ बढ़िया लगती है।", "hi-Latn": "Pyaaz-tamatar ki halki gravy mein aloo aur hari matar ki roz banne wali North Indian sabzi, pressure cooker mein bani. Roti ya chawal ke saath badhiya lagti hai."}'::jsonb, 'north_indian', 'main', 'veg', 4, 15, 25, 1, 2, array['pressure_cooker', 'gas_stove']::text[], array['comforting', 'one_pot', 'kids_friendly', 'tiffin']::text[], '{"acid": 0.4, "crunch": 0, "heat": 0.3, "rich": 0.4, "starch": 0.7, "sweet": 0.1}'::jsonb, array['sabzi']::text[], 'curated', 'in_review', false)
