insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'aloo-matar'), 1, 'Heat oil in the pressure cooker, add cumin seeds and asafoetida.', '{"en": "Heat oil in the pressure cooker, add cumin seeds and asafoetida.", "hi": {"sound": "जीरा चटकने लगे।", "text": "प्रेशर कुकर में तेल गरम करें, जीरा और हींग डालें।"}, "hi-Latn": {"sound": "Jeera chatakne lage.", "text": "Pressure cooker mein tel garam karein, jeera aur hing daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin crackles.', '{"en": "The cumin crackles.", "heat": "medium", "sound": "The cumin crackles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-matar'), 2, 'Add the chopped onion and fry, stirring often.', '{"en": "Add the chopped onion and fry, stirring often.", "hi": {"look": "प्याज़ हल्का सुनहरा हो जाए।", "text": "कटा प्याज़ डालें और चलाते हुए भूनें।"}, "hi-Latn": {"look": "Pyaaz halka sunehra ho jaye.", "text": "Kata pyaaz daalein aur chalate hue bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 360, true, null, 'Onion turns light golden.', '{"en": "Onion turns light golden.", "heat": "medium", "look": "Onion turns light golden."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-matar'), 3, 'Add ginger garlic paste and slit green chillies and stir.', '{"en": "Add ginger garlic paste and slit green chillies and stir.", "hi": {"smell": "लहसुन की कच्ची महक चली जाए।", "text": "अदरक लहसुन का पेस्ट और बीच से कटी हरी मिर्च डालकर चलाएँ।"}, "hi-Latn": {"smell": "Lehsun ki kachchi mehak chali jaye.", "text": "Adrak lehsun ka paste aur beech se kati hari mirch daal kar chalayein."}}'::jsonb, null, 60, false, null, 'The raw garlic smell goes.', '{"en": "The raw garlic smell goes.", "heat": "medium", "smell": "The raw garlic smell goes."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-matar'), 4, 'Add chopped tomato, turmeric, red chilli powder, coriander powder and salt, and cook the masala.', '{"en": "Add chopped tomato, turmeric, red chilli powder, coriander powder and salt, and cook the masala.", "hi": {"look": "टमाटर गल जाएँ और किनारों पर तेल दिखने लगे।", "text": "कटा टमाटर, हल्दी, लाल मिर्च पाउडर, धनिया पाउडर और नमक डालकर मसाला भूनें।"}, "hi-Latn": {"look": "Tamatar gal jayein aur kinaron par tel dikhne lage.", "text": "Kata tamatar, haldi, lal mirch powder, dhaniya powder aur namak daal kar masala bhunein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 360, true, null, 'Tomatoes go soft and oil shows at the edges.', '{"en": "Tomatoes go soft and oil shows at the edges.", "heat": "medium", "look": "Tomatoes go soft and oil shows at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-matar'), 5, 'Add the potato cubes and peas and mix well with the masala.', '{"en": "Add the potato cubes and peas and mix well with the masala.", "hi": {"look": "हर टुकड़े पर मसाला लग जाए।", "text": "आलू के टुकड़े और मटर डालकर मसाले में अच्छे से मिलाएँ।"}, "hi-Latn": {"look": "Har tukde par masala lag jaye.", "text": "Aloo ke tukde aur matar daal kar masale mein achhe se milayein."}}'::jsonb, null, 120, false, null, 'Every piece is coated in masala.', '{"en": "Every piece is coated in masala.", "heat": "medium", "look": "Every piece is coated in masala."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-matar'), 6, 'Pour in about 2 cups of water, close the lid and pressure-cook.', '{"en": "Pour in about 2 cups of water, close the lid and pressure-cook.", "hi": {"safety": "ढक्कन खोलने से पहले प्रेशर अपने आप निकलने दें।", "text": "लगभग 2 कप पानी डालें, ढक्कन बंद करें और प्रेशर कुकर में पकाएँ।"}, "hi-Latn": {"safety": "Dhakkan kholne se pehle pressure apne aap nikalne dein.", "text": "Lagbhag 2 cup paani daalein, dhakkan band karein aur pressure cooker mein pakayein."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 480, true, 2, null, '{"heat": "medium"}'::jsonb, null, 'Let the pressure drop on its own before opening the lid.'),
  ((select id from public.recipes where household_id is null and slug = 'aloo-matar'), 7, 'Open, lightly mash a few potato pieces, add garam masala and simmer, then top with coriander leaves.', '{"en": "Open, lightly mash a few potato pieces, add garam masala and simmer, then top with coriander leaves.", "hi": {"look": "ग्रेवी थोड़ी गाढ़ी हो जाए।", "text": "कुकर खोलें, आलू के कुछ टुकड़े हल्का मसल दें, गरम मसाला डालकर पकाएँ, फिर हरा धनिया डालें।", "touch": "आलू चम्मच से आसानी से टूट जाए।"}, "hi-Latn": {"look": "Gravy thodi gaadhi ho jaye.", "text": "Cooker kholein, aloo ke kuch tukde halka masal dein, garam masala daal kar pakayein, phir hara dhaniya daalein.", "touch": "Aloo chammach se aasani se toot jaye."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 180, true, null, 'The gravy thickens slightly. Potato breaks easily with the spoon.', '{"en": "The gravy thickens slightly. Potato breaks easily with the spoon.", "heat": "low", "look": "The gravy thickens slightly.", "touch": "Potato breaks easily with the spoon."}'::jsonb, null, null)
