-- Recipe: aloo-methi (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('aloo-methi', 'Aloo Methi', '{"en": "Aloo Methi", "hi": "आलू मेथी", "hi-Latn": "Aloo Methi"}'::jsonb, 'A dry North Indian sabzi of potato cubes cooked with fresh fenugreek leaves, garlic and cumin. It is slightly bitter, garlicky and goes well with roti or paratha.', '{"hi": "आलू के टुकड़ों और ताज़ी मेथी की पत्तियों से बनी सूखी उत्तर भारतीय सब्ज़ी, जिसमें लहसुन और जीरा पड़ता है। हल्की कड़वाहट और लहसुन के स्वाद वाली यह सब्ज़ी रोटी या पराठे के साथ अच्छी लगती है।", "hi-Latn": "Aloo ke tukdon aur taazi methi ki pattiyon se bani sookhi North Indian sabzi, jismein lehsun aur jeera padta hai. Halki kadwahat aur lehsun ke swaad wali yeh sabzi roti ya parathe ke saath achhi lagti hai."}'::jsonb, 'north_indian', 'main', 'vegan', 4, 20, 20, 2, 2, array['kadai', 'gas_stove']::text[], array['tiffin', 'comforting']::text[], '{"acid": 0.1, "crunch": 0.1, "heat": 0.4, "rich": 0.3, "starch": 0.6, "sweet": 0}'::jsonb, array['sabzi', 'greens']::text[], 'curated', 'in_review', false)
