  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'aloo-methi') and step_no > 6;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'aloo-methi');

-- Recipe: aloo-poha (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('aloo-poha', 'Aloo Poha', '{"en": "Aloo Poha", "hi": "आलू पोहा", "hi-Latn": "Aloo Poha"}'::jsonb, 'Soft flattened rice tossed with potato, onion, mustard seeds and curry leaves, tinted yellow with turmeric and finished with lemon, coriander and crunchy peanuts. A quick weekday breakfast from Maharashtra and Madhya Pradesh.', '{"hi": "मुलायम पोहा, आलू, प्याज़, राई और करी पत्ते के साथ, हल्दी से पीला रंग, ऊपर से नींबू, हरा धनिया और कुरकुरी मूंगफली। महाराष्ट्र और मध्य प्रदेश का झटपट रोज़ का नाश्ता।", "hi-Latn": "Mulayam poha, aloo, pyaaz, rai aur curry patte ke saath, haldi se peela rang, upar se nimbu, hara dhaniya aur kurkuri moongphali. Maharashtra aur Madhya Pradesh ka jhatpat roz ka naashta."}'::jsonb, 'maharashtra_madhya_pradesh', 'breakfast', 'vegan', 4, 15, 20, 2, 2, array['kadai', 'gas_stove']::text[], array['quick', 'comforting', 'tiffin']::text[], '{"acid": 0.3, "crunch": 0.4, "heat": 0.3, "rich": 0.3, "starch": 0.7, "sweet": 0.2}'::jsonb, array['grain', 'sabzi']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
  description = excluded.description, descriptions = excluded.descriptions, cuisine_region = excluded.cuisine_region, course = excluded.course,
  diet = excluded.diet, base_servings = excluded.base_servings, prep_time_min = excluded.prep_time_min,
  cook_time_min = excluded.cook_time_min, difficulty = excluded.difficulty,
  spice_level = excluded.spice_level, equipment = excluded.equipment, tags = excluded.tags,
  flavor_profile = excluded.flavor_profile, food_groups = excluded.food_groups,
  review_status = excluded.review_status, is_published = excluded.is_published;

