  ((select id from public.recipes where household_id is null and slug = 'aloo-poha'), (select id from public.ingredients where canonical_name = 'salt'), 'salt', 6, 'g', '1 chhota chammach namak', false, null, 'spice', '[]'::jsonb, 8),
