insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'aloo-poha'), 1, 'Rinse the poha in a strainer under running water 2 to 3 times, drain well, mix in the sugar and half the salt and let it rest.', '{"en": "Rinse the poha in a strainer under running water 2 to 3 times, drain well, mix in the sugar and half the salt and let it rest.", "hi": {"text": "पोहे को छलनी में बहते पानी में 2-3 बार धोएं, पानी अच्छे से निकाल दें, उसमें चीनी और आधा नमक मिलाकर रख दें।", "touch": "हर दाना उंगलियों में दबाने पर नरम हो, पर दाने अलग-अलग रहें, गीले-चिपचिपे नहीं।"}, "hi-Latn": {"text": "Poha ko chhalni mein behte paani mein 2-3 baar dhoyein, paani achhe se nikaal dein, usmein cheeni aur aadha namak milakar rakh dein.", "touch": "Har daana ungliyon mein dabane par naram ho, par daane alag-alag rahein, geele-chipchipe nahin."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 600, true, null, 'Each flake presses soft between fingers but the grains stay separate, not mushy.', '{"en": "Each flake presses soft between fingers but the grains stay separate, not mushy.", "touch": "Each flake presses soft between fingers but the grains stay separate, not mushy."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-poha'), 2, 'Heat the oil in a kadai, fry the peanuts until golden and crunchy, then lift them out onto a plate.', '{"en": "Heat the oil in a kadai, fry the peanuts until golden and crunchy, then lift them out onto a plate.", "hi": {"look": "मूंगफली सुनहरी हो जाए, कहीं-कहीं गहरे दाग दिखें।", "safety": "गरम तेल छिटक सकता है; चेहरा दूर रखें।", "sound": "तेल में हल्की चटचट आवाज़ आए।", "text": "कड़ाही में तेल गरम करें, मूंगफली सुनहरी और कुरकुरी होने तक तलें, फिर प्लेट में निकाल लें।"}, "hi-Latn": {"look": "Moongphali sunehri ho jaaye, kahin-kahin gehre daag dikhein.", "safety": "Garam tel chhitak sakta hai; chehra door rakhein.", "sound": "Tel mein halki chatchat aawaaz aaye.", "text": "Kadai mein tel garam karein, moongphali sunehri aur kurkuri hone tak talein, phir plate mein nikaal lein."}}'::jsonb, (select id from public.techniques where slug = 'shallow_fry'), 180, true, null, 'Peanuts turn golden with darker spots. They crackle softly in the oil.', '{"en": "Peanuts turn golden with darker spots. They crackle softly in the oil.", "heat": "medium", "look": "Peanuts turn golden with darker spots.", "sound": "They crackle softly in the oil."}'::jsonb, null, 'Hot oil can spit; keep your face away.'),
  ((select id from public.recipes where household_id is null and slug = 'aloo-poha'), 3, 'In the same oil add mustard seeds; once they splutter add cumin, curry leaves and slit green chillies.', '{"en": "In the same oil add mustard seeds; once they splutter add cumin, curry leaves and slit green chillies.", "hi": {"safety": "करी पत्ते तेल में डालते ही छिटकते हैं; थोड़ा पीछे हटें।", "smell": "करी पत्तों की ताज़ी भुनी खुशबू आए।", "sound": "राई चटक-चटक कर फूटे।", "text": "उसी तेल में राई डालें; चटकने लगे तो जीरा, करी पत्ते और बीच से चीरी हरी मिर्च डालें।"}, "hi-Latn": {"safety": "Curry patte tel mein daalte hi chhitakte hain; thoda peeche hatein.", "smell": "Curry patton ki taazi bhuni khushboo aaye.", "sound": "Rai chatak-chatak kar phoote.", "text": "Usi tel mein rai daalein; chatakne lage to jeera, curry patte aur beech se cheeri hari mirch daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'Mustard seeds pop and crackle. Curry leaves smell fresh and toasty.', '{"en": "Mustard seeds pop and crackle. Curry leaves smell fresh and toasty.", "heat": "medium", "smell": "Curry leaves smell fresh and toasty.", "sound": "Mustard seeds pop and crackle."}'::jsonb, null, 'Curry leaves spatter when they hit the oil; stand back.'),
  ((select id from public.recipes where household_id is null and slug = 'aloo-poha'), 4, 'Add the chopped onion and sauté until soft and translucent.', '{"en": "Add the chopped onion and sauté until soft and translucent.", "hi": {"look": "प्याज़ पारदर्शी और चमकदार हो जाए, भूरा नहीं।", "text": "कटा प्याज़ डालें और नरम व पारदर्शी होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz paardarshi aur chamakdaar ho jaaye, bhoora nahin.", "text": "Kata pyaaz daalein aur naram va paardarshi hone tak bhoonein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 180, true, null, 'Onion turns see-through and glossy, not brown.', '{"en": "Onion turns see-through and glossy, not brown.", "heat": "medium", "look": "Onion turns see-through and glossy, not brown."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-poha'), 5, 'Add the small potato cubes, turmeric and the rest of the salt, stir, cover and cook until the potatoes are tender.', '{"en": "Add the small potato cubes, turmeric and the rest of the salt, stir, cover and cook until the potatoes are tender.", "hi": {"text": "छोटे टुकड़ों में कटे आलू, हल्दी और बचा नमक डालें, चलाएं, ढककर आलू नरम होने तक पकाएं।", "touch": "करछी से दबाने पर आलू का टुकड़ा आसानी से टूट जाए।"}, "hi-Latn": {"text": "Chhote tukdon mein kate aloo, haldi aur bacha namak daalein, chalaayein, dhakkar aloo naram hone tak pakaayein.", "touch": "Karchhi se dabaane par aloo ka tukda aasaani se toot jaaye."}}'::jsonb, null, 480, true, null, 'A potato cube breaks easily when pressed with the spatula.', '{"en": "A potato cube breaks easily when pressed with the spatula.", "heat": "low", "touch": "A potato cube breaks easily when pressed with the spatula."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-poha'), 6, 'Add the rested poha, fold gently to mix, cover and let it steam.', '{"en": "Add the rested poha, fold gently to mix, cover and let it steam.", "hi": {"look": "पोहा एक जैसा पीला हो और ढक्कन हटाने पर भाप उठे।", "text": "रखा हुआ पोहा डालें, हल्के हाथ से मिलाएं, ढककर भाप में पकने दें।"}, "hi-Latn": {"look": "Poha ek jaisa peela ho aur dhakkan hataane par bhaap uthe.", "text": "Rakha hua poha daalein, halke haath se milaayein, dhakkar bhaap mein pakne dein."}}'::jsonb, (select id from public.techniques where slug = 'steam'), 180, true, null, 'Poha is evenly yellow and steam rises when you lift the lid.', '{"en": "Poha is evenly yellow and steam rises when you lift the lid.", "heat": "low", "look": "Poha is evenly yellow and steam rises when you lift the lid."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'aloo-poha'), 7, 'Turn off the heat, squeeze in the lemon, add coriander and the fried peanuts, toss and serve hot.', '{"en": "Turn off the heat, squeeze in the lemon, add coriander and the fried peanuts, toss and serve hot.", "hi": {"text": "आंच बंद करें, नींबू निचोड़ें, हरा धनिया और तली मूंगफली डालें, मिलाएं और गरम-गरम परोसें।"}, "hi-Latn": {"text": "Aanch band karein, nimbu nichodein, hara dhaniya aur tali moongphali daalein, milaayein aur garam-garam parosein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
