  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('baingan-bharta', 'Baingan Bharta', '{"en": "Baingan Bharta", "hi": "बैंगन भर्ता", "hi-Latn": "Baingan Bharta"}'::jsonb, 'Smoky flame-roasted brinjal mashed and cooked with onion, tomato, garlic and green chilli in mustard oil. A Punjabi weekday sabzi to eat with hot rotis.', '{"hi": "आग पर भुने धुएँदार बैंगन को मैश करके सरसों के तेल में प्याज़, टमाटर, लहसुन और हरी मिर्च के साथ पकाया जाता है। गरम रोटी के साथ खाने वाली पंजाबी रोज़ की सब्ज़ी।", "hi-Latn": "Aag par bhune dhuandaar baingan ko mash karke sarson ke tel mein pyaaz, tamatar, lehsun aur hari mirch ke saath pakaya jaata hai. Garam roti ke saath khaane wali Punjabi roz ki sabzi."}'::jsonb, 'punjabi', 'main', 'veg', 4, 10, 35, 2, 3, array['gas_stove', 'kadai']::text[], array['comforting']::text[], '{"acid": 0.3, "crunch": 0, "heat": 0.5, "rich": 0.4, "starch": 0.2, "sweet": 0.1}'::jsonb, array['sabzi']::text[], 'curated', 'in_review', false)
