insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'baingan-bharta'), 1, 'Wash and dry the brinjal, rub a few drops of oil on it, make 4 small slits and push 4 garlic cloves inside, then roast it directly on the gas flame, turning with tongs until charred all over.', '{"en": "Wash and dry the brinjal, rub a few drops of oil on it, make 4 small slits and push 4 garlic cloves inside, then roast it directly on the gas flame, turning with tongs until charred all over.", "hi": {"look": "छिलका हर तरफ़ से काला और फफोलेदार हो जाए और बैंगन सिकुड़कर ढीला पड़ जाए।", "safety": "बैंगन चिमटे से पलटें, उँगलियों से नहीं, और दुपट्टा या बाँह आँच से दूर रखें।", "smell": "धुएँदार खुशबू आने लगे।", "text": "बैंगन धोकर सुखा लें, उस पर कुछ बूँद तेल लगाएँ, 4 छोटे चीरे लगाकर 4 लहसुन की कलियाँ अंदर डालें, फिर सीधे गैस की आँच पर चिमटे से घुमाते हुए चारों तरफ़ से काला होने तक भूनें।", "touch": "सबसे मोटे हिस्से में चाकू बिना रुकावट के घुस जाए।"}, "hi-Latn": {"look": "Chhilka har taraf se kaala aur phapholedaar ho jaaye aur baingan sikudkar dheela pad jaaye.", "safety": "Baingan chimte se palatein, ungliyon se nahin, aur dupatta ya baanh aanch se door rakhein.", "smell": "Dhuandaar khushboo aane lage.", "text": "Baingan dhokar sukha lein, us par kuch boond tel lagayein, 4 chhote cheere lagakar 4 lehsun ki kaliyan andar daalein, phir seedhe gas ki aanch par chimte se ghumate hue chaaron taraf se kaala hone tak bhunein.", "touch": "Sabse mote hisse mein chaaku bina rukawat ke ghus jaaye."}}'::jsonb, null, 900, true, null, 'The skin is black and blistered everywhere and the brinjal has shrunk and collapsed. It smells smoky. A knife goes through the thickest part with no resistance.', '{"en": "The skin is black and blistered everywhere and the brinjal has shrunk and collapsed. It smells smoky. A knife goes through the thickest part with no resistance.", "heat": "medium", "look": "The skin is black and blistered everywhere and the brinjal has shrunk and collapsed.", "smell": "It smells smoky.", "touch": "A knife goes through the thickest part with no resistance."}'::jsonb, null, 'Turn the brinjal with tongs, not your fingers, and keep the dupatta or sleeves away from the flame.'),
  ((select id from public.recipes where household_id is null and slug = 'baingan-bharta'), 2, 'Cover the roasted brinjal in a bowl for 5 minutes, then peel off the burnt skin, remove the stem and mash the pulp with the roasted garlic.', '{"en": "Cover the roasted brinjal in a bowl for 5 minutes, then peel off the burnt skin, remove the stem and mash the pulp with the roasted garlic.", "hi": {"look": "गूदा नरम और मलाईदार हो, उसमें थोड़े धुएँदार छिलके के टुकड़े दिखें।", "safety": "अंदर से बैंगन बहुत गरम रहता है, इसलिए छीलने से पहले थोड़ा ठंडा होने दें।", "text": "भुने बैंगन को एक कटोरे में 5 मिनट ढककर रखें, फिर जला छिलका उतारें, डंठल हटाएँ और गूदे को भुने लहसुन के साथ मैश कर लें।"}, "hi-Latn": {"look": "Gudda naram aur malaidaar ho, usmein thode dhuandaar chhilke ke tukde dikhein.", "safety": "Andar se baingan bahut garam rehta hai, isliye chheelne se pehle thoda thanda hone dein.", "text": "Bhune baingan ko ek katore mein 5 minute dhakkar rakhein, phir jala chhilka utaarein, danthal hatayein aur gudde ko bhune lehsun ke saath mash kar lein."}}'::jsonb, null, 300, true, null, 'The pulp is soft, creamy and flecked with a little smoky skin.', '{"en": "The pulp is soft, creamy and flecked with a little smoky skin.", "look": "The pulp is soft, creamy and flecked with a little smoky skin."}'::jsonb, null, 'The inside stays very hot, so let it cool a little before peeling.'),
  ((select id from public.recipes where household_id is null and slug = 'baingan-bharta'), 3, 'Heat the mustard oil in a kadai until it smokes lightly, lower the heat a little and add the cumin seeds and the remaining garlic, finely chopped.', '{"en": "Heat the mustard oil in a kadai until it smokes lightly, lower the heat a little and add the cumin seeds and the remaining garlic, finely chopped.", "hi": {"look": "लहसुन हल्का सुनहरा हो जाए।", "sound": "जीरा चटकने लगे।", "text": "कड़ाही में सरसों का तेल हल्का धुआँ उठने तक गरम करें, आँच थोड़ी कम करें और जीरा व बचा हुआ बारीक कटा लहसुन डालें।"}, "hi-Latn": {"look": "Lehsun halka sunehra ho jaaye.", "sound": "Jeera chatakne lage.", "text": "Kadai mein sarson ka tel halka dhuan uthne tak garam karein, aanch thodi kam karein aur jeera va bacha hua bareek kata lehsun daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 120, false, null, 'The garlic turns light golden. The cumin crackles.', '{"en": "The garlic turns light golden. The cumin crackles.", "heat": "medium", "look": "The garlic turns light golden.", "sound": "The cumin crackles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'baingan-bharta'), 4, 'Add the onion, ginger and green chilli and sauté until the onion is golden.', '{"en": "Add the onion, ginger and green chilli and sauté until the onion is golden.", "hi": {"look": "प्याज़ नरम और सुनहरा हो जाए।", "text": "प्याज़, अदरक और हरी मिर्च डालें और प्याज़ सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram aur sunehra ho jaaye.", "text": "Pyaaz, adrak aur hari mirch daalein aur pyaaz sunehra hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 300, true, null, 'The onion turns soft and golden.', '{"en": "The onion turns soft and golden.", "heat": "medium", "look": "The onion turns soft and golden."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'baingan-bharta'), 5, 'Add the tomato, turmeric, red chilli powder, coriander powder and salt, and cook, stirring, until the tomato breaks down.', '{"en": "Add the tomato, turmeric, red chilli powder, coriander powder and salt, and cook, stirring, until the tomato breaks down.", "hi": {"look": "टमाटर गल जाए और किनारों पर तेल दिखने लगे।", "text": "टमाटर, हल्दी, लाल मिर्च पाउडर, धनिया पाउडर और नमक डालें और चलाते हुए टमाटर गलने तक पकाएँ।"}, "hi-Latn": {"look": "Tamatar gal jaaye aur kinaaron par tel dikhne lage.", "text": "Tamatar, haldi, laal mirch powder, dhaniya powder aur namak daalein aur chalaate hue tamatar galne tak pakayein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 420, true, null, 'The tomato turns mushy and oil shows at the edges.', '{"en": "The tomato turns mushy and oil shows at the edges.", "heat": "medium", "look": "The tomato turns mushy and oil shows at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'baingan-bharta'), 6, 'Add the mashed brinjal and cook, mashing and stirring, so it soaks up the masala; sprinkle garam masala if using.', '{"en": "Add the mashed brinjal and cook, mashing and stirring, so it soaks up the masala; sprinkle garam masala if using.", "hi": {"look": "भर्ता गाढ़ा, अच्छी तरह मिला हुआ और चमकदार दिखे।", "text": "मैश किया बैंगन डालें और दबाते-चलाते हुए पकाएँ ताकि मसाला अच्छे से मिल जाए; चाहें तो गरम मसाला छिड़कें।"}, "hi-Latn": {"look": "Bharta gaadha, achhi tarah mila hua aur chamakdaar dikhe.", "text": "Mash kiya baingan daalein aur dabaate-chalaate hue pakayein taaki masala achhe se mil jaaye; chahein to garam masala chhidkein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 360, true, null, 'The bharta is thick, well blended and glossy.', '{"en": "The bharta is thick, well blended and glossy.", "heat": "low", "look": "The bharta is thick, well blended and glossy."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'baingan-bharta'), 7, 'Turn off the heat, top with chopped coriander leaves and serve hot with roti.', '{"en": "Turn off the heat, top with chopped coriander leaves and serve hot with roti.", "hi": {"text": "आँच बंद करें, ऊपर से कटा हरा धनिया डालें और रोटी के साथ गरम परोसें।"}, "hi-Latn": {"text": "Aanch band karein, upar se kata hara dhaniya daalein aur roti ke saath garam parosein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
