-- Recipe: beans-poriyal (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('beans-poriyal', 'Beans Poriyal', '{"en": "Beans Poriyal", "hi": "बीन्स पोरियल", "hi-Latn": "Beans Poriyal"}'::jsonb, 'A South Indian dry stir-fry of finely chopped french beans. They are tempered with mustard seeds, urad dal and curry leaves and finished with fresh grated coconut. It goes with rice and sambar or rasam.', '{"hi": "बारीक कटी फ्रेंच बीन्स की दक्षिण भारतीय सूखी सब्ज़ी। इसमें राई, उड़द दाल और करी पत्ते का तड़का लगता है और ऊपर से ताज़ा कसा नारियल डलता है। चावल के साथ सांभर या रसम के संग परोसें।", "hi-Latn": "Baarik kati french beans ki South Indian sookhi sabzi. Isme rai, urad dal aur curry patte ka tadka lagta hai aur upar se taaza kasa nariyal padta hai. Chawal ke saath sambar ya rasam ke sang parosein."}'::jsonb, 'tamil_nadu', 'side', 'vegan', 4, 15, 15, 1, 2, array['kadai', 'gas_stove']::text[], array['quick', 'light', 'tiffin']::text[], '{"acid": 0, "crunch": 0.4, "heat": 0.2, "rich": 0.3, "starch": 0.1, "sweet": 0.1}'::jsonb, array['sabzi']::text[], 'curated', 'in_review', false)
