insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'beans-poriyal'), 1, 'Wash the beans, trim both ends and chop them finely into small rounds. Chop the onion finely if you are using it.', '{"en": "Wash the beans, trim both ends and chop them finely into small rounds. Chop the onion finely if you are using it.", "hi": {"text": "बीन्स धोकर दोनों सिरे काट दें और बारीक छोटे टुकड़ों में काट लें। प्याज़ डाल रहे हैं तो उसे भी बारीक काट लें।"}, "hi-Latn": {"text": "Beans dhokar dono sire kaat dein aur baarik chhote tukdon mein kaat lein. Pyaaz daal rahe hain to use bhi baarik kaat lein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'beans-poriyal'), 2, 'Heat oil in a kadai and add the mustard seeds. When they splutter, add the urad dal and fry until golden. Then add the dry red chillies, curry leaves and asafoetida.', '{"en": "Heat oil in a kadai and add the mustard seeds. When they splutter, add the urad dal and fry until golden. Then add the dry red chillies, curry leaves and asafoetida.", "hi": {"look": "उड़द दाल हल्की सुनहरी हो जाती है।", "safety": "गरम तेल में करी पत्ते छिटकते हैं, इसलिए डालते समय थोड़ा पीछे रहें।", "smell": "करी पत्तों की खुशबू आती है।", "sound": "राई चटकती है।", "text": "कढ़ाई में तेल गरम करें और राई डालें। राई चटकने लगे तो उड़द दाल डालकर सुनहरी होने तक भूनें। फिर सूखी लाल मिर्च, करी पत्ते और हींग डालें।"}, "hi-Latn": {"look": "Urad dal halki sunehri ho jaati hai.", "safety": "Garam tel mein curry patte chhitakte hain, isliye daalte samay thoda peeche rahein.", "smell": "Curry patton ki khushboo aati hai.", "sound": "Rai chatakti hai.", "text": "Kadai mein tel garam karein aur rai daalein. Rai chatakne lage to urad dal daalkar sunehri hone tak bhunein. Phir sookhi laal mirch, curry patte aur hing daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The urad dal turns light golden. The mustard seeds crackle. The curry leaves smell fragrant.', '{"en": "The urad dal turns light golden. The mustard seeds crackle. The curry leaves smell fragrant.", "heat": "medium", "look": "The urad dal turns light golden.", "smell": "The curry leaves smell fragrant.", "sound": "The mustard seeds crackle."}'::jsonb, null, 'Curry leaves spit in hot oil, so stand back when you add them.'),
  ((select id from public.recipes where household_id is null and slug = 'beans-poriyal'), 3, 'Add the onion and sauté until it is soft.', '{"en": "Add the onion and sauté until it is soft.", "hi": {"look": "प्याज़ नरम और पारदर्शी हो जाता है।", "text": "प्याज़ डालें और नरम होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram aur transparent ho jaata hai.", "text": "Pyaaz daalein aur naram hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 120, false, null, 'The onion turns soft and translucent.', '{"en": "The onion turns soft and translucent.", "heat": "medium", "look": "The onion turns soft and translucent."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'beans-poriyal'), 4, 'Add the beans, turmeric and salt and mix well. Sprinkle 3 to 4 tablespoons of water, cover and cook on low heat. Stir once in between.', '{"en": "Add the beans, turmeric and salt and mix well. Sprinkle 3 to 4 tablespoons of water, cover and cook on low heat. Stir once in between.", "hi": {"text": "बीन्स, हल्दी और नमक डालकर अच्छे से मिलाएँ। 3 से 4 बड़े चम्मच पानी छिड़कें, ढककर धीमी आँच पर पकाएँ। बीच में एक बार चलाएँ।", "touch": "बीन्स दबाने पर आसानी से दबती है पर हल्की कुरकुरी रहती है।"}, "hi-Latn": {"text": "Beans, haldi aur namak daalkar achhe se milayein. 3 se 4 bade chammach paani chhidkein, dhakkar dheemi aanch par pakayein. Beech mein ek baar chalayein.", "touch": "Beans dabane par aasani se dabti hai par halki kurkuri rehti hai."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 600, true, null, 'A bean presses easily but still has a slight bite.', '{"en": "A bean presses easily but still has a slight bite.", "heat": "low", "touch": "A bean presses easily but still has a slight bite."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'beans-poriyal'), 5, 'Uncover the kadai and stir until any leftover water dries up.', '{"en": "Uncover the kadai and stir until any leftover water dries up.", "hi": {"look": "कढ़ाई के तले में पानी नहीं बचता।", "text": "ढक्कन हटाएँ और बचा हुआ पानी सूखने तक चलाते रहें।"}, "hi-Latn": {"look": "Kadai ke tale mein paani nahi bachta.", "text": "Dhakkan hatayein aur bacha hua paani sookhne tak chalate rahein."}}'::jsonb, null, 120, false, null, 'No water is left at the bottom of the kadai.', '{"en": "No water is left at the bottom of the kadai.", "heat": "medium", "look": "No water is left at the bottom of the kadai."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'beans-poriyal'), 6, 'Add the grated coconut and mix for a minute, then switch off the heat. Serve hot.', '{"en": "Add the grated coconut and mix for a minute, then switch off the heat. Serve hot.", "hi": {"smell": "हल्के भुने नारियल की खुशबू आती है।", "text": "कसा नारियल डालकर एक मिनट मिलाएँ, फिर गैस बंद कर दें। गरम परोसें।"}, "hi-Latn": {"smell": "Halke bhune nariyal ki khushboo aati hai.", "text": "Kasa nariyal daalkar ek minute milayein, phir gas band kar dein. Garam parosein."}}'::jsonb, null, 60, false, null, 'It smells of toasted coconut.', '{"en": "It smells of toasted coconut.", "heat": "low", "smell": "It smells of toasted coconut."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
