-- Recipe: bhindi-masala (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('bhindi-masala', 'Bhindi Masala', '{"en": "Bhindi Masala", "hi": "भिंडी मसाला", "hi-Latn": "Bhindi Masala"}'::jsonb, 'A weekday dry okra sabzi. The bhindi is first fried until it is no longer slimy, then tossed in a quick onion-tomato masala and finished with amchur. It goes well with phulka or dal-chawal.', '{"hi": "रोज़ के खाने वाली सूखी भिंडी की सब्ज़ी। भिंडी को पहले तब तक भूनते हैं जब तक उसकी चिपचिपाहट न चली जाए, फिर प्याज़-टमाटर के मसाले में मिलाकर अमचूर से खत्म करते हैं। फुलके या दाल-चावल के साथ बढ़िया लगती है।", "hi-Latn": "Roz ke khaane wali sookhi bhindi ki sabzi. Bhindi ko pehle tab tak bhoonte hain jab tak uski chipchipahat na chali jaaye, phir pyaaz-tamatar ke masale mein milaakar amchur se khatam karte hain. Phulke ya dal-chawal ke saath badhiya lagti hai."}'::jsonb, 'north_indian', 'main', 'veg', 4, 15, 25, 2, 3, array['kadai', 'gas_stove']::text[], array['tiffin', 'comforting']::text[], '{"acid": 0.3, "crunch": 0.3, "heat": 0.4, "rich": 0.3, "starch": 0.1, "sweet": 0}'::jsonb, array['sabzi']::text[], 'curated', 'in_review', false)
