insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'bhindi-masala'), 1, 'Wash the okra, wipe every piece completely dry with a cloth, trim the ends and cut it into 2 cm pieces.', '{"en": "Wash the okra, wipe every piece completely dry with a cloth, trim the ends and cut it into 2 cm pieces.", "hi": {"safety": "सूखा बोर्ड लें और चाकू ध्यान से चलाएँ, क्योंकि गीली भिंडी फिसलती है।", "text": "भिंडी धो लें, हर भिंडी को कपड़े से पूरा सूखा पोंछें, सिरे काटें और 2 सेंटीमीटर के टुकड़े कर लें।", "touch": "काटने से पहले भिंडी पूरी सूखी लगनी चाहिए, इससे वह कम चिपचिपी रहती है।"}, "hi-Latn": {"safety": "Sookha board lein aur chaaku dhyaan se chalaayein, kyunki geeli bhindi phisalti hai.", "text": "Bhindi dho lein, har bhindi ko kapde se poora sookha ponchhein, sire kaatein aur 2 centimetre ke tukde kar lein.", "touch": "Kaatne se pehle bhindi poori sookhi lagni chahiye, isse woh kam chipchipi rehti hai."}}'::jsonb, null, 600, true, null, 'The okra should feel fully dry before you cut it, so it stays less slimy.', '{"en": "The okra should feel fully dry before you cut it, so it stays less slimy.", "touch": "The okra should feel fully dry before you cut it, so it stays less slimy."}'::jsonb, null, 'Use a dry board and take care with the knife, because wet okra slips.'),
  ((select id from public.recipes where household_id is null and slug = 'bhindi-masala'), 2, 'Heat 2 tablespoons of oil in a kadai. Add the okra and fry it uncovered, stirring now and then, until it is no longer slimy and the edges brown. Take it out onto a plate.', '{"en": "Heat 2 tablespoons of oil in a kadai. Add the okra and fry it uncovered, stirring now and then, until it is no longer slimy and the edges brown. Take it out onto a plate.", "hi": {"look": "चिपचिपे तार खत्म हो जाएँ और किनारे हल्के भूरे हो जाएँ।", "text": "कड़ाही में 2 बड़े चम्मच तेल गरम करें। भिंडी डालें और बिना ढके, बीच-बीच में चलाते हुए तब तक भूनें जब तक चिपचिपाहट न चली जाए और किनारे भूरे न हो जाएँ। फिर भिंडी निकालकर प्लेट में रख लें।"}, "hi-Latn": {"look": "Chipchipe taar khatam ho jaayein aur kinaare halke bhoore ho jaayein.", "text": "Kadai mein 2 bade chammach tel garam karein. Bhindi daalein aur bina dhake, beech-beech mein chalaate hue tab tak bhoonein jab tak chipchipahat na chali jaaye aur kinaare bhoore na ho jaayein. Phir bhindi nikaal kar plate mein rakh lein."}}'::jsonb, (select id from public.techniques where slug = 'shallow_fry'), 720, true, null, 'The sticky strings are gone and the edges are lightly browned.', '{"en": "The sticky strings are gone and the edges are lightly browned.", "heat": "medium", "look": "The sticky strings are gone and the edges are lightly browned."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'bhindi-masala'), 3, 'Add the remaining oil to the same kadai and put in the cumin seeds. When they crackle, add the sliced onion and cook it until golden.', '{"en": "Add the remaining oil to the same kadai and put in the cumin seeds. When they crackle, add the sliced onion and cook it until golden.", "hi": {"look": "प्याज़ नरम होकर सुनहरा भूरा हो जाए।", "sound": "जीरा चटकने लगे।", "text": "उसी कड़ाही में बचा हुआ तेल डालें और जीरा डालें। जीरा चटकने लगे तो कटा प्याज़ डालें और सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram hokar sunehra bhoora ho jaaye.", "sound": "Jeera chatakne lage.", "text": "Usi kadai mein bacha hua tel daalein aur jeera daalein. Jeera chatakne lage to kata pyaaz daalein aur sunehra hone tak bhoonein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 360, true, null, 'The onion turns soft and golden brown. The cumin seeds crackle.', '{"en": "The onion turns soft and golden brown. The cumin seeds crackle.", "heat": "medium", "look": "The onion turns soft and golden brown.", "sound": "The cumin seeds crackle."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'bhindi-masala'), 4, 'Add the ginger garlic paste and the slit green chillies, and stir for about a minute.', '{"en": "Add the ginger garlic paste and the slit green chillies, and stir for about a minute.", "hi": {"smell": "लहसुन की कच्ची महक चली जाए।", "text": "अदरक-लहसुन का पेस्ट और बीच से चीरी हुई हरी मिर्च डालें और करीब एक मिनट तक चलाएँ।"}, "hi-Latn": {"smell": "Lehsun ki kachchi mehak chali jaaye.", "text": "Adrak-lehsun ka paste aur beech se cheeri hui hari mirch daalein aur kareeb ek minute tak chalaayein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 60, false, null, 'The raw smell of the garlic goes away.', '{"en": "The raw smell of the garlic goes away.", "heat": "medium", "smell": "The raw smell of the garlic goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'bhindi-masala'), 5, 'Add the chopped tomato, turmeric, red chilli powder, coriander powder and salt. Cook the masala until the tomato breaks down and the oil separates.', '{"en": "Add the chopped tomato, turmeric, red chilli powder, coriander powder and salt. Cook the masala until the tomato breaks down and the oil separates.", "hi": {"look": "टमाटर गल जाए और मसाले के किनारों पर तेल दिखने लगे।", "text": "कटा टमाटर, हल्दी, लाल मिर्च पाउडर, धनिया पाउडर और नमक डालें। मसाले को तब तक भूनें जब तक टमाटर गल न जाए और तेल अलग न होने लगे।"}, "hi-Latn": {"look": "Tamatar gal jaaye aur masale ke kinaaron par tel dikhne lage.", "text": "Kata tamatar, haldi, laal mirch powder, dhaniya powder aur namak daalein. Masale ko tab tak bhoonein jab tak tamatar gal na jaaye aur tel alag na hone lage."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 360, true, null, 'The tomato turns mushy and oil shows at the edges of the masala.', '{"en": "The tomato turns mushy and oil shows at the edges of the masala.", "heat": "medium", "look": "The tomato turns mushy and oil shows at the edges of the masala."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'bhindi-masala'), 6, 'Put the fried okra back in the kadai and mix it gently with the masala. Cook uncovered until the okra is tender.', '{"en": "Put the fried okra back in the kadai and mix it gently with the masala. Cook uncovered until the okra is tender.", "hi": {"look": "मसाला भिंडी के हर टुकड़े पर लिपट जाए।", "text": "भुनी हुई भिंडी वापस कड़ाही में डालें और मसाले में हल्के हाथ से मिलाएँ। बिना ढके तब तक पकाएँ जब तक भिंडी नरम न हो जाए।", "touch": "चम्मच से दबाने पर भिंडी का टुकड़ा नरम लगे।"}, "hi-Latn": {"look": "Masala bhindi ke har tukde par lipat jaaye.", "text": "Bhuni hui bhindi wapas kadai mein daalein aur masale mein halke haath se milaayein. Bina dhake tab tak pakaayein jab tak bhindi naram na ho jaaye.", "touch": "Chammach se dabaane par bhindi ka tukda naram lage."}}'::jsonb, null, 300, true, null, 'The masala coats every piece of okra. A piece of okra feels soft when you press it with the spoon.', '{"en": "The masala coats every piece of okra. A piece of okra feels soft when you press it with the spoon.", "heat": "low", "look": "The masala coats every piece of okra.", "touch": "A piece of okra feels soft when you press it with the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'bhindi-masala'), 7, 'Sprinkle the amchur and garam masala over the okra, mix once and turn off the heat. Garnish with coriander leaves and serve hot.', '{"en": "Sprinkle the amchur and garam masala over the okra, mix once and turn off the heat. Garnish with coriander leaves and serve hot.", "hi": {"smell": "कड़ाही से खट्टी-मसालेदार खुशबू उठे।", "text": "ऊपर से अमचूर और गरम मसाला छिड़कें, एक बार मिलाएँ और आँच बंद कर दें। हरा धनिया डालकर गरमागरम परोसें।"}, "hi-Latn": {"smell": "Kadai se khatti-masaledaar khushboo uthe.", "text": "Upar se amchur aur garam masala chhidkein, ek baar milaayein aur aanch band kar dein. Hara dhaniya daal kar garamagaram parosein."}}'::jsonb, null, 60, false, null, 'A tangy, spicy aroma rises from the kadai.', '{"en": "A tangy, spicy aroma rises from the kadai.", "heat": "low", "smell": "A tangy, spicy aroma rises from the kadai."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'bhindi-masala') and step_no > 7;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'bhindi-masala');

-- Recipe: boiled-chana (draft, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('boiled-chana', 'Boiled Chana', '{"en": "Boiled Chana", "hi": "उबले छोले", "hi-Latn": "Ubale Chole"}'::jsonb, 'Soak and pressure-cook a big batch on Sunday. Kept in the fridge (three days) or frozen in portions, it turns a weekday chole, rajma or chaat into a half-hour job.', '{"hi": "रविवार को एक बड़ा बैच भिगोकर कुकर में उबाल लें। फ़्रिज में (तीन दिन) या हिस्सों में जमाकर रखें, तो हफ़्ते में छोले, राजमा या चाट आधे घंटे का काम है।", "hi-Latn": "Ravivaar ko ek bada batch bhigo kar cooker mein ubaal lein. Fridge mein (teen din) ya hisson mein jama kar rakhein, to hafte mein chole, rajma ya chaat aadhe ghante ka kaam hai."}'::jsonb, 'generic_north', 'component', 'vegan', 8, 480, 35, 1, 1, array['pressure_cooker']::text[], array['basics', 'high_protein']::text[], '{"acid": 0, "crunch": 0, "heat": 0, "rich": 0.3, "starch": 0.6, "sweet": 0}'::jsonb, array['dal', 'protein']::text[], 'curated', 'draft', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
  description = excluded.description, descriptions = excluded.descriptions, cuisine_region = excluded.cuisine_region, course = excluded.course,
  diet = excluded.diet, base_servings = excluded.base_servings, prep_time_min = excluded.prep_time_min,
  cook_time_min = excluded.cook_time_min, difficulty = excluded.difficulty,
  spice_level = excluded.spice_level, equipment = excluded.equipment, tags = excluded.tags,
  flavor_profile = excluded.flavor_profile, food_groups = excluded.food_groups,
  review_status = excluded.review_status, is_published = excluded.is_published;

delete from public.recipe_ingredients where recipe_id = (select id from public.recipes where household_id is null and slug = 'boiled-chana');
insert into public.recipe_ingredients (recipe_id, ingredient_id, display_name, quantity, unit, local_measure,
  is_optional, group_name, role, substitutes, sort_order) values
  ((select id from public.recipes where household_id is null and slug = 'boiled-chana'), (select id from public.ingredients where canonical_name = 'chickpeas'), 'chickpeas', 500, 'g', '4 katori chana', false, null, 'protein', jsonb_build_array(jsonb_build_object('ingredient_id', (select id from public.ingredients where canonical_name = 'kidney beans'), 'ingredient', 'kidney beans', 'ratio', 1, 'note', 'rajma needs a few more whistles')), 0),
  ((select id from public.recipes where household_id is null and slug = 'boiled-chana'), (select id from public.ingredients where canonical_name = 'salt'), 'salt', 6, 'g', '1 chhota chammach', false, null, 'spice', '[]'::jsonb, 1);

insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'boiled-chana'), 1, 'Rinse the chana and soak in plenty of water overnight.', '{"en": "Rinse the chana and soak in plenty of water overnight.", "hi": {"look": "दुगने हो जाएँ और छिलका चिकना और कसा दिखे।", "text": "चने धोकर रात भर ढेर सारे पानी में भिगो दें।"}, "hi-Latn": {"look": "Dugne ho jaayein aur chhilka chikna aur kasa dikhe.", "text": "Chane dho kar raat bhar dher saare paani mein bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 28800, false, null, 'They double in size and the skins look smooth and tight.', '{"en": "They double in size and the skins look smooth and tight.", "look": "They double in size and the skins look smooth and tight."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'boiled-chana'), 2, 'Drain, add fresh water to cover by two fingers and the salt, and pressure-cook for 6 whistles (rajma 8), then let the pressure drop by itself.', '{"en": "Drain, add fresh water to cover by two fingers and the salt, and pressure-cook for 6 whistles (rajma 8), then let the pressure drop by itself.", "hi": {"safety": "राजमा पूरी तरह नरम होना चाहिए; कच्चा राजमा खाना सुरक्षित नहीं। प्रेशर उतरने पर ही कुकर खोलें।", "sound": "सीटियाँ गिनें, फिर प्रेशर उतरने तक रुकें।", "text": "पानी निकालें, दो उँगली ऊपर तक ताज़ा पानी और नमक डालें, और 6 सीटी (राजमा 8) लगाएँ, फिर प्रेशर अपने आप उतरने दें।", "touch": "दो उँगलियों के बीच दबाने पर आसानी से मसल जाए।"}, "hi-Latn": {"safety": "Rajma poori tarah naram hona chahiye; kachcha rajma khaana surakshit nahi. Pressure utarne par hi cooker kholein.", "sound": "Seetiyaan ginein, phir pressure utarne tak rukein.", "text": "Paani nikaalein, do ungli upar tak taaza paani aur namak daalein, aur 6 seeti (rajma 8) lagaayein, phir pressure apne aap utarne dein.", "touch": "Do ungliyon ke beech dabaane par aasaani se masal jaaye."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 2100, false, 6, 'Count the whistles, then wait for the pressure to drop. One pressed between two fingers mashes easily.', '{"en": "Count the whistles, then wait for the pressure to drop. One pressed between two fingers mashes easily.", "heat": "medium", "sound": "Count the whistles, then wait for the pressure to drop.", "touch": "One pressed between two fingers mashes easily."}'::jsonb, null, 'Rajma must be fully soft; undercooked kidney beans are unsafe to eat. Open the cooker only when the pressure has dropped.'),
  ((select id from public.recipes where household_id is null and slug = 'boiled-chana'), 3, 'Cool, then keep with a little of the cooking water in closed boxes in the fridge, or freeze in portions.', '{"en": "Cool, then keep with a little of the cooking water in closed boxes in the fridge, or freeze in portions.", "hi": {"safety": "फ़्रिज में 3 दिन, फ़्रीज़र में एक महीना चलता है।", "text": "ठंडा करें, फिर थोड़े पकने वाले पानी के साथ बंद डिब्बों में फ़्रिज में रखें, या हिस्सों में जमा दें।", "touch": "फ़्रिज में रखने से पहले ठंडा हो।"}, "hi-Latn": {"safety": "Fridge mein 3 din, freezer mein ek mahina chalta hai.", "text": "Thanda karein, phir thode pakne waale paani ke saath band dibbon mein fridge mein rakhein, ya hisson mein jama dein.", "touch": "Fridge mein rakhne se pehle thanda ho."}}'::jsonb, null, 900, false, null, 'Cool before the boxes go in the fridge.', '{"en": "Cool before the boxes go in the fridge.", "touch": "Cool before the boxes go in the fridge."}'::jsonb, null, 'Keeps 3 days in the fridge or a month frozen.')
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'boiled-chana') and step_no > 3;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'boiled-chana');

-- Recipe: bread-upma (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('bread-upma', 'Bread Upma', '{"en": "Bread Upma", "hi": "ब्रेड उपमा", "hi-Latn": "Bread Upma"}'::jsonb, 'A quick South Indian style breakfast where cubes of bread are tossed in a tangy tomato-onion masala with a mustard seed, dal and curry leaf tadka, finished with lemon and coriander.', '{"hi": "झटपट बनने वाला दक्षिण भारतीय अंदाज़ का नाश्ता, जिसमें ब्रेड के टुकड़ों को राई, दाल और करी पत्ते के तड़के वाले खट्टे टमाटर-प्याज़ मसाले में मिलाया जाता है और ऊपर से नींबू और धनिया डाला जाता है।", "hi-Latn": "Jhatpat banne wala South Indian style nashta, jismein bread ke tukdon ko rai, dal aur curry patte ke tadke wale khatte tamatar-pyaaz masale mein milaya jaata hai aur upar se nimbu aur dhaniya daala jaata hai."}'::jsonb, 'south_indian', 'breakfast', 'veg', 4, 10, 15, 1, 2, array['kadai', 'gas_stove']::text[], array['quick', 'tiffin']::text[], '{"acid": 0.4, "crunch": 0.2, "heat": 0.4, "rich": 0.3, "starch": 0.6, "sweet": 0.1}'::jsonb, array['grain', 'sabzi']::text[], 'curated', 'in_review', false)
