insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'bread-upma'), 1, 'Cut the bread slices into small bite-size cubes; finely chop the onion, tomato, green chilli and ginger.', '{"en": "Cut the bread slices into small bite-size cubes; finely chop the onion, tomato, green chilli and ginger.", "hi": {"text": "ब्रेड स्लाइस को छोटे-छोटे टुकड़ों में काट लें; प्याज़, टमाटर, हरी मिर्च और अदरक बारीक काट लें।"}, "hi-Latn": {"text": "Bread slice ko chhote-chhote tukdon mein kaat lein; pyaaz, tamatar, hari mirch aur adrak bareek kaat lein."}}'::jsonb, null, 300, true, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'bread-upma'), 2, 'Heat the oil in a kadai, add mustard seeds, then urad dal, chana dal and curry leaves.', '{"en": "Heat the oil in a kadai, add mustard seeds, then urad dal, chana dal and curry leaves.", "hi": {"look": "दालें हल्की सुनहरी हो जाएँ।", "safety": "गरम तेल में करी पत्ते छिटकते हैं, डालते समय थोड़ा पीछे रहें।", "sound": "राई चटकने लगे और करी पत्ते छनछनाएँ।", "text": "कड़ाही में तेल गरम करें, राई डालें, फिर उड़द दाल, चना दाल और करी पत्ते डालें।"}, "hi-Latn": {"look": "Dalein halki sunehri ho jaayein.", "safety": "Garam tel mein curry patte chhitakte hain, daalte samay thoda peeche rahein.", "sound": "Rai chatakne lage aur curry patte chhanchhanaayein.", "text": "Kadai mein tel garam karein, rai daalein, phir urad dal, chana dal aur curry patte daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 120, false, null, 'The dals turn light golden. The mustard seeds crackle and the curry leaves splutter.', '{"en": "The dals turn light golden. The mustard seeds crackle and the curry leaves splutter.", "heat": "medium", "look": "The dals turn light golden.", "sound": "The mustard seeds crackle and the curry leaves splutter."}'::jsonb, null, 'Curry leaves splutter in hot oil, so stand back when adding them.'),
  ((select id from public.recipes where household_id is null and slug = 'bread-upma'), 3, 'Add the onion, green chilli and ginger and sauté until the onion is soft.', '{"en": "Add the onion, green chilli and ginger and sauté until the onion is soft.", "hi": {"look": "प्याज़ नरम और पारदर्शी हो जाए।", "smell": "अदरक की कच्ची महक चली जाए।", "text": "प्याज़, हरी मिर्च और अदरक डालकर प्याज़ नरम होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram aur transparent ho jaaye.", "smell": "Adrak ki kachchi mehak chali jaaye.", "text": "Pyaaz, hari mirch aur adrak daalkar pyaaz naram hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 240, true, null, 'The onion turns soft and translucent. The raw smell of ginger goes away.', '{"en": "The onion turns soft and translucent. The raw smell of ginger goes away.", "heat": "medium", "look": "The onion turns soft and translucent.", "smell": "The raw smell of ginger goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'bread-upma'), 4, 'Add the tomato, turmeric, red chilli powder, salt and sugar, and cook until the tomato turns mushy.', '{"en": "Add the tomato, turmeric, red chilli powder, salt and sugar, and cook until the tomato turns mushy.", "hi": {"look": "टमाटर गल जाए और किनारों पर तेल दिखने लगे।", "text": "टमाटर, हल्दी, लाल मिर्च पाउडर, नमक और चीनी डालकर टमाटर गलने तक पकाएँ।"}, "hi-Latn": {"look": "Tamatar gal jaaye aur kinaron par tel dikhne lage.", "text": "Tamatar, haldi, lal mirch powder, namak aur cheeni daalkar tamatar galne tak pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 300, true, null, 'The tomato breaks down and oil shows at the edges.', '{"en": "The tomato breaks down and oil shows at the edges.", "heat": "medium", "look": "The tomato breaks down and oil shows at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'bread-upma'), 5, 'Sprinkle 2 to 3 tablespoons of water, add the bread cubes and toss gently until every piece is coated with masala.', '{"en": "Sprinkle 2 to 3 tablespoons of water, add the bread cubes and toss gently until every piece is coated with masala.", "hi": {"look": "ब्रेड पर एक जैसा नारंगी मसाला चढ़ जाए।", "text": "2-3 बड़े चम्मच पानी छिड़कें, ब्रेड के टुकड़े डालें और हल्के हाथ से मिलाएँ ताकि हर टुकड़े पर मसाला लग जाए।", "touch": "टुकड़े अंदर से नरम हों पर गीले न हों।"}, "hi-Latn": {"look": "Bread par ek jaisa orange masala chadh jaaye.", "text": "2-3 bade chammach paani chhidkein, bread ke tukde daalein aur halke haath se milaayein taaki har tukde par masala lag jaaye.", "touch": "Tukde andar se naram hon par geele na hon."}}'::jsonb, null, 180, true, null, 'The bread is evenly orange with masala. The cubes are soft inside but not soggy.', '{"en": "The bread is evenly orange with masala. The cubes are soft inside but not soggy.", "heat": "low", "look": "The bread is evenly orange with masala.", "touch": "The cubes are soft inside but not soggy."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'bread-upma'), 6, 'Turn off the heat, squeeze the lemon, add the coriander leaves, mix and serve hot.', '{"en": "Turn off the heat, squeeze the lemon, add the coriander leaves, mix and serve hot.", "hi": {"text": "आँच बंद करें, नींबू निचोड़ें, हरा धनिया डालें, मिलाएँ और गरम परोसें।"}, "hi-Latn": {"text": "Aanch band karein, nimbu nichodein, hara dhaniya daalein, milaayein aur garam parosein."}}'::jsonb, null, 60, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'bread-upma') and step_no > 6;

