insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('cabbage-sabzi', 'Patta Gobhi Sabzi', '{"en": "Patta Gobhi Sabzi", "hi": "पत्ता गोभी की सब्ज़ी", "hi-Latn": "Patta Gobhi Sabzi"}'::jsonb, 'A dry North Indian stir-fry of finely shredded cabbage and green peas, cooked with cumin, ginger, green chilli and everyday masalas. It is eaten with roti or dal-chawal.', '{"hi": "बारीक कटी पत्ता गोभी और हरी मटर की सूखी उत्तर भारतीय सब्ज़ी, जो जीरा, अदरक, हरी मिर्च और रोज़ के मसालों के साथ बनती है। इसे रोटी या दाल-चावल के साथ खाते हैं।", "hi-Latn": "Baarik kati patta gobhi aur hari matar ki sookhi North Indian sabzi, jo jeera, adrak, hari mirch aur roz ke masalon ke saath banti hai. Ise roti ya dal-chawal ke saath khaate hain."}'::jsonb, 'north_indian', 'side', 'veg', 4, 10, 20, 1, 2, array['kadai', 'gas_stove']::text[], array['quick', 'tiffin', 'light']::text[], '{"acid": 0.2, "crunch": 0.2, "heat": 0.3, "rich": 0.3, "starch": 0.1, "sweet": 0.1}'::jsonb, array['sabzi']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
