insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'cabbage-sabzi'), 1, 'Wash the cabbage, shred it finely and let it drain in a colander; chop the tomato, ginger and green chillies.', '{"en": "Wash the cabbage, shred it finely and let it drain in a colander; chop the tomato, ginger and green chillies.", "hi": {"text": "पत्ता गोभी धोकर बारीक काटें और छलनी में पानी निकलने दें; टमाटर, अदरक और हरी मिर्च काट लें।"}, "hi-Latn": {"text": "Patta gobhi dhokar baarik kaatein aur chhalni mein paani nikalne dein; tamatar, adrak aur hari mirch kaat lein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'cabbage-sabzi'), 2, 'Heat the oil in a kadai on medium heat and add the cumin seeds.', '{"en": "Heat the oil in a kadai on medium heat and add the cumin seeds.", "hi": {"sound": "जीरा चटकने और चड़चड़ाने लगे।", "text": "कढ़ाई में मध्यम आंच पर तेल गरम करें और जीरा डालें।"}, "hi-Latn": {"sound": "Jeera chatakne aur chadchadane lage.", "text": "Kadai mein medium aanch par tel garam karein aur jeera daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin crackles and sizzles.', '{"en": "The cumin crackles and sizzles.", "heat": "medium", "sound": "The cumin crackles and sizzles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'cabbage-sabzi'), 3, 'Add the ginger and green chillies and sauté for 30 seconds.', '{"en": "Add the ginger and green chillies and sauté for 30 seconds.", "hi": {"smell": "अदरक की कच्ची महक चली जाए।", "text": "अदरक और हरी मिर्च डालकर 30 सेकंड भूनें।"}, "hi-Latn": {"smell": "Adrak ki kachchi mahak chali jaaye.", "text": "Adrak aur hari mirch daalkar 30 second bhoonein."}}'::jsonb, null, 60, false, null, 'The raw smell of ginger goes away.', '{"en": "The raw smell of ginger goes away.", "heat": "medium", "smell": "The raw smell of ginger goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'cabbage-sabzi'), 4, 'Add the tomato, turmeric, red chilli powder, coriander powder and salt, and cook until the tomato turns soft.', '{"en": "Add the tomato, turmeric, red chilli powder, coriander powder and salt, and cook until the tomato turns soft.", "hi": {"look": "टमाटर गल जाए और किनारों से तेल दिखने लगे।", "text": "टमाटर, हल्दी, लाल मिर्च, धनिया पाउडर और नमक डालें और टमाटर नरम होने तक पकाएं।"}, "hi-Latn": {"look": "Tamatar gal jaaye aur kinaaron se tel dikhne lage.", "text": "Tamatar, haldi, lal mirch, dhania powder aur namak daalein aur tamatar naram hone tak pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 180, true, null, 'The tomato turns mushy and the oil starts to show at the edges.', '{"en": "The tomato turns mushy and the oil starts to show at the edges.", "heat": "medium", "look": "The tomato turns mushy and the oil starts to show at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'cabbage-sabzi'), 5, 'Add the cabbage and peas, mix well, cover and cook on low heat without adding water, stirring every few minutes.', '{"en": "Add the cabbage and peas, mix well, cover and cook on low heat without adding water, stirring every few minutes.", "hi": {"look": "गोभी सिकुड़ जाए और चमकदार दिखने लगे।", "text": "पत्ता गोभी और मटर डालें, अच्छे से मिलाएं, ढककर धीमी आंच पर बिना पानी डाले पकाएं और बीच-बीच में चलाते रहें।", "touch": "गोभी नरम हो जाए पर थोड़ी कुरकुरी रहे।"}, "hi-Latn": {"look": "Gobhi sikud jaaye aur chamakdaar dikhne lage.", "text": "Patta gobhi aur matar daalein, achche se milaayein, dhakkar dheemi aanch par bina paani daale pakaayein aur beech-beech mein chalaate rahein.", "touch": "Gobhi naram ho jaaye par thodi kurkuri rahe."}}'::jsonb, null, 720, true, null, 'The cabbage wilts and turns glossy. The cabbage is tender but still has a slight bite.', '{"en": "The cabbage wilts and turns glossy. The cabbage is tender but still has a slight bite.", "heat": "low", "look": "The cabbage wilts and turns glossy.", "touch": "The cabbage is tender but still has a slight bite."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'cabbage-sabzi'), 6, 'Uncover, raise the heat to medium and stir-fry until the extra moisture dries up, then sprinkle in the garam masala.', '{"en": "Uncover, raise the heat to medium and stir-fry until the extra moisture dries up, then sprinkle in the garam masala.", "hi": {"look": "कढ़ाई के तले में पानी न बचे।", "text": "ढक्कन हटाएं, आंच मध्यम करें और पानी सूखने तक भूनें, फिर गरम मसाला छिड़कें।"}, "hi-Latn": {"look": "Kadai ke tale mein paani na bache.", "text": "Dhakkan hataayein, aanch medium karein aur paani sookhne tak bhoonein, phir garam masala chhidkein."}}'::jsonb, null, 180, true, null, 'No water is left at the bottom of the kadai.', '{"en": "No water is left at the bottom of the kadai.", "heat": "medium", "look": "No water is left at the bottom of the kadai."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'cabbage-sabzi'), 7, 'Turn off the heat, garnish with chopped coriander leaves and serve hot with roti.', '{"en": "Turn off the heat, garnish with chopped coriander leaves and serve hot with roti.", "hi": {"text": "गैस बंद करें, कटा हरा धनिया डालें और रोटी के साथ गरम परोसें।"}, "hi-Latn": {"text": "Gas band karein, kata hara dhania daalein aur roti ke saath garam parosein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'cabbage-sabzi') and step_no > 7;

