insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('chana-dal', 'Chana Dal Tadka', '{"en": "Chana Dal Tadka", "hi": "चना दाल तड़का", "hi-Latn": "Chana Dal Tadka"}'::jsonb, 'Everyday North Indian chana dal. The split Bengal gram is soaked, pressure-cooked soft, then simmered in a ghee tadka of cumin, onion, tomato and ginger-garlic. Thick, nutty and homely with rice or roti.', '{"hi": "रोज़ की उत्तर भारतीय चना दाल। भीगी हुई चना दाल को प्रेशर कुकर में नरम पकाकर घी में जीरा, प्याज़, टमाटर और अदरक-लहसुन के तड़के के साथ उबाला जाता है। गाढ़ी, हल्की सोंधी और घर जैसी, चावल या रोटी के साथ।", "hi-Latn": "Roz ki North Indian chana dal. Bhigi hui chana dal ko pressure cooker mein naram pakakar ghee mein jeera, pyaaz, tamatar aur adrak-lehsun ke tadke ke saath ubaala jaata hai. Gaadhi, halki sondhi aur ghar jaisi, chawal ya roti ke saath."}'::jsonb, 'north_indian', 'main', 'veg', 4, 70, 35, 2, 2, array['pressure_cooker', 'kadai', 'gas_stove']::text[], array['comforting']::text[], '{"acid": 0.3, "crunch": 0, "heat": 0.4, "rich": 0.5, "starch": 0.5, "sweet": 0}'::jsonb, array['dal']::text[], 'curated', 'in_review', false)
