insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'chana-dal'), 1, 'Wash the chana dal 3 to 4 times, then soak it in plenty of water for 1 hour.', '{"en": "Wash the chana dal 3 to 4 times, then soak it in plenty of water for 1 hour.", "hi": {"look": "धोने का पानी लगभग साफ़ दिखने लगे।", "text": "चना दाल को 3-4 बार धो लें, फिर भरपूर पानी में 1 घंटे भिगो दें।"}, "hi-Latn": {"look": "Dhone ka paani lagbhag saaf dikhne lage.", "text": "Chana dal ko 3-4 baar dho lein, phir bharpoor paani mein 1 ghante bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 3600, true, null, 'The washing water runs almost clear.', '{"en": "The washing water runs almost clear.", "look": "The washing water runs almost clear."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chana-dal'), 2, 'Drain the dal and add it to the pressure cooker with 750 ml water, the turmeric and the salt. Cook on medium heat for 4 whistles, then let the pressure drop on its own.', '{"en": "Drain the dal and add it to the pressure cooker with 750 ml water, the turmeric and the salt. Cook on medium heat for 4 whistles, then let the pressure drop on its own.", "hi": {"safety": "ढक्कन तभी खोलें जब सारा प्रेशर अपने आप निकल जाए।", "text": "दाल का पानी निकालकर उसे प्रेशर कुकर में 750 मि.ली. पानी, हल्दी और नमक के साथ डालें। मध्यम आँच पर 4 सीटी लगाएँ, फिर प्रेशर अपने आप उतरने दें।", "touch": "दाना उंगलियों में आसानी से मसल जाए, पर अपना आकार बनाए रखे।"}, "hi-Latn": {"safety": "Dhakkan tabhi kholein jab saara pressure apne aap nikal jaaye.", "text": "Dal ka paani nikaalkar use pressure cooker mein 750 ml paani, haldi aur namak ke saath daalein. Medium aanch par 4 seeti lagayein, phir pressure apne aap utarne dein.", "touch": "Daana ungliyon mein aasani se masal jaaye, par apna shape banaye rakhe."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 900, true, 4, 'A grain mashes easily between your fingers but still keeps its shape.', '{"en": "A grain mashes easily between your fingers but still keeps its shape.", "heat": "medium", "touch": "A grain mashes easily between your fingers but still keeps its shape."}'::jsonb, null, 'Open the lid only after all the pressure has released by itself.'),
  ((select id from public.recipes where household_id is null and slug = 'chana-dal'), 3, 'Heat the ghee in a kadai on medium heat, then add the cumin seeds and asafoetida.', '{"en": "Heat the ghee in a kadai on medium heat, then add the cumin seeds and asafoetida.", "hi": {"smell": "भुनी हुई खुशबू आए।", "sound": "जीरा चटकने लगे।", "text": "कड़ाही में मध्यम आँच पर घी गरम करें, फिर जीरा और हींग डालें।"}, "hi-Latn": {"smell": "Bhuni hui khushboo aaye.", "sound": "Jeera chatakne lage.", "text": "Kadai mein medium aanch par ghee garam karein, phir jeera aur hing daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin crackles. It smells toasty.', '{"en": "The cumin crackles. It smells toasty.", "heat": "medium", "smell": "It smells toasty.", "sound": "The cumin crackles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chana-dal'), 4, 'Add the onion, ginger, garlic and green chilli, and sauté until the onion turns golden.', '{"en": "Add the onion, ginger, garlic and green chilli, and sauté until the onion turns golden.", "hi": {"look": "प्याज़ किनारों से सुनहरा हो जाए।", "smell": "लहसुन की कच्ची महक चली जाए।", "text": "प्याज़, अदरक, लहसुन और हरी मिर्च डालें और प्याज़ सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz kinaaron se sunehra ho jaaye.", "smell": "Lehsun ki kachchi mehak chali jaaye.", "text": "Pyaaz, adrak, lehsun aur hari mirch daalein aur pyaaz sunehra hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 360, true, null, 'The onion is golden at the edges. The raw smell of the garlic goes away.', '{"en": "The onion is golden at the edges. The raw smell of the garlic goes away.", "heat": "medium", "look": "The onion is golden at the edges.", "smell": "The raw smell of the garlic goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chana-dal'), 5, 'Add the tomato, red chilli powder and coriander powder, and cook until the tomato turns soft.', '{"en": "Add the tomato, red chilli powder and coriander powder, and cook until the tomato turns soft.", "hi": {"look": "मसाले के किनारों पर घी दिखने लगे।", "text": "टमाटर, लाल मिर्च पाउडर और धनिया पाउडर डालें और टमाटर नरम होने तक पकाएँ।", "touch": "टमाटर चम्मच से दबाने पर मसल जाए।"}, "hi-Latn": {"look": "Masale ke kinaaron par ghee dikhne lage.", "text": "Tamatar, laal mirch powder aur dhaniya powder daalein aur tamatar naram hone tak pakaayein.", "touch": "Tamatar chammach se dabane par masal jaaye."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 360, true, null, 'Ghee shows at the edges of the masala. The tomato mashes under the spoon.', '{"en": "Ghee shows at the edges of the masala. The tomato mashes under the spoon.", "heat": "medium", "look": "Ghee shows at the edges of the masala.", "touch": "The tomato mashes under the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chana-dal'), 6, 'Pour in the cooked dal with its water, adding a little hot water if it is too thick. Simmer on low heat for 5 minutes, stirring now and then.', '{"en": "Pour in the cooked dal with its water, adding a little hot water if it is too thick. Simmer on low heat for 5 minutes, stirring now and then.", "hi": {"look": "दाल गाढ़ी हो जाए और चम्मच पर चढ़ने लगे।", "safety": "गाढ़ी दाल छींटे मार सकती है, लंबे चम्मच से चलाएँ।", "sound": "हल्के-हल्के बुलबुले उठें।", "text": "पकी हुई दाल पानी समेत डालें, ज़्यादा गाढ़ी हो तो थोड़ा गरम पानी मिलाएँ। धीमी आँच पर 5 मिनट उबालें, बीच-बीच में चलाते रहें।"}, "hi-Latn": {"look": "Dal gaadhi ho jaaye aur chammach par chadhne lage.", "safety": "Gaadhi dal chheente maar sakti hai, lambe chammach se chalaayein.", "sound": "Halke-halke bulbule uthein.", "text": "Paki hui dal paani samet daalein, zyada gaadhi ho to thoda garam paani milaayein. Dheemi aanch par 5 minute ubaalein, beech-beech mein chalaate rahein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, true, null, 'The dal is thick and coats the spoon. It bubbles gently.', '{"en": "The dal is thick and coats the spoon. It bubbles gently.", "heat": "low", "look": "The dal is thick and coats the spoon.", "sound": "It bubbles gently."}'::jsonb, null, 'Thick dal can splutter, so stir with a long spoon.'),
  ((select id from public.recipes where household_id is null and slug = 'chana-dal'), 7, 'Stir in the garam masala and switch off the heat. Finish with coriander leaves and a squeeze of lemon, and serve hot.', '{"en": "Stir in the garam masala and switch off the heat. Finish with coriander leaves and a squeeze of lemon, and serve hot.", "hi": {"smell": "गरम मसाले की खुशबू आए।", "text": "गरम मसाला मिलाएँ और आँच बंद कर दें। ऊपर से हरा धनिया और नींबू का रस डालें और गरमागरम परोसें।"}, "hi-Latn": {"smell": "Garam masale ki khushboo aaye.", "text": "Garam masala milaayein aur aanch band kar dein. Upar se hara dhaniya aur nimbu ka ras daalein aur garamagaram parosein."}}'::jsonb, null, null, false, null, 'The garam masala smells fragrant.', '{"en": "The garam masala smells fragrant.", "smell": "The garam masala smells fragrant."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
