insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'chole'), 1, 'Wash the chickpeas and soak them in plenty of water for 8 hours or overnight.', '{"en": "Wash the chickpeas and soak them in plenty of water for 8 hours or overnight.", "hi": {"look": "छोले फूलकर लगभग दोगुने हो जाते हैं।", "text": "छोले धोकर खूब सारे पानी में 8 घंटे या रात भर भिगो दें।"}, "hi-Latn": {"look": "Chhole phoolkar lagbhag doguna ho jaate hain.", "text": "Chhole dhokar khoob saare paani mein 8 ghante ya raat bhar bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 28800, true, null, 'The chickpeas swell to about double their size.', '{"en": "The chickpeas swell to about double their size.", "look": "The chickpeas swell to about double their size."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chole'), 2, 'Drain the chickpeas and put them in the pressure cooker with 900 ml fresh water and half the salt. Cook for 5 whistles on medium heat, then let the pressure drop on its own.', '{"en": "Drain the chickpeas and put them in the pressure cooker with 900 ml fresh water and half the salt. Cook for 5 whistles on medium heat, then let the pressure drop on its own.", "hi": {"safety": "प्रेशर पूरी तरह अपने आप उतरने के बाद ही कुकर खोलें।", "text": "छोलों का पानी निकाल दें। प्रेशर कुकर में 900 ml ताज़ा पानी और आधा नमक डालकर छोले डालें। मध्यम आँच पर 5 सीटी लगाएँ, फिर प्रेशर अपने आप उतरने दें।", "touch": "एक छोला दो उँगलियों के बीच आसानी से मसल जाता है।"}, "hi-Latn": {"safety": "Pressure poori tarah apne aap utarne ke baad hi cooker kholein.", "text": "Chhole ka paani nikaal dein. Pressure cooker mein 900 ml taaza paani aur aadha namak daalkar chhole daalein. Medium aanch par 5 seeti lagayein, phir pressure apne aap utarne dein.", "touch": "Ek chhola do ungliyon ke beech aasani se masal jaata hai."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 1500, true, 5, 'A chickpea mashes easily between two fingers.', '{"en": "A chickpea mashes easily between two fingers.", "heat": "medium", "touch": "A chickpea mashes easily between two fingers."}'::jsonb, null, 'Open the cooker only after the pressure has fully dropped by itself.'),
  ((select id from public.recipes where household_id is null and slug = 'chole'), 3, 'Heat oil in a kadai and add cumin seeds and the bay leaf. Then add the onion and fry until golden brown.', '{"en": "Heat oil in a kadai and add cumin seeds and the bay leaf. Then add the onion and fry until golden brown.", "hi": {"look": "प्याज़ एक जैसा सुनहरा भूरा हो जाता है।", "sound": "तेल में डालते ही जीरा चटकने लगता है।", "text": "कड़ाही में तेल गरम करें, जीरा और तेज पत्ता डालें। फिर प्याज़ डालकर सुनहरा भूरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz ek jaisa sunehra bhoora ho jaata hai.", "sound": "Tel mein daalte hi jeera chatakne lagta hai.", "text": "Kadai mein tel garam karein, jeera aur tej patta daalein. Phir pyaaz daalkar sunehra bhoora hone tak bhoonein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 480, true, null, 'The onion turns an even golden brown. The cumin crackles as soon as it hits the oil.', '{"en": "The onion turns an even golden brown. The cumin crackles as soon as it hits the oil.", "heat": "medium", "look": "The onion turns an even golden brown.", "sound": "The cumin crackles as soon as it hits the oil."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chole'), 4, 'Add the ginger garlic paste and green chilli and stir for a minute.', '{"en": "Add the ginger garlic paste and green chilli and stir for a minute.", "hi": {"smell": "लहसुन की कच्ची महक चली जाती है।", "text": "अदरक लहसुन पेस्ट और हरी मिर्च डालकर एक मिनट चलाएँ।"}, "hi-Latn": {"smell": "Lehsun ki kachchi mehak chali jaati hai.", "text": "Adrak lehsun paste aur hari mirch daalkar ek minute chalayein."}}'::jsonb, null, 60, false, null, 'The raw garlic smell goes away.', '{"en": "The raw garlic smell goes away.", "heat": "medium", "smell": "The raw garlic smell goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chole'), 5, 'Add the tomato, turmeric, red chilli powder, coriander powder and chole masala with a splash of water. Cook the masala until it thickens.', '{"en": "Add the tomato, turmeric, red chilli powder, coriander powder and chole masala with a splash of water. Cook the masala until it thickens.", "hi": {"look": "मसाला गहरा हो जाता है और किनारों पर तेल छोड़ने लगता है।", "text": "टमाटर, हल्दी, लाल मिर्च, धनिया पाउडर और छोले मसाला थोड़े पानी के साथ डालें। मसाला गाढ़ा होने तक भूनें।"}, "hi-Latn": {"look": "Masala gehra ho jaata hai aur kinaron par tel chhodne lagta hai.", "text": "Tamatar, haldi, laal mirch, dhaniya powder aur chhole masala thode paani ke saath daalein. Masala gaadha hone tak bhoonein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 480, true, null, 'The masala turns dark and oil separates at the edges.', '{"en": "The masala turns dark and oil separates at the edges.", "heat": "medium", "look": "The masala turns dark and oil separates at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chole'), 6, 'Add the cooked chickpeas with their water and the remaining salt. Mash a few chickpeas against the side, cover, and simmer.', '{"en": "Add the cooked chickpeas with their water and the remaining salt. Mash a few chickpeas against the side, cover, and simmer.", "hi": {"look": "ग्रेवी गाढ़ी होकर चम्मच पर लिपटने लगती है।", "text": "पके छोले उनके पानी के साथ और बचा हुआ नमक डालें। कुछ छोले कड़ाही की दीवार पर मसल दें, ढककर धीमी आँच पर पकाएँ।"}, "hi-Latn": {"look": "Gravy gaadhi hokar chammach par lipatne lagti hai.", "text": "Pake chhole unke paani ke saath aur bacha hua namak daalein. Kuch chhole kadai ki deewar par masal dein, dhakkar dheemi aanch par pakayein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 720, true, null, 'The gravy turns thick and coats the spoon.', '{"en": "The gravy turns thick and coats the spoon.", "heat": "low", "look": "The gravy turns thick and coats the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chole'), 7, 'Stir in the dry mango powder and garam masala, top with coriander leaves, and serve hot.', '{"en": "Stir in the dry mango powder and garam masala, top with coriander leaves, and serve hot.", "hi": {"smell": "कड़ाही से गरम, खट्टी मसालेदार खुशबू उठती है।", "text": "अमचूर और गरम मसाला मिलाएँ, ऊपर से हरा धनिया डालें और गरम परोसें।"}, "hi-Latn": {"smell": "Kadai se garam, khatti masaledaar khushboo uthti hai.", "text": "Amchur aur garam masala milayein, upar se hara dhaniya daalein aur garam parosein."}}'::jsonb, null, 60, false, null, 'A warm, tangy spice aroma rises from the pan.', '{"en": "A warm, tangy spice aroma rises from the pan.", "heat": "low", "smell": "A warm, tangy spice aroma rises from the pan."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'chole') and step_no > 7;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'chole');

-- Recipe: dal-dhokli (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('dal-dhokli', 'Gujarati Dal Dhokli', '{"en": "Gujarati Dal Dhokli", "hi": "गुजराती दाल ढोकली", "hi-Latn": "Gujarati Dal Dhokli"}'::jsonb, 'Sweet, tangy and lightly spiced Gujarati toor dal with soft, masala wheat-flour dhokli simmered right in it. A full one-pot meal for a weekday dinner.', '{"hi": "खट्टी-मीठी, हल्की मसालेदार गुजराती तुअर दाल, जिसमें मसाले वाले गेहूँ के आटे की नरम ढोकली उसी में पकाई जाती है। हफ़्ते के किसी भी दिन के खाने के लिए पूरा एक-बर्तन भोजन।", "hi-Latn": "Khatti-meethi, halki masaledar Gujarati toor dal, jismein masale wale gehun ke aate ki naram dhokli usi mein pakayi jaati hai. Hafte ke kisi bhi din ke khaane ke liye poora ek-bartan bhojan."}'::jsonb, 'gujarat', 'main', 'veg', 4, 20, 35, 2, 2, array['pressure_cooker', 'gas_stove', 'kadai']::text[], array['comforting', 'one_pot']::text[], '{"acid": 0.5, "crunch": 0, "heat": 0.3, "rich": 0.5, "starch": 0.8, "sweet": 0.5}'::jsonb, array['dal', 'grain']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
  description = excluded.description, descriptions = excluded.descriptions, cuisine_region = excluded.cuisine_region, course = excluded.course,
  diet = excluded.diet, base_servings = excluded.base_servings, prep_time_min = excluded.prep_time_min,
  cook_time_min = excluded.cook_time_min, difficulty = excluded.difficulty,
  spice_level = excluded.spice_level, equipment = excluded.equipment, tags = excluded.tags,
  flavor_profile = excluded.flavor_profile, food_groups = excluded.food_groups,
  review_status = excluded.review_status, is_published = excluded.is_published;

