insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'dal-fry'), 1, 'Wash the toor dal 3 to 4 times and soak it in water for 20 minutes, then drain.', '{"en": "Wash the toor dal 3 to 4 times and soak it in water for 20 minutes, then drain.", "hi": {"look": "धोने का पानी लगभग साफ़ दिखने लगे।", "text": "तूर दाल को 3-4 बार धोकर 20 मिनट पानी में भिगो दो, फिर पानी निकाल दो।"}, "hi-Latn": {"look": "Dhone ka paani lagbhag saaf dikhne lage.", "text": "Toor dal ko 3-4 baar dhokar 20 minute paani mein bhigo do, phir paani nikaal do."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 1200, true, null, 'The washing water turns almost clear.', '{"en": "The washing water turns almost clear.", "look": "The washing water turns almost clear."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-fry'), 2, 'Put the dal in the pressure cooker with 3 cups water, the turmeric and half the salt, and cook on medium heat for 3 whistles.', '{"en": "Put the dal in the pressure cooker with 3 cups water, the turmeric and half the salt, and cook on medium heat for 3 whistles.", "hi": {"safety": "कुकर तभी खोलो जब प्रेशर अपने आप उतर जाए।", "text": "दाल को प्रेशर कुकर में 3 कप पानी, हल्दी और आधे नमक के साथ डालो और मध्यम आँच पर 3 सीटी आने तक पकाओ।"}, "hi-Latn": {"safety": "Cooker tabhi kholo jab pressure apne aap utar jaaye.", "text": "Dal ko pressure cooker mein 3 cup paani, haldi aur aadhe namak ke saath daalo aur medium aanch par 3 seeti aane tak pakao."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 720, true, 3, null, '{"heat": "medium"}'::jsonb, null, 'Open the cooker only after the pressure drops on its own.'),
  ((select id from public.recipes where household_id is null and slug = 'dal-fry'), 3, 'Open the cooker and whisk the dal lightly with a ladle until smooth.', '{"en": "Open the cooker and whisk the dal lightly with a ladle until smooth.", "hi": {"look": "दाल मलाईदार दिखे, कोई साबुत दाना न रहे।", "text": "कुकर खोलो और करछी से दाल को हल्का सा घोटकर एकसार कर लो।", "touch": "दाना उँगलियों के बीच आसानी से मसल जाए।"}, "hi-Latn": {"look": "Dal malaidaar dikhe, koi saabut daana na rahe.", "text": "Cooker kholo aur karchhi se dal ko halka sa ghotkar eksaar kar lo.", "touch": "Daana ungliyon ke beech aasaani se masal jaaye."}}'::jsonb, null, null, false, null, 'The dal looks creamy, with no whole grains. A grain crushes easily between your fingers.', '{"en": "The dal looks creamy, with no whole grains. A grain crushes easily between your fingers.", "look": "The dal looks creamy, with no whole grains.", "touch": "A grain crushes easily between your fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-fry'), 4, 'Heat the ghee and oil in a kadai on medium heat, then add the cumin seeds, dry red chillies and asafoetida.', '{"en": "Heat the ghee and oil in a kadai on medium heat, then add the cumin seeds, dry red chillies and asafoetida.", "hi": {"safety": "चेहरा दूर रखो, गरम घी छिटक सकता है।", "sound": "जीरा चटकने लगे।", "text": "कढ़ाई में घी और तेल मध्यम आँच पर गरम करो, फिर जीरा, सूखी लाल मिर्च और हींग डालो।"}, "hi-Latn": {"safety": "Chehra door rakho, garam ghee chhitak sakta hai.", "sound": "Jeera chatakne lage.", "text": "Kadai mein ghee aur tel medium aanch par garam karo, phir jeera, sookhi laal mirch aur hing daalo."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin crackles.', '{"en": "The cumin crackles.", "heat": "medium", "sound": "The cumin crackles."}'::jsonb, null, 'Keep your face back, because hot ghee can splutter.'),
  ((select id from public.recipes where household_id is null and slug = 'dal-fry'), 5, 'Add the finely chopped onion and sauté until golden.', '{"en": "Add the finely chopped onion and sauté until golden.", "hi": {"look": "प्याज़ किनारों से हल्का सुनहरा हो जाए।", "text": "बारीक कटा प्याज़ डालो और सुनहरा होने तक भूनो।"}, "hi-Latn": {"look": "Pyaaz kinaaron se halka sunehra ho jaaye.", "text": "Baarik kata pyaaz daalo aur sunehra hone tak bhuno."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 300, true, null, 'The onion turns light golden at the edges.', '{"en": "The onion turns light golden at the edges.", "heat": "medium", "look": "The onion turns light golden at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-fry'), 6, 'Add the grated ginger, chopped garlic and slit green chillies and stir for 1 minute.', '{"en": "Add the grated ginger, chopped garlic and slit green chillies and stir for 1 minute.", "hi": {"smell": "लहसुन की कच्ची महक सोंधी हो जाए।", "text": "कद्दूकस किया अदरक, कटा लहसुन और चीरी हुई हरी मिर्च डालकर 1 मिनट चलाओ।"}, "hi-Latn": {"smell": "Lehsun ki kachchi mehak sondhi ho jaaye.", "text": "Kaddukas kiya adrak, kata lehsun aur cheeri hui hari mirch daalkar 1 minute chalao."}}'::jsonb, null, 60, false, null, 'The raw garlic smell turns nutty.', '{"en": "The raw garlic smell turns nutty.", "heat": "medium", "smell": "The raw garlic smell turns nutty."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-fry'), 7, 'Add the chopped tomatoes, red chilli powder, kashmiri chilli powder, coriander powder and the rest of the salt, and cook until the tomatoes turn mushy.', '{"en": "Add the chopped tomatoes, red chilli powder, kashmiri chilli powder, coriander powder and the rest of the salt, and cook until the tomatoes turn mushy.", "hi": {"look": "मसाले के किनारों से तेल अलग होने लगे।", "text": "कटे टमाटर, लाल मिर्च पाउडर, कश्मीरी मिर्च, धनिया पाउडर और बचा नमक डालो और टमाटर गलने तक भूनो।"}, "hi-Latn": {"look": "Masale ke kinaaron se tel alag hone lage.", "text": "Kate tamatar, laal mirch powder, kashmiri mirch, dhaniya powder aur bacha namak daalo aur tamatar galne tak bhuno."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 360, true, null, 'Oil separates at the sides of the masala.', '{"en": "Oil separates at the sides of the masala.", "heat": "medium", "look": "Oil separates at the sides of the masala."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-fry'), 8, 'Pour in the cooked dal with about 1 cup hot water, stir, and simmer on low heat.', '{"en": "Pour in the cooked dal with about 1 cup hot water, stir, and simmer on low heat.", "hi": {"look": "दाल डालने लायक गाढ़ी हो जाए।", "safety": "उबलती दाल छिटक सकती है, लंबी करछी से चलाओ।", "sound": "धीमे-धीमे बुलबुले उठें।", "text": "पकी दाल और लगभग 1 कप गरम पानी डालो, मिलाओ और धीमी आँच पर उबलने दो।"}, "hi-Latn": {"look": "Dal daalne laayak gaadhi ho jaaye.", "safety": "Ubalti dal chhitak sakti hai, lambi karchhi se chalao.", "sound": "Dheeme-dheeme bulbule uthein.", "text": "Paki dal aur lagbhag 1 cup garam paani daalo, milao aur dheemi aanch par ubalne do."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 420, true, null, 'The dal thickens to a pouring consistency. It bubbles gently.', '{"en": "The dal thickens to a pouring consistency. It bubbles gently.", "heat": "low", "look": "The dal thickens to a pouring consistency.", "sound": "It bubbles gently."}'::jsonb, null, 'Bubbling dal can splash, so stir with a long ladle.'),
  ((select id from public.recipes where household_id is null and slug = 'dal-fry'), 9, 'Turn off the heat and stir in the garam masala, chopped coriander leaves and a squeeze of lemon if you like, then serve hot.', '{"en": "Turn off the heat and stir in the garam masala, chopped coriander leaves and a squeeze of lemon if you like, then serve hot.", "hi": {"text": "आँच बंद करो, गरम मसाला, कटा हरा धनिया और चाहो तो थोड़ा नींबू निचोड़कर मिलाओ, फिर गरम परोसो।"}, "hi-Latn": {"text": "Aanch band karo, garam masala, kata hara dhaniya aur chaho to thoda nimbu nichodkar milao, phir garam paroso."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
