-- Recipe: dal-makhani (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('dal-makhani', 'Dal Makhani', '{"en": "Dal Makhani", "hi": "दाल मखनी", "hi-Latn": "Dal Makhani"}'::jsonb, 'Creamy Punjabi dal of whole black urad and a little rajma, pressure-cooked soft, then simmered slowly with a buttery tomato masala and finished with cream.', '{"hi": "साबुत काली उड़द और थोड़े राजमा की मलाईदार पंजाबी दाल। इसे कुकर में नरम पकाकर मक्खन वाले टमाटर मसाले में धीमी आँच पर पकाया जाता है और ऊपर से क्रीम डाली जाती है।", "hi-Latn": "Sabut kaali urad aur thode rajma ki malaidaar Punjabi dal. Ise cooker mein naram pakakar makkhan wale tamatar masale mein dheemi aanch par pakaya jaata hai aur upar se cream daali jaati hai."}'::jsonb, 'punjabi', 'main', 'veg', 4, 20, 75, 3, 2, array['pressure_cooker', 'kadai', 'gas_stove']::text[], array['comforting', 'high_protein']::text[], '{"acid": 0.3, "crunch": 0, "heat": 0.3, "rich": 0.9, "starch": 0.5, "sweet": 0.1}'::jsonb, array['dal', 'dairy']::text[], 'curated', 'in_review', false)
