insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'dal-makhani'), 1, 'Wash the black urad and rajma together and soak them overnight, at least 8 hours, in plenty of water.', '{"en": "Wash the black urad and rajma together and soak them overnight, at least 8 hours, in plenty of water.", "hi": {"look": "दाने फूलकर लगभग दोगुने हो जाते हैं।", "text": "काली उड़द और राजमा को साथ में धोकर खूब सारे पानी में रात भर, कम से कम 8 घंटे, भिगो दें।"}, "hi-Latn": {"look": "Daane phoolkar lagbhag dogune ho jaate hain.", "text": "Kaali urad aur rajma ko saath mein dhokar khoob saare paani mein raat bhar, kam se kam 8 ghante, bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 28800, true, null, 'The beans swell to nearly double in size.', '{"en": "The beans swell to nearly double in size.", "look": "The beans swell to nearly double in size."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-makhani'), 2, 'Drain and throw away the soaking water, rinse, then pressure-cook with 900 ml fresh water and the salt: 7 whistles on medium heat, then 20 minutes on low.', '{"en": "Drain and throw away the soaking water, rinse, then pressure-cook with 900 ml fresh water and the salt: 7 whistles on medium heat, then 20 minutes on low.", "hi": {"safety": "राजमा को कभी भिगोने वाले पानी में न पकाएँ और न ही आधा कच्चा छोड़ें।", "sound": "कुकर से लगातार सीटी और भाप की आवाज़ आती है।", "text": "भिगोने वाला पानी निकालकर फेंक दें, दाल धो लें, फिर 900 ml ताज़ा पानी और नमक डालकर कुकर में मध्यम आँच पर 7 सीटी लगाएँ, फिर धीमी आँच पर 20 मिनट पकाएँ।"}, "hi-Latn": {"safety": "Rajma ko kabhi bhigone wale paani mein na pakayein aur na hi aadha kachcha chhodein.", "sound": "Cooker se lagataar seeti aur bhaap ki awaaz aati hai.", "text": "Bhigone wala paani nikaal kar phenk dein, dal dho lein, phir 900 ml taaza paani aur namak daalkar cooker mein medium aanch par 7 seeti lagayein, phir dheemi aanch par 20 minute pakayein."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 2400, true, 7, 'Steady hiss and whistles from the cooker.', '{"en": "Steady hiss and whistles from the cooker.", "heat": "medium", "sound": "Steady hiss and whistles from the cooker."}'::jsonb, null, 'Rajma must never be cooked in its soaking water or left half-cooked.'),
  ((select id from public.recipes where household_id is null and slug = 'dal-makhani'), 3, 'Turn off the heat and open the cooker only after the pressure has dropped by itself, then check the rajma; if any bean is not fully soft, cook 2 to 3 more whistles.', '{"en": "Turn off the heat and open the cooker only after the pressure has dropped by itself, then check the rajma; if any bean is not fully soft, cook 2 to 3 more whistles.", "hi": {"safety": "कुकर ज़बरदस्ती कभी न खोलें; प्रेशर अपने आप पूरा निकलने तक रुकें।", "text": "आँच बंद कर दें और कुकर तभी खोलें जब प्रेशर अपने आप पूरा निकल जाए, फिर राजमा जाँचें; अगर कोई दाना पूरा नरम न हो तो 2-3 सीटी और लगाएँ।", "touch": "हर राजमा उंगलियों के बीच पूरा मसल जाए, बीच में कोई सख़्ती न हो।"}, "hi-Latn": {"safety": "Cooker zabardasti kabhi na kholein; pressure apne aap poora nikalne tak rukein.", "text": "Aanch band kar dein aur cooker tabhi kholein jab pressure apne aap poora nikal jaaye, phir rajma check karein; agar koi daana poora naram na ho to 2-3 seeti aur lagayein.", "touch": "Har rajma ungliyon ke beech poora masal jaaye, beech mein koi sakhti na ho."}}'::jsonb, null, 900, true, null, 'Every rajma mashes completely between your fingers with no hard centre.', '{"en": "Every rajma mashes completely between your fingers with no hard centre.", "touch": "Every rajma mashes completely between your fingers with no hard centre."}'::jsonb, null, 'Never force the cooker open; wait till all the pressure is gone on its own.'),
  ((select id from public.recipes where household_id is null and slug = 'dal-makhani'), 4, 'Heat the butter and ghee in a kadai on medium heat, add cumin, then fry the onion until golden.', '{"en": "Heat the butter and ghee in a kadai on medium heat, add cumin, then fry the onion until golden.", "hi": {"look": "प्याज़ नरम और सुनहरा भूरा हो जाता है।", "sound": "गरम घी में जीरा चटकता है।", "text": "कढ़ाई में मध्यम आँच पर मक्खन और घी गरम करें, जीरा डालें, फिर प्याज़ सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram aur sunehra bhoora ho jaata hai.", "sound": "Garam ghee mein jeera chatakta hai.", "text": "Kadai mein medium aanch par makkhan aur ghee garam karein, jeera daalein, phir pyaaz sunehra hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 420, true, null, 'Onion turns soft and golden brown. Cumin crackles as it hits the hot fat.', '{"en": "Onion turns soft and golden brown. Cumin crackles as it hits the hot fat.", "heat": "medium", "look": "Onion turns soft and golden brown.", "sound": "Cumin crackles as it hits the hot fat."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-makhani'), 5, 'Add ginger garlic paste, then the tomato puree and kashmiri chilli powder, and cook the masala, stirring, until the fat separates.', '{"en": "Add ginger garlic paste, then the tomato puree and kashmiri chilli powder, and cook the masala, stirring, until the fat separates.", "hi": {"look": "गाढ़े गहरे लाल मसाले के किनारों पर मक्खन चमकने लगता है।", "smell": "लहसुन की कच्ची महक चली जाती है।", "text": "अदरक लहसुन का पेस्ट डालें, फिर टमाटर की प्यूरी और कश्मीरी लाल मिर्च डालकर चलाते हुए मसाला तब तक भूनें जब तक घी अलग न हो जाए।"}, "hi-Latn": {"look": "Gaadhe gehre laal masale ke kinaaron par makkhan chamakne lagta hai.", "smell": "Lehsun ki kachchi mehak chali jaati hai.", "text": "Adrak lehsun ka paste daalein, phir tamatar ki puree aur kashmiri laal mirch daalkar chalaate hue masala tab tak bhunein jab tak ghee alag na ho jaaye."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 600, true, null, 'Butter shines at the edges of a thick, dark red masala. The raw garlic smell goes away.', '{"en": "Butter shines at the edges of a thick, dark red masala. The raw garlic smell goes away.", "heat": "medium", "look": "Butter shines at the edges of a thick, dark red masala.", "smell": "The raw garlic smell goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-makhani'), 6, 'Lightly mash the cooked dal with a ladle, add it to the masala with about 1 cup water, and simmer on low, stirring often so it does not stick.', '{"en": "Lightly mash the cooked dal with a ladle, add it to the masala with about 1 cup water, and simmer on low, stirring often so it does not stick.", "hi": {"look": "दाल गाढ़ी, मलाईदार और गहरे रंग की हो जाती है।", "sound": "धीमे-धीमे बुलबुले उठते हैं।", "text": "पकी दाल को कलछी से हल्का मसल लें, लगभग 1 कप पानी के साथ मसाले में डालें और धीमी आँच पर पकाएँ, बार-बार चलाते रहें ताकि नीचे न लगे।"}, "hi-Latn": {"look": "Dal gaadhi, malaidaar aur gehre rang ki ho jaati hai.", "sound": "Dheeme-dheeme bulbule uthte hain.", "text": "Paki dal ko kalchhi se halka masal lein, lagbhag 1 cup paani ke saath masale mein daalein aur dheemi aanch par pakayein, baar-baar chalaate rahein taaki neeche na lage."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 1500, true, null, 'The dal turns thick, creamy and dark. Slow, gentle bubbling.', '{"en": "The dal turns thick, creamy and dark. Slow, gentle bubbling.", "heat": "low", "look": "The dal turns thick, creamy and dark.", "sound": "Slow, gentle bubbling."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-makhani'), 7, 'Stir in garam masala, kasuri methi crushed between your palms, and the cream, simmer 5 minutes, and serve hot with the extra butter on top.', '{"en": "Stir in garam masala, kasuri methi crushed between your palms, and the cream, simmer 5 minutes, and serve hot with the extra butter on top.", "hi": {"smell": "मक्खन और कसूरी मेथी की ख़ुशबू आती है।", "text": "गरम मसाला, हथेलियों में मसली कसूरी मेथी और क्रीम मिलाएँ, 5 मिनट धीमी आँच पर पकाएँ और ऊपर से मक्खन डालकर गरमागरम परोसें।"}, "hi-Latn": {"smell": "Makkhan aur kasuri methi ki khushboo aati hai.", "text": "Garam masala, hatheliyon mein masli kasuri methi aur cream milaayein, 5 minute dheemi aanch par pakayein aur upar se makkhan daalkar garmagaram parosein."}}'::jsonb, null, 300, true, null, 'A buttery smell with the scent of kasuri methi.', '{"en": "A buttery smell with the scent of kasuri methi.", "heat": "low", "smell": "A buttery smell with the scent of kasuri methi."}'::jsonb, null, null)
