insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('dal-palak', 'Dal Palak', '{"en": "Dal Palak", "hi": "दाल पालक", "hi-Latn": "Dal Palak"}'::jsonb, 'Everyday toor dal cooked with fresh spinach, onion, tomato and garlic, finished with a ghee and red chilli tadka. Serve with rice or roti.', '{"hi": "रोज़ की अरहर दाल, ताज़े पालक, प्याज़, टमाटर और लहसुन के साथ पकी हुई, ऊपर से घी और लाल मिर्च का तड़का। चावल या रोटी के साथ परोसें।", "hi-Latn": "Roz ki arhar dal, taaze palak, pyaaz, tamatar aur lahsun ke saath paki hui, upar se ghee aur laal mirch ka tadka. Chawal ya roti ke saath parosein."}'::jsonb, 'north_indian', 'main', 'veg', 4, 20, 30, 2, 2, array['pressure_cooker', 'kadai', 'gas_stove']::text[], array['comforting']::text[], '{"acid": 0.2, "crunch": 0, "heat": 0.3, "rich": 0.4, "starch": 0.4, "sweet": 0}'::jsonb, array['dal', 'greens']::text[], 'curated', 'in_review', false)
