insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'dal-palak'), 1, 'Wash the toor dal 2 to 3 times and soak it in water for 15 minutes.', '{"en": "Wash the toor dal 2 to 3 times and soak it in water for 15 minutes.", "hi": {"look": "धोने का पानी लगभग साफ़ दिखने लगे।", "text": "अरहर दाल को 2 से 3 बार धोकर 15 मिनट पानी में भिगो दें।"}, "hi-Latn": {"look": "Dhone ka paani lagbhag saaf dikhne lage.", "text": "Arhar dal ko 2 se 3 baar dhokar 15 minute paani mein bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 900, true, null, 'The washing water runs almost clear.', '{"en": "The washing water runs almost clear.", "look": "The washing water runs almost clear."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-palak'), 2, 'Drain the dal, put it in the pressure cooker with 3 cups water, the turmeric and half the salt, and cook for 3 whistles on medium heat.', '{"en": "Drain the dal, put it in the pressure cooker with 3 cups water, the turmeric and half the salt, and cook for 3 whistles on medium heat.", "hi": {"look": "दाल पूरी नरम हो और चलाने पर घुल जाए।", "safety": "ढक्कन खोलने से पहले प्रेशर अपने आप निकलने दें।", "text": "दाल का पानी निकालकर कुकर में 3 कप पानी, हल्दी और आधा नमक डालें और मध्यम आंच पर 3 सीटी आने दें।", "touch": "दाल का दाना उंगलियों के बीच आसानी से मसल जाए।"}, "hi-Latn": {"look": "Dal poori naram ho aur chalane par ghul jaaye.", "safety": "Dhakkan kholne se pehle pressure apne aap nikalne dein.", "text": "Dal ka paani nikaalkar cooker mein 3 cup paani, haldi aur aadha namak daalein aur medium aanch par 3 seeti aane dein.", "touch": "Dal ka daana ungliyon ke beech aasaani se masal jaaye."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 720, true, 3, 'The dal is fully soft and breaks down when stirred. A grain mashes easily between your fingers.', '{"en": "The dal is fully soft and breaks down when stirred. A grain mashes easily between your fingers.", "heat": "medium", "look": "The dal is fully soft and breaks down when stirred.", "touch": "A grain mashes easily between your fingers."}'::jsonb, null, 'Let the pressure drop on its own before you open the lid.'),
  ((select id from public.recipes where household_id is null and slug = 'dal-palak'), 3, 'While the dal cooks, wash the spinach in a big bowl of water 2 to 3 times and chop it roughly.', '{"en": "While the dal cooks, wash the spinach in a big bowl of water 2 to 3 times and chop it roughly.", "hi": {"look": "बर्तन की तली में मिट्टी या रेत न बचे।", "text": "दाल पकने तक पालक को बड़े बर्तन में पानी में 2 से 3 बार धोएं और मोटा-मोटा काट लें।"}, "hi-Latn": {"look": "Bartan ki tali mein mitti ya ret na bache.", "text": "Dal pakne tak palak ko bade bartan mein paani mein 2 se 3 baar dhoyein aur mota-mota kaat lein."}}'::jsonb, null, null, false, null, 'No mud or grit is left at the bottom of the bowl.', '{"en": "No mud or grit is left at the bottom of the bowl.", "look": "No mud or grit is left at the bottom of the bowl."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-palak'), 4, 'Heat the ghee in a kadai, add cumin and hing, then the chopped garlic, ginger, green chilli and onion, and fry until the onion turns golden.', '{"en": "Heat the ghee in a kadai, add cumin and hing, then the chopped garlic, ginger, green chilli and onion, and fry until the onion turns golden.", "hi": {"look": "प्याज़ नरम और किनारों से सुनहरा हो जाए।", "smell": "लहसुन की कच्ची नहीं, भुनी हुई खुशबू आए।", "sound": "घी में डालते ही जीरा चटकने लगे।", "text": "कढ़ाई में घी गरम करें, जीरा और हींग डालें, फिर कटा लहसुन, अदरक, हरी मिर्च और प्याज़ डालकर प्याज़ सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram aur kinaaron se sunehra ho jaaye.", "smell": "Lahsun ki kachchi nahin, bhuni hui khushboo aaye.", "sound": "Ghee mein daalte hi jeera chatakne lage.", "text": "Kadai mein ghee garam karein, jeera aur hing daalein, phir kata lahsun, adrak, hari mirch aur pyaaz daalkar pyaaz sunehra hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 360, true, null, 'The onion turns soft and golden at the edges. The cumin crackles as soon as it hits the ghee. The garlic smells nutty, not raw.', '{"en": "The onion turns soft and golden at the edges. The cumin crackles as soon as it hits the ghee. The garlic smells nutty, not raw.", "heat": "medium", "look": "The onion turns soft and golden at the edges.", "smell": "The garlic smells nutty, not raw.", "sound": "The cumin crackles as soon as it hits the ghee."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-palak'), 5, 'Add the chopped tomato, red chilli powder and coriander powder and cook until the tomato is mushy.', '{"en": "Add the chopped tomato, red chilli powder and coriander powder and cook until the tomato is mushy.", "hi": {"look": "मसाले के किनारों पर घी दिखने लगे।", "text": "कटा टमाटर, लाल मिर्च पाउडर और धनिया पाउडर डालें और टमाटर गलने तक पकाएं।"}, "hi-Latn": {"look": "Masale ke kinaaron par ghee dikhne lage.", "text": "Kata tamatar, laal mirch powder aur dhaniya powder daalein aur tamatar galne tak pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 300, true, null, 'Ghee starts showing at the edges of the masala.', '{"en": "Ghee starts showing at the edges of the masala.", "heat": "medium", "look": "Ghee starts showing at the edges of the masala."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-palak'), 6, 'Add the spinach and stir until it wilts.', '{"en": "Add the spinach and stir until it wilts.", "hi": {"look": "पालक सिकुड़कर गहरा हरा हो जाए।", "text": "पालक डालें और मुरझाने तक चलाते रहें।"}, "hi-Latn": {"look": "Palak sikudkar gehra hara ho jaaye.", "text": "Palak daalein aur murjhaane tak chalaate rahein."}}'::jsonb, null, 180, true, null, 'The spinach shrinks and turns a deep green.', '{"en": "The spinach shrinks and turns a deep green.", "heat": "medium", "look": "The spinach shrinks and turns a deep green."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-palak'), 7, 'Whisk the cooked dal lightly, pour it into the kadai with the rest of the salt and about 1 cup water, and simmer for 8 minutes.', '{"en": "Whisk the cooked dal lightly, pour it into the kadai with the rest of the salt and about 1 cup water, and simmer for 8 minutes.", "hi": {"look": "दाल गाढ़ी हो पर कलछी से बहती रहे।", "safety": "ढक्कन आधा ढक कर रखें, क्योंकि गाढ़ी दाल छींटे मारती है।", "text": "पकी दाल को हल्का घोंट लें, बचा नमक और करीब 1 कप पानी के साथ कढ़ाई में डालें और 8 मिनट धीमी आंच पर उबालें।"}, "hi-Latn": {"look": "Dal gaadhi ho par kalchhi se behti rahe.", "safety": "Dhakkan aadha dhak kar rakhein, kyunki gaadhi dal chheente maarti hai.", "text": "Paki dal ko halka ghont lein, bacha namak aur kareeb 1 cup paani ke saath kadai mein daalein aur 8 minute dheemi aanch par ubaalein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 480, true, null, 'The dal is thick but still pours from the ladle.', '{"en": "The dal is thick but still pours from the ladle.", "heat": "low", "look": "The dal is thick but still pours from the ladle."}'::jsonb, null, 'Keep the lid half on, because thick dal splutters.'),
  ((select id from public.recipes where household_id is null and slug = 'dal-palak'), 8, 'For the tadka, heat the remaining ghee in a small pan, add the broken dry red chillies, and pour it over the dal; squeeze in lemon off the heat if you like.', '{"en": "For the tadka, heat the remaining ghee in a small pan, add the broken dry red chillies, and pour it over the dal; squeeze in lemon off the heat if you like.", "hi": {"look": "मिर्च हल्की गहरी हो, पर काली न पड़े।", "sound": "दाल पर डालते ही तड़का ज़ोर से छनके।", "text": "तड़के के लिए छोटे बर्तन में बचा घी गरम करें, टूटी सूखी लाल मिर्च डालें और दाल पर डाल दें; पसंद हो तो गैस बंद करके नींबू निचोड़ें।"}, "hi-Latn": {"look": "Mirch halki gehri ho, par kaali na pade.", "sound": "Dal par daalte hi tadka zor se chhanke.", "text": "Tadke ke liye chhote bartan mein bacha ghee garam karein, tooti sookhi laal mirch daalein aur dal par daal dein; pasand ho to gas band karke nimbu nichodein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The chillies darken slightly but do not turn black. The tadka sizzles loudly as it hits the dal.', '{"en": "The chillies darken slightly but do not turn black. The tadka sizzles loudly as it hits the dal.", "heat": "medium", "look": "The chillies darken slightly but do not turn black.", "sound": "The tadka sizzles loudly as it hits the dal."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'dal-palak') and step_no > 8;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'dal-palak');

-- Recipe: dal-tadka (draft, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('dal-tadka', 'Dal Tadka', '{"en": "Dal Tadka", "hi": "दाल तड़का", "hi-Latn": "Dal Tadka"}'::jsonb, 'Everyday arhar dal, pressure-cooked soft and finished with a ghee tadka of cumin, garlic, onion and tomato.', '{"hi": "रोज़ की अरहर दाल, कुकर में नरम पकी, ऊपर से जीरा, लहसुन, प्याज़ और टमाटर का घी वाला तड़का।", "hi-Latn": "Roz ki arhar daal, cooker mein naram paki, upar se jeera, lahsun, pyaaz aur tamatar ka ghee wala tadka."}'::jsonb, 'generic_north', 'main', 'veg', 4, 25, 25, 2, 2, array['pressure_cooker', 'kadai']::text[], array['comforting', 'high_protein']::text[], '{"acid": 0.3, "crunch": 0, "heat": 0.3, "rich": 0.5, "starch": 0.4, "sweet": 0}'::jsonb, array['dal']::text[], 'curated', 'draft', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
  description = excluded.description, descriptions = excluded.descriptions, cuisine_region = excluded.cuisine_region, course = excluded.course,
  diet = excluded.diet, base_servings = excluded.base_servings, prep_time_min = excluded.prep_time_min,
  cook_time_min = excluded.cook_time_min, difficulty = excluded.difficulty,
  spice_level = excluded.spice_level, equipment = excluded.equipment, tags = excluded.tags,
  flavor_profile = excluded.flavor_profile, food_groups = excluded.food_groups,
  review_status = excluded.review_status, is_published = excluded.is_published;

