  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 'diet', '{"diet": "jain"}'::jsonb, '{"add": [{"ingredient": "asafoetida", "qty": 0.2, "unit": "g"}], "omit": ["onion", "garlic", "ginger"]}'::jsonb, 'A pinch more hing and a little tomato keep the flavour.'),
  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 'equipment', '{"missing_equipment": "pressure_cooker"}'::jsonb, '{"at_step": 2, "method": "simmer", "minutes": 45}'::jsonb, 'Simmer in a covered pot with extra water, stirring, until soft.');

-- Recipe: dosa (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('dosa', 'Dosa', '{"en": "Dosa", "hi": "डोसा", "hi-Latn": "Dosa"}'::jsonb, 'A thin, crisp South Indian crepe made from a fermented rice and urad dal batter, cooked on a hot tawa with a little oil. Serve with sambar and chutney.', '{"hi": "चावल और उड़द दाल के खमीर वाले घोल से बना पतला, कुरकुरा दक्षिण भारतीय डोसा, जो गरम तवे पर थोड़े तेल में सेंका जाता है। सांबर और चटनी के साथ परोसें।", "hi-Latn": "Chawal aur urad dal ke khameer wale ghol se bana patla, kurkura South Indian dosa, jo garam tawe par thode tel mein senka jaata hai. Sambar aur chutney ke saath parosein."}'::jsonb, 'south_indian', 'breakfast', 'vegan', 4, 30, 30, 3, 1, array['mixer_grinder', 'tawa', 'gas_stove']::text[], array['kids_friendly', 'tiffin']::text[], '{"acid": 0.3, "crunch": 0.6, "heat": 0, "rich": 0.2, "starch": 0.8, "sweet": 0}'::jsonb, array['grain', 'dal']::text[], 'curated', 'in_review', false)
