insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'dosa'), 1, 'Wash the rice, and separately wash the urad dal with the fenugreek seeds, then soak both in plenty of water for 5 to 6 hours.', '{"en": "Wash the rice, and separately wash the urad dal with the fenugreek seeds, then soak both in plenty of water for 5 to 6 hours.", "hi": {"look": "दाने फूल जाते हैं और दाल दबाने पर आसानी से टूट जाती है।", "text": "चावल धो लें, और अलग से उड़द दाल को मेथी दाने के साथ धो लें, फिर दोनों को भरपूर पानी में 5 से 6 घंटे भिगो दें।"}, "hi-Latn": {"look": "Daane phool jaate hain aur dal dabane par aasaani se toot jaati hai.", "text": "Chawal dho lein, aur alag se urad dal ko methi dane ke saath dho lein, phir dono ko bharpoor paani mein 5 se 6 ghante bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 21600, true, null, 'The grains swell and the dal breaks easily when pressed.', '{"en": "The grains swell and the dal breaks easily when pressed.", "look": "The grains swell and the dal breaks easily when pressed."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dosa'), 2, 'Drain and grind the urad dal and fenugreek with a little cold water into a smooth, fluffy batter, then grind the rice slightly grainy and mix both together.', '{"en": "Drain and grind the urad dal and fenugreek with a little cold water into a smooth, fluffy batter, then grind the rice slightly grainy and mix both together.", "hi": {"text": "पानी निकालकर उड़द दाल और मेथी को थोड़े ठंडे पानी के साथ चिकना और फूला हुआ पीस लें, फिर चावल को हल्का दरदरा पीसें और दोनों को मिला लें।", "touch": "उड़द दाल का घोल उंगलियों में हल्का, फूला और चिकना लगता है।"}, "hi-Latn": {"text": "Paani nikaal kar urad dal aur methi ko thode thande paani ke saath chikna aur phoola hua pees lein, phir chawal ko halka dardara peesein aur dono ko mila lein.", "touch": "Urad dal ka ghol ungliyon mein halka, phoola aur chikna lagta hai."}}'::jsonb, (select id from public.techniques where slug = 'batter'), 900, true, null, 'The urad dal batter feels light, airy and smooth between your fingers.', '{"en": "The urad dal batter feels light, airy and smooth between your fingers.", "touch": "The urad dal batter feels light, airy and smooth between your fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dosa'), 3, 'Add the salt, mix well with your hand, cover and leave in a warm place overnight, 8 to 10 hours, to ferment.', '{"en": "Add the salt, mix well with your hand, cover and leave in a warm place overnight, 8 to 10 hours, to ferment.", "hi": {"look": "घोल फूलकर ऊपर आ जाता है और छोटे-छोटे बुलबुलों से भर जाता है।", "safety": "खमीर उठने के बाद घोल फ्रिज में रखें और 2 से 3 दिन में इस्तेमाल कर लें।", "smell": "हल्की खट्टी अच्छी खुशबू आती है।", "text": "नमक डालें, हाथ से अच्छी तरह मिलाएं, ढककर रात भर 8 से 10 घंटे गरम जगह पर खमीर उठने के लिए रख दें।"}, "hi-Latn": {"look": "Ghol phool kar upar aa jaata hai aur chhote-chhote bulbulon se bhar jaata hai.", "safety": "Khameer uthne ke baad ghol fridge mein rakhein aur 2 se 3 din mein istemaal kar lein.", "smell": "Halki khatti achhi khushboo aati hai.", "text": "Namak daalein, haath se achhi tarah milayein, dhak kar raat bhar 8 se 10 ghante garam jagah par khameer uthne ke liye rakh dein."}}'::jsonb, (select id from public.techniques where slug = 'batter'), 32400, true, null, 'The batter rises and is full of tiny bubbles. It smells pleasantly sour.', '{"en": "The batter rises and is full of tiny bubbles. It smells pleasantly sour.", "look": "The batter rises and is full of tiny bubbles.", "smell": "It smells pleasantly sour."}'::jsonb, null, 'Once fermented, keep the batter in the fridge and use it within 2 to 3 days.'),
  ((select id from public.recipes where household_id is null and slug = 'dosa'), 4, 'Stir the batter gently and add a little water to make it a thick pouring consistency.', '{"en": "Stir the batter gently and add a little water to make it a thick pouring consistency.", "hi": {"look": "घोल करछी पर चिपकता है और गाढ़ी छाछ की तरह धीरे बहता है।", "text": "घोल को हल्के से चलाएं और थोड़ा पानी डालकर गाढ़ा बहने लायक बना लें।"}, "hi-Latn": {"look": "Ghol karchhi par chipakta hai aur gaadhi chhaachh ki tarah dheere behta hai.", "text": "Ghol ko halke se chalayein aur thoda paani daal kar gaadha behne laayak bana lein."}}'::jsonb, null, null, false, null, 'It coats the ladle and flows slowly, like thick buttermilk.', '{"en": "It coats the ladle and flows slowly, like thick buttermilk.", "look": "It coats the ladle and flows slowly, like thick buttermilk."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dosa'), 5, 'Heat the tawa on medium-high, rub it with a few drops of oil, then sprinkle a little water and wipe it off.', '{"en": "Heat the tawa on medium-high, rub it with a few drops of oil, then sprinkle a little water and wipe it off.", "hi": {"safety": "गरम तवे पर पानी छिड़कते समय थोड़ा पीछे हटें, भाप उछलती है।", "sound": "पानी छन्न से आवाज़ करके तुरंत सूख जाता है।", "text": "तवा तेज़-मध्यम आंच पर गरम करें, कुछ बूंद तेल लगाएं, फिर थोड़ा पानी छिड़ककर पोंछ दें।"}, "hi-Latn": {"safety": "Garam tawe par paani chhidakte samay thoda peeche hatein, bhaap uchhalti hai.", "sound": "Paani chhann se awaaz karke turant sookh jaata hai.", "text": "Tawa tez-medium aanch par garam karein, kuch boond tel lagayein, phir thoda paani chhidak kar ponchh dein."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 180, true, null, 'The water sizzles and dries up at once.', '{"en": "The water sizzles and dries up at once.", "heat": "high", "sound": "The water sizzles and dries up at once."}'::jsonb, null, 'Stand back when sprinkling water on the hot tawa, as it spits steam.'),
  ((select id from public.recipes where household_id is null and slug = 'dosa'), 6, 'Lower the heat to medium, pour a ladle of batter in the centre and quickly spread it in circles outward into a thin round.', '{"en": "Lower the heat to medium, pour a ladle of batter in the centre and quickly spread it in circles outward into a thin round.", "hi": {"look": "घोल पतला जम जाता है और ऊपर छोटे-छोटे छेद दिखते हैं।", "text": "आंच मध्यम करें, बीच में एक करछी घोल डालें और जल्दी से गोल-गोल घुमाते हुए बाहर की ओर पतला फैला दें।"}, "hi-Latn": {"look": "Ghol patla jam jaata hai aur upar chhote-chhote chhed dikhte hain.", "text": "Aanch medium karein, beech mein ek karchhi ghol daalein aur jaldi se gol-gol ghumate hue bahar ki or patla phaila dein."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), null, false, null, 'The batter sets thin with small holes all over.', '{"en": "The batter sets thin with small holes all over.", "heat": "medium", "look": "The batter sets thin with small holes all over."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dosa'), 7, 'Drizzle half a teaspoon of oil around the edges and on top, and cook for about 2 minutes until the base is golden and crisp.', '{"en": "Drizzle half a teaspoon of oil around the edges and on top, and cook for about 2 minutes until the base is golden and crisp.", "hi": {"look": "नीचे का हिस्सा सुनहरा हो जाता है और किनारे तवे से उठने लगते हैं।", "smell": "सिंकने की भुनी हुई खुशबू आती है।", "sound": "किनारों पर तेल हल्का छन-छन करता है।", "text": "किनारों पर और ऊपर आधा छोटा चम्मच तेल डालें और लगभग 2 मिनट तक सेंकें, जब तक नीचे से सुनहरा और कुरकुरा न हो जाए।"}, "hi-Latn": {"look": "Neeche ka hissa sunehra ho jaata hai aur kinare tawe se uthne lagte hain.", "smell": "Sikne ki bhuni hui khushboo aati hai.", "sound": "Kinaron par tel halka chhan-chhan karta hai.", "text": "Kinaron par aur upar aadha chhota chammach tel daalein aur lagbhag 2 minute tak senkein, jab tak neeche se sunehra aur kurkura na ho jaaye."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 120, false, null, 'The underside turns golden and the edges lift away from the tawa. The oil sizzles softly around the edges. A toasty roasted smell rises.', '{"en": "The underside turns golden and the edges lift away from the tawa. The oil sizzles softly around the edges. A toasty roasted smell rises.", "heat": "medium", "look": "The underside turns golden and the edges lift away from the tawa.", "smell": "A toasty roasted smell rises.", "sound": "The oil sizzles softly around the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dosa'), 8, 'Fold the dosa and serve hot, then sprinkle water and wipe the tawa before making the next one.', '{"en": "Fold the dosa and serve hot, then sprinkle water and wipe the tawa before making the next one.", "hi": {"text": "डोसा मोड़कर गरम परोसें, फिर अगला बनाने से पहले तवे पर पानी छिड़ककर पोंछ लें।", "touch": "उठाने पर डोसा कुरकुरा और कड़क लगता है।"}, "hi-Latn": {"text": "Dosa mod kar garam parosein, phir agla banane se pehle tawe par paani chhidak kar ponchh lein.", "touch": "Uthane par dosa kurkura aur kadak lagta hai."}}'::jsonb, null, null, false, null, 'The dosa feels crisp and stiff when lifted.', '{"en": "The dosa feels crisp and stiff when lifted.", "heat": "medium", "touch": "The dosa feels crisp and stiff when lifted."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
