insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('dum-aloo', 'Dum Aloo', '{"en": "Dum Aloo", "hi": "दम आलू", "hi-Latn": "Dum Aloo"}'::jsonb, 'Small boiled potatoes, lightly fried and slow-cooked on low heat in a thick onion, tomato and curd gravy. A Punjabi-style weekday sabzi that goes with roti, paratha or rice.', '{"hi": "छोटे उबले आलू, हल्के तले हुए और प्याज़, टमाटर और दही की गाढ़ी ग्रेवी में धीमी आँच पर पकाए हुए। रोटी, पराठे या चावल के साथ खाई जाने वाली पंजाबी अंदाज़ की रोज़ की सब्ज़ी।", "hi-Latn": "Chhote uble aloo, halke tale hue aur pyaaz, tamatar aur dahi ki gaadhi gravy mein dheemi aanch par pakaye hue. Roti, paratha ya chawal ke saath khayi jaane wali Punjabi andaaz ki roz ki sabzi."}'::jsonb, 'punjabi_north_indian', 'main', 'veg', 4, 15, 40, 2, 3, array['pressure_cooker', 'kadai', 'gas_stove']::text[], array['comforting']::text[], '{"acid": 0.3, "crunch": 0, "heat": 0.4, "rich": 0.6, "starch": 0.7, "sweet": 0.1}'::jsonb, array['sabzi', 'dairy']::text[], 'curated', 'in_review', false)
