insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'dum-aloo'), 1, 'Pressure-cook the washed potatoes with enough water to cover for 2 whistles, let the pressure drop on its own, then peel them.', '{"en": "Pressure-cook the washed potatoes with enough water to cover for 2 whistles, let the pressure drop on its own, then peel them.", "hi": {"safety": "कुकर प्रेशर पूरी तरह उतरने के बाद ही खोलें।", "text": "धुले हुए आलू को डूबने लायक पानी के साथ कुकर में 2 सीटी तक पकाएँ, प्रेशर अपने आप उतरने दें, फिर छील लें।", "touch": "चाकू आसानी से जाए पर आलू टूटे नहीं।"}, "hi-Latn": {"safety": "Cooker pressure poori tarah utarne ke baad hi kholein.", "text": "Dhule hue aloo ko doobne laayak paani ke saath cooker mein 2 seeti tak pakayein, pressure apne aap utarne dein, phir chheel lein.", "touch": "Chaaku aasaani se jaaye par aloo toote nahi."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), null, false, 2, 'A knife should go in easily but the potato should still hold its shape.', '{"en": "A knife should go in easily but the potato should still hold its shape.", "heat": "medium", "touch": "A knife should go in easily but the potato should still hold its shape."}'::jsonb, null, 'Open the cooker only after the pressure has fully dropped.'),
  ((select id from public.recipes where household_id is null and slug = 'dum-aloo'), 2, 'Prick each potato with a fork and fry them in the hot oil in a kadai, turning often, until golden in patches, then lift them out.', '{"en": "Prick each potato with a fork and fry them in the hot oil in a kadai, turning often, until golden in patches, then lift them out.", "hi": {"look": "आलू पर चारों तरफ़ सुनहरे-भूरे धब्बे आ जाएँ।", "safety": "आलू अच्छे से सुखा लें ताकि तेल न उछले।", "text": "हर आलू में काँटे से छेद करें और कड़ाही में गरम तेल में बार-बार पलटते हुए सुनहरा होने तक तलें, फिर निकाल लें।"}, "hi-Latn": {"look": "Aloo par chaaron taraf sunehre-bhure dhabbe aa jaayein.", "safety": "Aloo achhe se sukha lein taaki tel na uchhle.", "text": "Har aloo mein kaante se chhed karein aur kadai mein garam tel mein baar-baar palatte hue sunehra hone tak talein, phir nikaal lein."}}'::jsonb, (select id from public.techniques where slug = 'shallow_fry'), 360, true, null, 'Golden-brown spots all over the potatoes.', '{"en": "Golden-brown spots all over the potatoes.", "heat": "medium", "look": "Golden-brown spots all over the potatoes."}'::jsonb, null, 'Dry the potatoes well so the oil does not splutter.'),
  ((select id from public.recipes where household_id is null and slug = 'dum-aloo'), 3, 'In the same oil, add cumin seeds and bay leaf, then add the onion and fry until golden brown.', '{"en": "In the same oil, add cumin seeds and bay leaf, then add the onion and fry until golden brown.", "hi": {"look": "प्याज़ एक जैसे सुनहरे भूरे हो जाएँ।", "sound": "तेल में डालते ही जीरा चटकने लगे।", "text": "उसी तेल में जीरा और तेज पत्ता डालें, फिर प्याज़ डालकर सुनहरा भूरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz ek jaise sunehre bhure ho jaayein.", "sound": "Tel mein daalte hi jeera chatakne lage.", "text": "Usi tel mein jeera aur tej patta daalein, phir pyaaz daalkar sunehra bhura hone tak bhoonein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 480, true, null, 'Onions turn an even golden brown. Cumin seeds crackle as soon as they hit the oil.', '{"en": "Onions turn an even golden brown. Cumin seeds crackle as soon as they hit the oil.", "heat": "medium", "look": "Onions turn an even golden brown.", "sound": "Cumin seeds crackle as soon as they hit the oil."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dum-aloo'), 4, 'Add ginger garlic paste, then the tomato, turmeric, chilli powder and coriander powder, and cook the masala until oil separates.', '{"en": "Add ginger garlic paste, then the tomato, turmeric, chilli powder and coriander powder, and cook the masala until oil separates.", "hi": {"look": "मसाले के किनारों पर तेल दिखने लगे।", "smell": "अदरक-लहसुन की कच्ची महक चली जाए।", "text": "अदरक-लहसुन का पेस्ट डालें, फिर टमाटर, हल्दी, मिर्च पाउडर और धनिया पाउडर डालकर मसाले को तेल छोड़ने तक भूनें।"}, "hi-Latn": {"look": "Masale ke kinaaron par tel dikhne lage.", "smell": "Adrak-lehsun ki kachchi mehak chali jaaye.", "text": "Adrak-lehsun ka paste daalein, phir tamatar, haldi, mirch powder aur dhaniya powder daalkar masale ko tel chhodne tak bhoonein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 420, true, null, 'Oil shows at the edges of the masala. The raw smell of ginger garlic is gone.', '{"en": "Oil shows at the edges of the masala. The raw smell of ginger garlic is gone.", "heat": "medium", "look": "Oil shows at the edges of the masala.", "smell": "The raw smell of ginger garlic is gone."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dum-aloo'), 5, 'Turn the heat to low and add the whisked curd a little at a time, stirring all the while, and cook for 3 minutes.', '{"en": "Turn the heat to low and add the whisked curd a little at a time, stirring all the while, and cook for 3 minutes.", "hi": {"look": "ग्रेवी चिकनी और मलाईदार हो जाए, कोई सफ़ेद दाने न दिखें।", "text": "आँच धीमी करें और फेंटा हुआ दही थोड़ा-थोड़ा करके लगातार चलाते हुए डालें, 3 मिनट पकाएँ।"}, "hi-Latn": {"look": "Gravy chikni aur malaidaar ho jaaye, koi safed daane na dikhein.", "text": "Aanch dheemi karein aur phenta hua dahi thoda-thoda karke lagaataar chalaate hue daalein, 3 minute pakayein."}}'::jsonb, null, 180, true, null, 'The gravy turns smooth and creamy, with no white specks.', '{"en": "The gravy turns smooth and creamy, with no white specks.", "heat": "low", "look": "The gravy turns smooth and creamy, with no white specks."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dum-aloo'), 6, 'Add the fried potatoes, salt and about 1 cup of hot water, stir, cover tightly and cook on low heat.', '{"en": "Add the fried potatoes, salt and about 1 cup of hot water, stir, cover tightly and cook on low heat.", "hi": {"look": "ग्रेवी गाढ़ी होकर आलू पर लिपट जाए।", "text": "तले हुए आलू, नमक और लगभग 1 कप गरम पानी डालें, मिलाएँ, ढक्कन कसकर लगाएँ और धीमी आँच पर पकाएँ।"}, "hi-Latn": {"look": "Gravy gaadhi hokar aloo par lipat jaaye.", "text": "Tale hue aloo, namak aur lagbhag 1 cup garam paani daalein, milaayein, dhakkan kaskar lagaayein aur dheemi aanch par pakayein."}}'::jsonb, (select id from public.techniques where slug = 'dum'), 720, true, null, 'The gravy thickens and coats the potatoes.', '{"en": "The gravy thickens and coats the potatoes.", "heat": "low", "look": "The gravy thickens and coats the potatoes."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dum-aloo'), 7, 'Stir in garam masala, crushed kasuri methi and cream, switch off the heat and garnish with coriander leaves.', '{"en": "Stir in garam masala, crushed kasuri methi and cream, switch off the heat and garnish with coriander leaves.", "hi": {"smell": "मेथी और गरम मसाले की खुशबू उठने लगे।", "text": "गरम मसाला, मसली हुई कसूरी मेथी और मलाई मिलाएँ, आँच बंद करें और हरा धनिया डालकर सजाएँ।"}, "hi-Latn": {"smell": "Methi aur garam masale ki khushboo uthne lage.", "text": "Garam masala, masli hui kasuri methi aur malai milaayein, aanch band karein aur hara dhaniya daalkar sajaayein."}}'::jsonb, null, 60, false, null, 'A warm smell of methi and garam masala rises.', '{"en": "A warm smell of methi and garam masala rises.", "heat": "low", "smell": "A warm smell of methi and garam masala rises."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'dum-aloo') and step_no > 7;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'dum-aloo');

