-- Recipe: egg-paratha (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('egg-paratha', 'Egg Paratha', '{"en": "Egg Paratha", "hi": "अंडा पराठा", "hi-Latn": "Anda Paratha"}'::jsonb, 'Soft whole wheat parathas cooked on the tawa with a spiced egg, onion and green chilli layer stuck to one side. A filling weekday breakfast or tiffin.', '{"hi": "गेहूं के आटे के नरम पराठे, जिनकी एक तरफ तवे पर मसालेदार अंडा, प्याज़ और हरी मिर्च की परत सेंकी जाती है। रोज़ के नाश्ते या टिफ़िन के लिए पेट भरने वाला पराठा।", "hi-Latn": "Gehun ke aate ke naram parathe, jinki ek taraf tawe par masaledaar anda, pyaaz aur hari mirch ki parat senki jaati hai. Roz ke naashte ya tiffin ke liye pet bharne wala paratha."}'::jsonb, 'north_indian', 'breakfast', 'eggetarian', 4, 25, 20, 2, 2, array['tawa', 'gas_stove']::text[], array['comforting', 'kids_friendly', 'tiffin', 'high_protein']::text[], '{"acid": 0.1, "crunch": 0.2, "heat": 0.3, "rich": 0.5, "starch": 0.7, "sweet": 0}'::jsonb, array['grain', 'protein']::text[], 'curated', 'in_review', false)
