insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'egg-paratha'), 1, 'Mix the flour, salt and oil, add about 150 ml water little by little and knead a soft dough, then cover and rest it for 15 minutes.', '{"en": "Mix the flour, salt and oil, add about 150 ml water little by little and knead a soft dough, then cover and rest it for 15 minutes.", "hi": {"text": "आटा, नमक और तेल मिलाएं, लगभग 150 मिली पानी थोड़ा-थोड़ा डालकर नरम आटा गूंध लें, फिर ढककर 15 मिनट रख दें।", "touch": "आटा नरम और चिकना लगे और उंगलियों पर न चिपके।"}, "hi-Latn": {"text": "Atta, namak aur tel milayein, lagbhag 150 ml paani thoda-thoda daalkar naram atta goondh lein, phir dhakkar 15 minute rakh dein.", "touch": "Atta naram aur chikna lage aur ungliyon par na chipke."}}'::jsonb, (select id from public.techniques where slug = 'knead'), 900, true, null, 'The dough feels soft and smooth and does not stick to your fingers.', '{"en": "The dough feels soft and smooth and does not stick to your fingers.", "touch": "The dough feels soft and smooth and does not stick to your fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'egg-paratha'), 2, 'Beat the eggs in a bowl with the onion, green chilli, coriander leaves, red chilli powder and salt until frothy.', '{"en": "Beat the eggs in a bowl with the onion, green chilli, coriander leaves, red chilli powder and salt until frothy.", "hi": {"look": "मिश्रण एक जैसा पीला और ऊपर से थोड़ा झागदार दिखे।", "text": "एक कटोरे में अंडे, प्याज़, हरी मिर्च, हरा धनिया, लाल मिर्च पाउडर और नमक डालकर झागदार होने तक फेंट लें।"}, "hi-Latn": {"look": "Mixture ek jaisa peela aur upar se thoda jhaagdaar dikhe.", "text": "Ek katori mein ande, pyaaz, hari mirch, hara dhaniya, laal mirch powder aur namak daalkar jhaagdaar hone tak phent lein."}}'::jsonb, null, null, false, null, 'The mixture looks evenly yellow and a little frothy on top.', '{"en": "The mixture looks evenly yellow and a little frothy on top.", "look": "The mixture looks evenly yellow and a little frothy on top."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'egg-paratha'), 3, 'Divide the dough into 4 balls and roll each one into a round about 7 inches wide, dusting with a little flour.', '{"en": "Divide the dough into 4 balls and roll each one into a round about 7 inches wide, dusting with a little flour.", "hi": {"text": "आटे की 4 लोइयां बनाएं और थोड़ा सूखा आटा लगाकर हर लोई को लगभग 7 इंच का गोल बेल लें।"}, "hi-Latn": {"text": "Aate ki 4 loiyan banayein aur thoda sookha atta lagakar har loi ko lagbhag 7 inch ka gol bel lein."}}'::jsonb, (select id from public.techniques where slug = 'shape'), null, false, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'egg-paratha'), 4, 'Cook one rolled paratha on a hot tawa on medium heat for about 1 minute on each side.', '{"en": "Cook one rolled paratha on a hot tawa on medium heat for about 1 minute on each side.", "hi": {"look": "हल्के भूरे धब्बे दिखें और पराठा जगह-जगह से फूलने लगे।", "text": "एक बेले हुए पराठे को गरम तवे पर मध्यम आंच पर हर तरफ लगभग 1 मिनट सेंकें।"}, "hi-Latn": {"look": "Halke bhoore dhabbe dikhein aur paratha jagah-jagah se phoolne lage.", "text": "Ek bele hue parathe ko garam tawe par medium aanch par har taraf lagbhag 1 minute senkein."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 120, false, null, 'Light brown spots appear and the paratha starts to puff in places.', '{"en": "Light brown spots appear and the paratha starts to puff in places.", "heat": "medium", "look": "Light brown spots appear and the paratha starts to puff in places."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'egg-paratha'), 5, 'Lift the paratha off, spread a little ghee on the tawa, pour a quarter of the stirred egg mixture and spread it into a round, then press the paratha on top at once.', '{"en": "Lift the paratha off, spread a little ghee on the tawa, pour a quarter of the stirred egg mixture and spread it into a round, then press the paratha on top at once.", "hi": {"look": "अंडा पराठे से चिपक जाए और किनारे जमने लगें।", "sound": "तवे पर पड़ते ही अंडा छनछनाए।", "text": "पराठा उठा लें, तवे पर थोड़ा घी फैलाएं, अंडे के मिश्रण को चलाकर उसका चौथाई हिस्सा डालें और गोल फैला दें, फिर तुरंत उसके ऊपर पराठा रखकर दबाएं।"}, "hi-Latn": {"look": "Anda parathe se chipak jaaye aur kinare jamne lagein.", "sound": "Tawe par padte hi anda chhanchhanaye.", "text": "Paratha utha lein, tawe par thoda ghee phailayein, ande ke mixture ko chalakar uska chauthai hissa daalein aur gol phaila dein, phir turant uske upar paratha rakhkar dabayein."}}'::jsonb, null, 60, false, null, 'The egg sticks to the paratha and the edges start to set. The egg sizzles as it hits the tawa.', '{"en": "The egg sticks to the paratha and the edges start to set. The egg sizzles as it hits the tawa.", "heat": "medium", "look": "The egg sticks to the paratha and the edges start to set.", "sound": "The egg sizzles as it hits the tawa."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'egg-paratha'), 6, 'Flip so the egg side faces up, drizzle ghee around the edges and cook for 2 to 3 minutes, flipping once more, until both sides are golden and the egg is fully cooked.', '{"en": "Flip so the egg side faces up, drizzle ghee around the edges and cook for 2 to 3 minutes, flipping once more, until both sides are golden and the egg is fully cooked.", "hi": {"look": "अंडे की परत सुनहरी हो और कहीं गीला या बहता हिस्सा न दिखे।", "safety": "अंडे को अंदर तक पूरा जमने तक पकाएं, कहीं भी कच्चा या बहता अंडा न रहे।", "smell": "भुने घी और पके प्याज़ की खुशबू आए।", "text": "पलटें ताकि अंडे वाली तरफ ऊपर आए, किनारों पर घी डालें और 2 से 3 मिनट सेंकें, एक बार और पलटें, जब तक दोनों तरफ सुनहरा न हो जाए और अंडा पूरा पक न जाए।", "touch": "पलटे से दबाने पर अंडे की परत सख्त लगे।"}, "hi-Latn": {"look": "Ande ki parat sunehri ho aur kahin geela ya behta hissa na dikhe.", "safety": "Ande ko andar tak poora jamne tak pakayein, kahin bhi kachcha ya behta anda na rahe.", "smell": "Bhune ghee aur pake pyaaz ki khushboo aaye.", "text": "Palatein taaki ande wali taraf upar aaye, kinaron par ghee daalein aur 2 se 3 minute senkein, ek baar aur palatein, jab tak dono taraf sunehra na ho jaaye aur anda poora pak na jaaye.", "touch": "Palte se dabane par ande ki parat sakht lage."}}'::jsonb, (select id from public.techniques where slug = 'shallow_fry'), 180, true, null, 'The egg layer is golden with no wet or runny patches. It smells of browned ghee and cooked onion. The egg layer feels firm when pressed with the spatula.', '{"en": "The egg layer is golden with no wet or runny patches. It smells of browned ghee and cooked onion. The egg layer feels firm when pressed with the spatula.", "heat": "medium", "look": "The egg layer is golden with no wet or runny patches.", "smell": "It smells of browned ghee and cooked onion.", "touch": "The egg layer feels firm when pressed with the spatula."}'::jsonb, null, 'Cook until the egg is fully set all the way through, with no runny egg left.'),
  ((select id from public.recipes where household_id is null and slug = 'egg-paratha'), 7, 'Repeat with the remaining parathas and egg mixture, and serve hot with ketchup if you like.', '{"en": "Repeat with the remaining parathas and egg mixture, and serve hot with ketchup if you like.", "hi": {"text": "बाकी पराठे और अंडे का मिश्रण इसी तरह बनाएं और चाहें तो केचप के साथ गरमागरम परोसें।"}, "hi-Latn": {"text": "Baaki parathe aur ande ka mixture isi tarah banayein aur chahein to ketchup ke saath garmagaram parosein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
