-- Recipe: gujarati-dal (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('gujarati-dal', 'Gujarati Dal', '{"en": "Gujarati Dal", "hi": "गुजराती दाल", "hi-Latn": "Gujarati Dal"}'::jsonb, 'Thin, smooth toor dal that is sweet, sour and gently spiced, with jaggery, kokum and a ghee tadka of mustard, cloves and curry leaves. Everyday Gujarati comfort with hot rice.', '{"hi": "पतली, मुलायम तूर दाल जो हल्की मीठी, खट्टी और कम तीखी होती है। इसमें गुड़, कोकम और राई, लौंग व करी पत्ते का घी वाला तड़का पड़ता है। गरम चावल के साथ रोज़ का गुजराती आराम।", "hi-Latn": "Patli, smooth toor dal jo halki meethi, khatti aur kam teekhi hoti hai. Isme gud, kokum aur rai, laung aur kadi patte ka ghee wala tadka padta hai. Garam chawal ke saath roz ka Gujarati aaram."}'::jsonb, 'gujarat', 'main', 'veg', 4, 25, 35, 2, 2, array['pressure_cooker', 'kadai', 'gas_stove']::text[], array['comforting']::text[], '{"acid": 0.6, "crunch": 0.1, "heat": 0.2, "rich": 0.4, "starch": 0.4, "sweet": 0.6}'::jsonb, array['dal']::text[], 'curated', 'in_review', false)
