insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'gujarati-dal'), 1, 'Rinse the toor dal and peanuts 3 times and soak them in water for 20 minutes.', '{"en": "Rinse the toor dal and peanuts 3 times and soak them in water for 20 minutes.", "hi": {"look": "धोने के बाद पानी लगभग साफ़ दिखता है।", "text": "तूर दाल और मूंगफली को 3 बार धोकर 20 मिनट पानी में भिगो दो।"}, "hi-Latn": {"look": "Dhone ke baad paani lagbhag saaf dikhta hai.", "text": "Toor dal aur moongphali ko 3 baar dhokar 20 minute paani mein bhigo do."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 1200, true, null, 'The water runs almost clear after rinsing.', '{"en": "The water runs almost clear after rinsing.", "look": "The water runs almost clear after rinsing."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'gujarati-dal'), 2, 'Drain, put dal and peanuts in the pressure cooker with 450 ml water and the turmeric, and cook for 4 whistles on medium heat.', '{"en": "Drain, put dal and peanuts in the pressure cooker with 450 ml water and the turmeric, and cook for 4 whistles on medium heat.", "hi": {"safety": "कुकर तभी खोलो जब प्रेशर अपने आप निकल जाए।", "text": "पानी निकालकर दाल और मूंगफली को 450 ml पानी और हल्दी के साथ प्रेशर कुकर में डालो और मध्यम आँच पर 4 सीटी आने दो।"}, "hi-Latn": {"safety": "Cooker tabhi kholo jab pressure apne aap nikal jaye.", "text": "Paani nikaal kar dal aur moongphali ko 450 ml paani aur haldi ke saath pressure cooker mein daalo aur medium aanch par 4 seeti aane do."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 900, true, 4, null, '{"heat": "medium"}'::jsonb, null, 'Open the cooker only after the pressure drops on its own.'),
  ((select id from public.recipes where household_id is null and slug = 'gujarati-dal'), 3, 'Whisk the cooked dal until completely smooth, then stir in 400 ml water to make it thin.', '{"en": "Whisk the cooked dal until completely smooth, then stir in 400 ml water to make it thin.", "hi": {"look": "दाल में कोई साबुत दाना नहीं रहता और यह पतले सूप जैसी बहती है।", "text": "पकी दाल को मथनी से अच्छी तरह मथकर बिल्कुल चिकना करो, फिर 400 ml पानी मिलाकर पतला करो।"}, "hi-Latn": {"look": "Dal mein koi saabut daana nahi rehta aur yeh patle soup jaisi behti hai.", "text": "Paki dal ko mathni se achhi tarah math kar bilkul smooth karo, phir 400 ml paani milakar patla karo."}}'::jsonb, null, null, false, null, 'The dal is smooth with no whole grains, and pourable like thin soup.', '{"en": "The dal is smooth with no whole grains, and pourable like thin soup.", "look": "The dal is smooth with no whole grains, and pourable like thin soup."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'gujarati-dal'), 4, 'Add chopped tomato, grated ginger, slit green chillies, jaggery, kokum, red chilli powder and salt, and simmer for 10 minutes on medium-low heat.', '{"en": "Add chopped tomato, grated ginger, slit green chillies, jaggery, kokum, red chilli powder and salt, and simmer for 10 minutes on medium-low heat.", "hi": {"look": "गुड़ घुल जाता है और टमाटर नरम हो जाता है।", "text": "कटा टमाटर, कसा अदरक, चीरी हरी मिर्च, गुड़, कोकम, लाल मिर्च पाउडर और नमक डालकर मध्यम-धीमी आँच पर 10 मिनट उबालो।"}, "hi-Latn": {"look": "Gud ghul jaata hai aur tamatar naram ho jaata hai.", "text": "Kata tamatar, kasa adrak, cheeri hari mirch, gud, kokum, laal mirch powder aur namak daal kar medium-dheemi aanch par 10 minute ubaalo."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 600, true, null, 'The jaggery melts and the tomato turns soft.', '{"en": "The jaggery melts and the tomato turns soft.", "heat": "medium", "look": "The jaggery melts and the tomato turns soft."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'gujarati-dal'), 5, 'Heat ghee in a small kadai, add mustard seeds, then cumin, fenugreek seeds, cloves, cinnamon, dry red chillies, curry leaves and asafoetida.', '{"en": "Heat ghee in a small kadai, add mustard seeds, then cumin, fenugreek seeds, cloves, cinnamon, dry red chillies, curry leaves and asafoetida.", "hi": {"safety": "गरम घी में करी पत्ता छिटकता है, थोड़ा पीछे खड़े रहो।", "smell": "लौंग और करी पत्ते की तेज़, भुनी खुशबू आती है।", "sound": "राई चटकती और फूटती है।", "text": "छोटी कड़ाही में घी गरम करो, राई डालो, फिर जीरा, मेथी दाना, लौंग, दालचीनी, सूखी लाल मिर्च, करी पत्ता और हींग डालो।"}, "hi-Latn": {"safety": "Garam ghee mein kadi patta chhitakta hai, thoda peeche khade raho.", "smell": "Laung aur kadi patte ki tez, bhuni khushboo aati hai.", "sound": "Rai chatakti aur phoot-ti hai.", "text": "Chhoti kadai mein ghee garam karo, rai daalo, phir jeera, methi dana, laung, dalchini, sookhi laal mirch, kadi patta aur hing daalo."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 120, false, null, 'The mustard seeds crackle and pop. The cloves and curry leaves smell strong and toasty.', '{"en": "The mustard seeds crackle and pop. The cloves and curry leaves smell strong and toasty.", "heat": "medium", "smell": "The cloves and curry leaves smell strong and toasty.", "sound": "The mustard seeds crackle and pop."}'::jsonb, null, 'Curry leaves splutter in hot ghee, so stand back.'),
  ((select id from public.recipes where household_id is null and slug = 'gujarati-dal'), 6, 'Pour the tadka into the dal and simmer for 5 more minutes on low heat.', '{"en": "Pour the tadka into the dal and simmer for 5 more minutes on low heat.", "hi": {"look": "ऊपर घी की हल्की परत चमकती है।", "sound": "तड़का पड़ते ही ज़ोर से छनछनाहट होती है।", "text": "तड़का दाल में डालो और धीमी आँच पर 5 मिनट और उबालो।"}, "hi-Latn": {"look": "Upar ghee ki halki parat chamakti hai.", "sound": "Tadka padte hi zor se chhan-chhan hoti hai.", "text": "Tadka dal mein daalo aur dheemi aanch par 5 minute aur ubaalo."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, true, null, 'A light layer of ghee shines on top. It sizzles loudly as the tadka hits the dal.', '{"en": "A light layer of ghee shines on top. It sizzles loudly as the tadka hits the dal.", "heat": "low", "look": "A light layer of ghee shines on top.", "sound": "It sizzles loudly as the tadka hits the dal."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'gujarati-dal'), 7, 'Switch off the heat, squeeze in lemon if you want more sourness, top with coriander leaves and serve hot with rice.', '{"en": "Switch off the heat, squeeze in lemon if you want more sourness, top with coriander leaves and serve hot with rice.", "hi": {"text": "गैस बंद करो, और खट्टापन चाहिए तो नींबू निचोड़ो, ऊपर हरा धनिया डालो और गरम-गरम चावल के साथ परोसो।"}, "hi-Latn": {"text": "Gas band karo, aur khattapan chahiye to nimbu nichodo, upar hara dhaniya daalo aur garam-garam chawal ke saath paroso."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'gujarati-dal') and step_no > 7;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'gujarati-dal');

-- Recipe: idli (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('idli', 'Idli', '{"en": "Idli", "hi": "इडली", "hi-Latn": "Idli"}'::jsonb, 'Soft, fluffy steamed cakes made from a fermented batter of idli rava and urad dal, a South Indian breakfast served with sambar and coconut chutney.', '{"hi": "इडली रवा और उड़द दाल के खमीर उठे घोल से बनी नरम, फूली हुई भाप में पकी इडली। यह दक्षिण भारत का नाश्ता है, जिसे सांभर और नारियल चटनी के साथ परोसा जाता है।", "hi-Latn": "Idli rava aur urad dal ke khameer uthe ghol se bani naram, phooli hui bhaap mein paki idli. Yeh South Indian nashta hai, jise sambar aur nariyal chutney ke saath parosa jata hai."}'::jsonb, 'south_indian', 'breakfast', 'vegan', 4, 30, 25, 3, 1, array['pressure_cooker', 'mixer_grinder', 'gas_stove']::text[], array['comforting', 'kids_friendly', 'light']::text[], '{"acid": 0.2, "crunch": 0, "heat": 0, "rich": 0.1, "starch": 0.7, "sweet": 0}'::jsonb, array['grain', 'dal']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
  description = excluded.description, descriptions = excluded.descriptions, cuisine_region = excluded.cuisine_region, course = excluded.course,
  diet = excluded.diet, base_servings = excluded.base_servings, prep_time_min = excluded.prep_time_min,
  cook_time_min = excluded.cook_time_min, difficulty = excluded.difficulty,
  spice_level = excluded.spice_level, equipment = excluded.equipment, tags = excluded.tags,
  flavor_profile = excluded.flavor_profile, food_groups = excluded.food_groups,
  review_status = excluded.review_status, is_published = excluded.is_published;

