insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'idli'), 1, 'Wash the urad dal with the fenugreek seeds and soak them in water for 5 hours. Soak the idli rava separately in water for the same time.', '{"en": "Wash the urad dal with the fenugreek seeds and soak them in water for 5 hours. Soak the idli rava separately in water for the same time.", "hi": {"look": "दाल फूली हुई और हल्की सफ़ेद दिखती है।", "text": "उड़द दाल और मेथी दाना धोकर 5 घंटे पानी में भिगो दो। इडली रवा को भी उतनी ही देर अलग पानी में भिगो दो।", "touch": "दाल का दाना उँगलियों में आसानी से टूट जाता है।"}, "hi-Latn": {"look": "Dal phooli hui aur halki safed dikhti hai.", "text": "Urad dal aur methi dana dhokar 5 ghante paani mein bhigo do. Idli rava ko bhi utni hi der alag paani mein bhigo do.", "touch": "Dal ka daana ungliyon mein aasani se toot jata hai."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 18000, true, null, 'The dal looks plump and pale. A dal grain breaks easily between your fingers.', '{"en": "The dal looks plump and pale. A dal grain breaks easily between your fingers.", "look": "The dal looks plump and pale.", "touch": "A dal grain breaks easily between your fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'idli'), 2, 'Drain the dal and grind it in the mixer with a little cold water, adding it slowly, until you get a smooth, fluffy batter.', '{"en": "Drain the dal and grind it in the mixer with a little cold water, adding it slowly, until you get a smooth, fluffy batter.", "hi": {"look": "घोल सफ़ेद, चिकना और हवादार दिखता है।", "text": "दाल का पानी निकालो और मिक्सी में थोड़ा-थोड़ा ठंडा पानी डालते हुए चिकना, फूला हुआ घोल पीस लो।", "touch": "घोल हल्का और फूला हुआ लगता है, दरदरा नहीं।"}, "hi-Latn": {"look": "Ghol safed, chikna aur hawadar dikhta hai.", "text": "Dal ka paani nikalo aur mixie mein thoda-thoda thanda paani daalte hue chikna, phoola hua ghol pees lo.", "touch": "Ghol halka aur phoola hua lagta hai, dardara nahi."}}'::jsonb, (select id from public.techniques where slug = 'batter'), 600, true, null, 'The batter is white, smooth and airy. The batter feels light and fluffy, not gritty.', '{"en": "The batter is white, smooth and airy. The batter feels light and fluffy, not gritty.", "look": "The batter is white, smooth and airy.", "touch": "The batter feels light and fluffy, not gritty."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'idli'), 3, 'Squeeze the water out of the idli rava with your hands and mix it into the dal batter with the salt. Cover and keep it in a warm place for 8 to 12 hours to ferment.', '{"en": "Squeeze the water out of the idli rava with your hands and mix it into the dal batter with the salt. Cover and keep it in a warm place for 8 to 12 hours to ferment.", "hi": {"look": "घोल लगभग दोगुना फूल जाता है और उसमें छोटे बुलबुले दिखते हैं।", "smell": "हल्की खट्टी अच्छी खुशबू आती है।", "text": "इडली रवा का पानी हाथ से निचोड़ो और उसे नमक के साथ दाल के घोल में मिला दो। ढककर 8 से 12 घंटे खमीर उठने के लिए गरम जगह पर रख दो।"}, "hi-Latn": {"look": "Ghol lagbhag dugna phool jata hai aur usmein chhote bulbule dikhte hain.", "smell": "Halki khatti achhi khushboo aati hai.", "text": "Idli rava ka paani haath se nichodo aur use namak ke saath dal ke ghol mein mila do. Dhakkar 8 se 12 ghante khameer uthne ke liye garam jagah par rakh do."}}'::jsonb, (select id from public.techniques where slug = 'batter'), 36000, true, null, 'The batter rises to about double and has small bubbles. It smells pleasantly sour.', '{"en": "The batter rises to about double and has small bubbles. It smells pleasantly sour.", "look": "The batter rises to about double and has small bubbles.", "smell": "It smells pleasantly sour."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'idli'), 4, 'Grease the idli moulds with oil and gently fill each cup about three-quarters full without stirring the batter too much.', '{"en": "Grease the idli moulds with oil and gently fill each cup about three-quarters full without stirring the batter too much.", "hi": {"text": "इडली के साँचों पर तेल लगाओ और घोल को ज़्यादा चलाए बिना हर खाने को धीरे से तीन-चौथाई भर दो।"}, "hi-Latn": {"text": "Idli ke saanchon par tel lagao aur ghol ko zyada chalaye bina har khaane ko dheere se teen-chauthai bhar do."}}'::jsonb, (select id from public.techniques where slug = 'shape'), 300, true, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'idli'), 5, 'Pour 2 cups of water into the pressure cooker, place the stand inside and close the lid without the whistle. Steam on medium heat for 12 minutes.', '{"en": "Pour 2 cups of water into the pressure cooker, place the stand inside and close the lid without the whistle. Steam on medium heat for 12 minutes.", "hi": {"look": "ढक्कन के छेद से लगातार भाप निकलती दिखती है।", "safety": "सीटी मत लगाओ, ताकि भाप आराम से निकलती रहे।", "text": "प्रेशर कुकर में 2 कप पानी डालो, स्टैंड अंदर रखो और सीटी लगाए बिना ढक्कन बंद करो। मध्यम आँच पर 12 मिनट भाप में पकाओ।"}, "hi-Latn": {"look": "Dhakkan ke chhed se lagatar bhaap nikalti dikhti hai.", "safety": "Seeti mat lagao, taaki bhaap aaram se nikalti rahe.", "text": "Pressure cooker mein 2 cup paani daalo, stand andar rakho aur seeti lagaye bina dhakkan band karo. Medium aanch par 12 minute bhaap mein pakao."}}'::jsonb, (select id from public.techniques where slug = 'steam'), 720, true, null, 'Steady steam comes out of the vent.', '{"en": "Steady steam comes out of the vent.", "heat": "medium", "look": "Steady steam comes out of the vent."}'::jsonb, null, 'Keep the whistle off so the steam can escape freely.'),
  ((select id from public.recipes where household_id is null and slug = 'idli'), 6, 'Turn off the heat and open the cooker only after the pressure has dropped by itself, about 5 minutes.', '{"en": "Turn off the heat and open the cooker only after the pressure has dropped by itself, about 5 minutes.", "hi": {"look": "छेद से भाप निकलना बंद हो जाता है।", "safety": "ढक्कन कभी ज़बरदस्ती मत खोलो। प्रेशर अपने आप उतरने तक रुको।", "text": "आँच बंद करो और प्रेशर अपने आप उतरने के बाद ही कुकर खोलो, लगभग 5 मिनट में।"}, "hi-Latn": {"look": "Chhed se bhaap nikalna band ho jata hai.", "safety": "Dhakkan kabhi zabardasti mat kholo. Pressure apne aap utarne tak ruko.", "text": "Aanch band karo aur pressure apne aap utarne ke baad hi cooker kholo, lagbhag 5 minute mein."}}'::jsonb, null, 300, true, null, 'Steam has stopped coming out of the vent.', '{"en": "Steam has stopped coming out of the vent.", "look": "Steam has stopped coming out of the vent."}'::jsonb, null, 'Never force the lid open; wait until the pressure has dropped by itself.'),
  ((select id from public.recipes where household_id is null and slug = 'idli'), 7, 'Let the moulds rest for 2 minutes, then scoop the idlis out with a wet spoon and serve hot.', '{"en": "Let the moulds rest for 2 minutes, then scoop the idlis out with a wet spoon and serve hot.", "hi": {"text": "साँचों को 2 मिनट रहने दो, फिर गीले चम्मच से इडली निकालो और गरम परोसो।", "touch": "पकी इडली दबाने पर वापस उठ जाती है और उँगली पर नहीं चिपकती।"}, "hi-Latn": {"text": "Saanchon ko 2 minute rehne do, phir geele chammach se idli nikalo aur garam paroso.", "touch": "Paki idli dabane par wapas uth jati hai aur ungli par nahi chipakti."}}'::jsonb, null, 120, false, null, 'A cooked idli springs back when pressed and does not stick to your finger.', '{"en": "A cooked idli springs back when pressed and does not stick to your finger.", "touch": "A cooked idli springs back when pressed and does not stick to your finger."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
