  ((select id from public.recipes where household_id is null and slug = 'jeera-rice'), (select id from public.ingredients where canonical_name = 'basmati rice'), 'basmati rice', 125, 'g', '1 katori chaawal', false, null, 'starch', jsonb_build_array(jsonb_build_object('ingredient_id', (select id from public.ingredients where canonical_name = 'rice'), 'ingredient', 'rice', 'ratio', 1, 'note', null)), 0),
