insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'kadai-paneer'), 1, 'Dry roast the coriander seeds and dry red chillies in the kadai on low heat, then coarsely crush them in the mixer.', '{"en": "Dry roast the coriander seeds and dry red chillies in the kadai on low heat, then coarsely crush them in the mixer.", "hi": {"smell": "धनिये से भुनी हुई खुशबू आने लगे।", "text": "कड़ाही में धीमी आँच पर साबुत धनिया और सूखी लाल मिर्च सूखा भूनें, फिर मिक्सर में दरदरा पीस लें।"}, "hi-Latn": {"smell": "Dhaniye se bhuni hui khushboo aane lage.", "text": "Kadai mein dheemi aanch par sabut dhaniya aur sookhi laal mirch sookha bhunein, phir mixer mein dardara pees lein."}}'::jsonb, (select id from public.techniques where slug = 'dry_roast'), 120, false, null, 'The coriander smells toasty and fragrant.', '{"en": "The coriander smells toasty and fragrant.", "heat": "low", "smell": "The coriander smells toasty and fragrant."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadai-paneer'), 2, 'Cut the paneer, capsicum and one onion into bite-size cubes, finely chop the other onion, slit the green chillies and blend the tomatoes to a puree.', '{"en": "Cut the paneer, capsicum and one onion into bite-size cubes, finely chop the other onion, slit the green chillies and blend the tomatoes to a puree.", "hi": {"text": "पनीर, शिमला मिर्च और एक प्याज़ के चौकोर टुकड़े काटें, दूसरा प्याज़ बारीक काटें, हरी मिर्च चीरें और टमाटर की प्यूरी बना लें।"}, "hi-Latn": {"text": "Paneer, shimla mirch aur ek pyaaz ke chaukor tukde kaatein, doosra pyaaz baarik kaatein, hari mirch cheerein aur tamatar ki puree bana lein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadai-paneer'), 3, 'Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat, then take them out.', '{"en": "Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat, then take them out.", "hi": {"look": "किनारे हल्के जले हुए दिखें पर टुकड़े अब भी कुरकुरे हों।", "text": "1 बड़ा चम्मच तेल गरम करके शिमला मिर्च और प्याज़ के टुकड़े तेज़ आँच पर उलटें-पलटें, फिर निकाल लें।"}, "hi-Latn": {"look": "Kinaare halke jale hue dikhein par tukde ab bhi kurkure hon.", "text": "1 bada chammach tel garam karke shimla mirch aur pyaaz ke tukde tez aanch par ulte-palte, phir nikaal lein."}}'::jsonb, null, 120, false, null, 'The edges are lightly charred but the pieces are still crunchy.', '{"en": "The edges are lightly charred but the pieces are still crunchy.", "heat": "high", "look": "The edges are lightly charred but the pieces are still crunchy."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadai-paneer'), 4, 'Add the remaining oil to the same kadai, add cumin seeds, then cook the chopped onion until golden on medium heat.', '{"en": "Add the remaining oil to the same kadai, add cumin seeds, then cook the chopped onion until golden on medium heat.", "hi": {"look": "प्याज़ सुनहरा भूरा हो जाए।", "safety": "पीछे हटकर रहें, जीरा डालते ही गरम तेल छिटक सकता है।", "sound": "तेल में पड़ते ही जीरा चटकने लगे।", "text": "उसी कड़ाही में बचा तेल डालें, जीरा डालें, फिर बारीक प्याज़ मध्यम आँच पर सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz sunehra bhoora ho jaaye.", "safety": "Peeche hatkar rahein, jeera daalte hi garam tel chhitak sakta hai.", "sound": "Tel mein padte hi jeera chatakne lage.", "text": "Usi kadai mein bacha tel daalein, jeera daalein, phir baarik pyaaz medium aanch par sunehra hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 360, true, null, 'The onion turns golden brown. The cumin crackles as soon as it hits the oil.', '{"en": "The onion turns golden brown. The cumin crackles as soon as it hits the oil.", "heat": "medium", "look": "The onion turns golden brown.", "sound": "The cumin crackles as soon as it hits the oil."}'::jsonb, null, 'Stand back, hot oil can splutter when the cumin goes in.'),
  ((select id from public.recipes where household_id is null and slug = 'kadai-paneer'), 5, 'Add the ginger garlic paste and green chillies and stir until the raw smell is gone.', '{"en": "Add the ginger garlic paste and green chillies and stir until the raw smell is gone.", "hi": {"smell": "लहसुन की कच्ची महक चली जाए।", "text": "अदरक लहसुन का पेस्ट और हरी मिर्च डालकर कच्ची महक जाने तक चलाएं।"}, "hi-Latn": {"smell": "Lehsun ki kachchi mehak chali jaaye.", "text": "Adrak lehsun ka paste aur hari mirch daalkar kachchi mehak jaane tak chalaayein."}}'::jsonb, null, 60, false, null, 'The raw garlic smell is gone.', '{"en": "The raw garlic smell is gone.", "heat": "medium", "smell": "The raw garlic smell is gone."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadai-paneer'), 6, 'Add the tomato puree, turmeric, kashmiri chilli powder, salt and half the crushed kadai masala, and cook the masala, stirring often.', '{"en": "Add the tomato puree, turmeric, kashmiri chilli powder, salt and half the crushed kadai masala, and cook the masala, stirring often.", "hi": {"look": "मसाला गाढ़ा हो जाए और किनारों से तेल अलग होने लगे।", "text": "टमाटर प्यूरी, हल्दी, कश्मीरी लाल मिर्च, नमक और आधा कुटा कड़ाही मसाला डालें, और बार-बार चलाते हुए मसाला भूनें।"}, "hi-Latn": {"look": "Masala gaadha ho jaaye aur kinaaron se tel alag hone lage.", "text": "Tamatar puree, haldi, kashmiri laal mirch, namak aur aadha kuta kadai masala daalein, aur baar-baar chalaate hue masala bhunein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 540, true, null, 'The masala thickens and oil separates at the sides.', '{"en": "The masala thickens and oil separates at the sides.", "heat": "medium", "look": "The masala thickens and oil separates at the sides."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadai-paneer'), 7, 'Add the paneer, the tossed capsicum and onion, the rest of the kadai masala, garam masala, crushed kasuri methi and cream if using, and toss gently on low heat.', '{"en": "Add the paneer, the tossed capsicum and onion, the rest of the kadai masala, garam masala, crushed kasuri methi and cream if using, and toss gently on low heat.", "hi": {"look": "हर टुकड़े पर मसाला लिपट जाए।", "text": "पनीर, भुनी शिमला मिर्च और प्याज़, बचा कड़ाही मसाला, गरम मसाला, मसली हुई कसूरी मेथी और चाहें तो मलाई डालें, और धीमी आँच पर हल्के हाथ से मिलाएं।", "touch": "पनीर नरम लगे और अंदर तक गरम हो जाए।"}, "hi-Latn": {"look": "Har tukde par masala lipat jaaye.", "text": "Paneer, bhuni shimla mirch aur pyaaz, bacha kadai masala, garam masala, masli hui kasuri methi aur chahein to malai daalein, aur dheemi aanch par halke haath se milaayein.", "touch": "Paneer naram lage aur andar tak garam ho jaaye."}}'::jsonb, null, 180, true, null, 'Every piece is coated in the masala. The paneer feels soft and warmed through.', '{"en": "Every piece is coated in the masala. The paneer feels soft and warmed through.", "heat": "low", "look": "Every piece is coated in the masala.", "touch": "The paneer feels soft and warmed through."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadai-paneer'), 8, 'Sprinkle chopped coriander leaves and serve hot with roti or paratha.', '{"en": "Sprinkle chopped coriander leaves and serve hot with roti or paratha.", "hi": {"text": "ऊपर से कटा हरा धनिया डालें और रोटी या पराठे के साथ गरम परोसें।"}, "hi-Latn": {"text": "Upar se kata hara dhaniya daalein aur roti ya paranthe ke saath garam parosein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
