insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('kadhi', 'Plain Kadhi', '{"en": "Plain Kadhi", "hi": "सादी कढ़ी", "hi-Latn": "Saadi Kadhi"}'::jsonb, 'A simple everyday kadhi: tangy buttermilk thickened with gram flour, simmered slowly, and finished with a ghee tadka of cumin, mustard seeds and curry leaves. Serve hot with plain rice.', '{"hi": "रोज़ की सादी कढ़ी: खट्टी छाछ को बेसन से गाढ़ा करके धीमी आँच पर पकाया जाता है, फिर ऊपर से जीरा, राई और करी पत्ते का घी वाला तड़का। गरम चावल के साथ परोसें।", "hi-Latn": "Roz ki saadi kadhi: khatti chhaach ko besan se gaadha karke dheemi aanch par pakaya jaata hai, phir upar se jeera, rai aur kari patte ka ghee wala tadka. Garam chawal ke saath parosein."}'::jsonb, 'north_indian', 'main', 'veg', 4, 10, 30, 2, 2, array['kadai', 'gas_stove']::text[], array['comforting']::text[], '{"acid": 0.7, "crunch": 0, "heat": 0.2, "rich": 0.4, "starch": 0.3, "sweet": 0.1}'::jsonb, array['dairy']::text[], 'curated', 'in_review', false)
