insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'kadhi'), 1, 'In the kadai, whisk the gram flour, turmeric and salt into the buttermilk until no lumps remain.', '{"en": "In the kadai, whisk the gram flour, turmeric and salt into the buttermilk until no lumps remain.", "hi": {"look": "मिश्रण एक जैसा हल्का पीला दिखे।", "text": "कढ़ाई में छाछ लें, उसमें बेसन, हल्दी और नमक डालकर तब तक फेंटें जब तक कोई गुठली न रहे।", "touch": "उंगलियों में चिकना लगे, कोई गुठली न हो।"}, "hi-Latn": {"look": "Mixture ek jaisa halka peela dikhe.", "text": "Kadai mein chhaach lein, usmein besan, haldi aur namak daalkar tab tak phentein jab tak koi gutthli na rahe.", "touch": "Ungliyon mein chikna lage, koi gutthli na ho."}}'::jsonb, (select id from public.techniques where slug = 'batter'), 180, true, null, 'The mixture is an even pale yellow. It feels smooth with no lumps between your fingers.', '{"en": "The mixture is an even pale yellow. It feels smooth with no lumps between your fingers.", "look": "The mixture is an even pale yellow.", "touch": "It feels smooth with no lumps between your fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi'), 2, 'Add the grated ginger and slit green chillies, put the kadai on medium heat and stir non-stop until it comes to a boil.', '{"en": "Add the grated ginger and slit green chillies, put the kadai on medium heat and stir non-stop until it comes to a boil.", "hi": {"look": "पूरी सतह पर बुलबुले उठने लगें।", "safety": "उबाल आने तक चलाते रहें, वरना कढ़ी फट जाएगी।", "text": "कद्दूकस किया अदरक और चिरी हुई हरी मिर्च डालें, कढ़ाई को मध्यम आँच पर रखें और उबाल आने तक लगातार चलाते रहें।"}, "hi-Latn": {"look": "Poori satah par bulbule uthne lagein.", "safety": "Ubaal aane tak chalate rahein, warna kadhi phat jayegi.", "text": "Kaddukas kiya adrak aur chiri hui hari mirch daalein, kadai ko medium aanch par rakhein aur ubaal aane tak lagataar chalate rahein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 480, true, null, 'Bubbles rise all over the surface.', '{"en": "Bubbles rise all over the surface.", "heat": "medium", "look": "Bubbles rise all over the surface."}'::jsonb, null, 'Keep stirring until it boils, or the kadhi will split.'),
  ((select id from public.recipes where household_id is null and slug = 'kadhi'), 3, 'Lower the heat and simmer, stirring now and then, until the kadhi thickens and the raw gram flour smell is gone.', '{"en": "Lower the heat and simmer, stirring now and then, until the kadhi thickens and the raw gram flour smell is gone.", "hi": {"look": "करछी के पीछे हल्की परत चढ़ने लगे।", "smell": "कच्चे बेसन की महक जाकर हल्की खट्टी खुशबू आए।", "sound": "धीरे-धीरे खदकने की आवाज़ आए।", "text": "आँच धीमी करें और बीच-बीच में चलाते हुए पकाएँ, जब तक कढ़ी गाढ़ी न हो जाए और कच्चे बेसन की महक न चली जाए।"}, "hi-Latn": {"look": "Karchhi ke peeche halki parat chadhne lage.", "smell": "Kachche besan ki mehak jaakar halki khatti khushboo aaye.", "sound": "Dheere-dheere khadakne ki aawaaz aaye.", "text": "Aanch dheemi karein aur beech-beech mein chalate hue pakayein, jab tak kadhi gaadhi na ho jaye aur kachche besan ki mehak na chali jaye."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 900, true, null, 'It lightly coats the back of the ladle. It bubbles gently. The raw besan smell turns mellow and tangy.', '{"en": "It lightly coats the back of the ladle. It bubbles gently. The raw besan smell turns mellow and tangy.", "heat": "low", "look": "It lightly coats the back of the ladle.", "smell": "The raw besan smell turns mellow and tangy.", "sound": "It bubbles gently."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi'), 4, 'For the tadka, heat ghee in a small pan, add mustard seeds, cumin and fenugreek seeds, then dry red chillies, curry leaves and asafoetida; switch off the heat and stir in red chilli powder.', '{"en": "For the tadka, heat ghee in a small pan, add mustard seeds, cumin and fenugreek seeds, then dry red chillies, curry leaves and asafoetida; switch off the heat and stir in red chilli powder.", "hi": {"look": "जीरा थोड़ा गहरा हो जाए।", "safety": "गरम घी में करी पत्ता चटकता है, थोड़ा दूर रहें।", "smell": "घी और हींग की सौंधी खुशबू आए।", "sound": "दाने चटकने लगें।", "text": "तड़के के लिए छोटे पैन में घी गरम करें, राई, जीरा और मेथी दाना डालें, फिर सूखी लाल मिर्च, करी पत्ता और हींग डालें; गैस बंद करके लाल मिर्च पाउडर मिलाएँ।"}, "hi-Latn": {"look": "Jeera thoda gehra ho jaye.", "safety": "Garam ghee mein kari patta chatakta hai, thoda door rahein.", "smell": "Ghee aur hing ki saundhi khushboo aaye.", "sound": "Daane chatakne lagein.", "text": "Tadke ke liye chhote pan mein ghee garam karein, rai, jeera aur methi dana daalein, phir sookhi laal mirch, kari patta aur hing daalein; gas band karke laal mirch powder milayein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 120, false, null, 'The cumin turns a shade darker. The seeds crackle and splutter. A nutty ghee and hing aroma rises.', '{"en": "The cumin turns a shade darker. The seeds crackle and splutter. A nutty ghee and hing aroma rises.", "heat": "medium", "look": "The cumin turns a shade darker.", "smell": "A nutty ghee and hing aroma rises.", "sound": "The seeds crackle and splutter."}'::jsonb, null, 'Curry leaves splutter in hot ghee, so stand back.'),
  ((select id from public.recipes where household_id is null and slug = 'kadhi'), 5, 'Pour the tadka over the kadhi, sprinkle coriander leaves and serve hot with rice.', '{"en": "Pour the tadka over the kadhi, sprinkle coriander leaves and serve hot with rice.", "hi": {"look": "पीली कढ़ी पर लाल घी तैरता दिखे।", "sound": "कढ़ी पर तड़का डालते ही छनछनाहट हो।", "text": "तड़का कढ़ी पर डालें, हरा धनिया छिड़कें और चावल के साथ गरम परोसें।"}, "hi-Latn": {"look": "Peeli kadhi par laal ghee tairta dikhe.", "sound": "Kadhi par tadka daalte hi chhanchhanahat ho.", "text": "Tadka kadhi par daalein, hara dhaniya chhidkein aur chawal ke saath garam parosein."}}'::jsonb, null, null, false, null, 'Red ghee floats on top of the yellow kadhi. The tadka sizzles as it hits the kadhi.', '{"en": "Red ghee floats on top of the yellow kadhi. The tadka sizzles as it hits the kadhi.", "look": "Red ghee floats on top of the yellow kadhi.", "sound": "The tadka sizzles as it hits the kadhi."}'::jsonb, null, null)
