insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('kala-chana', 'Kala Chana Masala', '{"en": "Kala Chana Masala", "hi": "काला चना मसाला", "hi-Latn": "Kala Chana Masala"}'::jsonb, 'Soaked black chickpeas pressure-cooked soft, then simmered in an onion-tomato masala until the gravy turns thick and earthy. A weekday dal-style curry for rice or roti.', '{"hi": "भीगे हुए काले चने कुकर में नरम पकाकर प्याज़-टमाटर के मसाले में तब तक पकाए जाते हैं जब तक ग्रेवी गाढ़ी और सोंधी न हो जाए। रोज़ के खाने के लिए, चावल या रोटी के साथ।", "hi-Latn": "Bhige hue kale chane cooker mein naram pakakar pyaaz-tamatar ke masale mein tab tak pakaye jaate hain jab tak gravy gaadhi aur sondhi na ho jaaye. Roz ke khaane ke liye, chawal ya roti ke saath."}'::jsonb, 'north_indian_punjabi_home_style_', 'main', 'veg', 4, 15, 45, 2, 3, array['pressure_cooker', 'kadai', 'gas_stove']::text[], array['comforting', 'high_protein']::text[], '{"acid": 0.4, "crunch": 0.1, "heat": 0.5, "rich": 0.5, "starch": 0.6, "sweet": 0}'::jsonb, array['dal', 'protein']::text[], 'curated', 'in_review', false)
