insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'kala-chana'), 1, 'Wash the black chickpeas and soak them in plenty of water for 8 hours or overnight, then drain and rinse.', '{"en": "Wash the black chickpeas and soak them in plenty of water for 8 hours or overnight, then drain and rinse.", "hi": {"look": "चने फूलकर लगभग दुगने हो जाते हैं।", "text": "काले चने धोकर भरपूर पानी में 8 घंटे या रात भर भिगो दो, फिर पानी निकालकर एक बार धो लो।"}, "hi-Latn": {"look": "Chane phoolkar lagbhag dugne ho jaate hain.", "text": "Kale chane dhokar bharpoor paani mein 8 ghante ya raat bhar bhigo do, phir paani nikaal kar ek baar dho lo."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 28800, true, null, 'The chana swell to almost double their size.', '{"en": "The chana swell to almost double their size.", "look": "The chana swell to almost double their size."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kala-chana'), 2, 'Pressure-cook the chana with 600 ml water, half the salt and the turmeric for 6 to 7 whistles on medium heat, then let the pressure drop on its own.', '{"en": "Pressure-cook the chana with 600 ml water, half the salt and the turmeric for 6 to 7 whistles on medium heat, then let the pressure drop on its own.", "hi": {"safety": "सारा प्रेशर निकल जाने के बाद ही कुकर खोलो।", "text": "चनों को 600 ml पानी, आधा नमक और हल्दी के साथ कुकर में मध्यम आँच पर 6 से 7 सीटी तक पकाओ, फिर प्रेशर अपने आप उतरने दो।", "touch": "एक चना दो उंगलियों के बीच आसानी से दब जाता है।"}, "hi-Latn": {"safety": "Saara pressure nikal jaane ke baad hi cooker kholo.", "text": "Chanon ko 600 ml paani, aadha namak aur haldi ke saath cooker mein medium aanch par 6 se 7 seeti tak pakao, phir pressure apne aap utarne do.", "touch": "Ek chana do ungliyon ke beech aasaani se dab jaata hai."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 1800, true, 7, 'A chana presses flat easily between two fingers.', '{"en": "A chana presses flat easily between two fingers.", "heat": "medium", "touch": "A chana presses flat easily between two fingers."}'::jsonb, null, 'Open the cooker only after all the pressure has released.'),
  ((select id from public.recipes where household_id is null and slug = 'kala-chana'), 3, 'Heat mustard oil in a kadai until it smokes lightly, add cumin seeds and bay leaf, then the onion, and fry until golden brown.', '{"en": "Heat mustard oil in a kadai until it smokes lightly, add cumin seeds and bay leaf, then the onion, and fry until golden brown.", "hi": {"look": "प्याज़ एक जैसा सुनहरा भूरा हो जाता है।", "sound": "तेल में डालते ही जीरा चटकने लगता है।", "text": "कढ़ाई में सरसों का तेल हल्का धुआँ आने तक गरम करो, जीरा और तेज पत्ता डालो, फिर प्याज़ डालकर सुनहरा भूरा होने तक भूनो।"}, "hi-Latn": {"look": "Pyaaz ek jaisa sunehra bhoora ho jaata hai.", "sound": "Tel mein daalte hi jeera chatakne lagta hai.", "text": "Kadai mein sarson ka tel halka dhuaan aane tak garam karo, jeera aur tej patta daalo, phir pyaaz daalkar sunehra bhoora hone tak bhuno."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 480, true, null, 'The onion turns an even golden brown. The cumin crackles as soon as it hits the oil.', '{"en": "The onion turns an even golden brown. The cumin crackles as soon as it hits the oil.", "heat": "medium", "look": "The onion turns an even golden brown.", "sound": "The cumin crackles as soon as it hits the oil."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kala-chana'), 4, 'Add ginger, garlic and green chilli for a minute, then the tomato, red chilli powder, coriander powder and remaining salt, and cook until the masala is soft and the oil separates.', '{"en": "Add ginger, garlic and green chilli for a minute, then the tomato, red chilli powder, coriander powder and remaining salt, and cook until the masala is soft and the oil separates.", "hi": {"look": "मसाले के किनारों पर तेल दिखने लगता है।", "smell": "लहसुन की कच्ची महक सोंधी हो जाती है।", "text": "अदरक, लहसुन और हरी मिर्च एक मिनट भूनो, फिर टमाटर, लाल मिर्च, धनिया पाउडर और बचा नमक डालकर मसाला नरम होने और तेल छोड़ने तक पकाओ।"}, "hi-Latn": {"look": "Masale ke kinaron par tel dikhne lagta hai.", "smell": "Lehsun ki kachchi mehak sondhi ho jaati hai.", "text": "Adrak, lehsun aur hari mirch ek minute bhuno, phir tamatar, laal mirch, dhaniya powder aur bacha namak daalkar masala naram hone aur tel chhodne tak pakao."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 480, true, null, 'Oil shows at the edges of the masala. The raw garlic smell turns sweet and roasted.', '{"en": "Oil shows at the edges of the masala. The raw garlic smell turns sweet and roasted.", "heat": "medium", "look": "Oil shows at the edges of the masala.", "smell": "The raw garlic smell turns sweet and roasted."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kala-chana'), 5, 'Tip in the cooked chana with their cooking water, mash a few against the side, and simmer until the gravy thickens.', '{"en": "Tip in the cooked chana with their cooking water, mash a few against the side, and simmer until the gravy thickens.", "hi": {"look": "ग्रेवी गाढ़ी और गहरी भूरी होकर चनों पर लिपट जाती है।", "text": "पके हुए चने उनके पानी के साथ डालो, कुछ चने किनारे पर दबाकर मसल दो, और ग्रेवी गाढ़ी होने तक धीमी आँच पर पकाओ।"}, "hi-Latn": {"look": "Gravy gaadhi aur gehri bhoori hokar chanon par lipat jaati hai.", "text": "Pake hue chane unke paani ke saath daalo, kuch chane kinaare par dabaakar masal do, aur gravy gaadhi hone tak dheemi aanch par pakao."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 600, true, null, 'The gravy turns thick and dark brown and coats the chana.', '{"en": "The gravy turns thick and dark brown and coats the chana.", "heat": "low", "look": "The gravy turns thick and dark brown and coats the chana."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kala-chana'), 6, 'Stir in garam masala and amchur, switch off the heat, scatter coriander leaves and serve hot with rice or roti.', '{"en": "Stir in garam masala and amchur, switch off the heat, scatter coriander leaves and serve hot with rice or roti.", "hi": {"smell": "गरम मसाले की गरम, खुशबूदार महक आती है।", "text": "गरम मसाला और अमचूर मिलाओ, गैस बंद करो, हरा धनिया डालकर चावल या रोटी के साथ गरमागरम परोसो।"}, "hi-Latn": {"smell": "Garam masale ki garam, khushboodar mehak aati hai.", "text": "Garam masala aur amchur milao, gas band karo, hara dhaniya daalkar chawal ya roti ke saath garmagaram paroso."}}'::jsonb, null, 60, false, null, 'The garam masala smells warm and fragrant.', '{"en": "The garam masala smells warm and fragrant.", "smell": "The garam masala smells warm and fragrant."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'kala-chana') and step_no > 6;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'kala-chana');

