insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('kanda-poha', 'Kanda Poha', '{"en": "Kanda Poha", "hi": "कांदा पोहा", "hi-Latn": "Kanda Poha"}'::jsonb, 'Flattened rice tossed with onion, mustard seeds, curry leaves and crunchy peanuts, finished with lemon and coriander.', '{"hi": "पोहा प्याज़, राई, करी पत्ता और कुरकुरी मूँगफली के साथ, ऊपर से नींबू और धनिया।", "hi-Latn": "Poha pyaaz, rai, curry patta aur kurkuri moongphali ke saath, upar se nimbu aur dhaniya."}'::jsonb, 'maharashtrian', 'breakfast', 'vegan', 4, 10, 12, 1, 2, array['kadai']::text[], array['quick', 'light', 'kids_friendly']::text[], '{"acid": 0.5, "crunch": 0.6, "heat": 0.3, "rich": 0.2, "starch": 0.8, "sweet": 0.2}'::jsonb, array['grain']::text[], 'curated', 'draft', false)
