-- Recipe: karela-sabzi (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('karela-sabzi', 'Karela Sabzi', '{"en": "Karela Sabzi", "hi": "करेले की सब्ज़ी", "hi-Latn": "Karela Sabzi"}'::jsonb, 'A dry North Indian everyday sabzi of thin bitter gourd slices fried with onions until crisp-edged. It is spiced with chilli, coriander and tangy amchur, with a little jaggery to round off the bitterness. Good with roti and dal.', '{"hi": "रोज़ की सूखी उत्तर भारतीय सब्ज़ी। करेले के पतले टुकड़े प्याज़ के साथ किनारे कुरकुरे होने तक भूने जाते हैं। इसमें मिर्च, धनिया और खट्टा अमचूर पड़ता है, और कड़वाहट संभालने के लिए थोड़ा गुड़। रोटी और दाल के साथ बढ़िया लगती है।", "hi-Latn": "Roz ki sookhi North Indian sabzi. Karele ke patle tukde pyaaz ke saath kinare kurkure hone tak bhune jaate hain. Isme mirch, dhaniya aur khatta amchur padta hai, aur kadwahat sambhalne ke liye thoda gud. Roti aur dal ke saath badhiya lagti hai."}'::jsonb, 'north_indian', 'side', 'veg', 4, 30, 25, 2, 3, array['kadai', 'gas_stove']::text[], array['tiffin']::text[], '{"acid": 0.3, "crunch": 0.3, "heat": 0.4, "rich": 0.3, "starch": 0.1, "sweet": 0.2}'::jsonb, array['sabzi']::text[], 'curated', 'in_review', false)
