insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'karela-sabzi'), 1, 'Lightly scrape the bitter gourds and cut them into thin rounds. Rub them with most of the salt and half the turmeric, then leave them for 20 minutes.', '{"en": "Lightly scrape the bitter gourds and cut them into thin rounds. Rub them with most of the salt and half the turmeric, then leave them for 20 minutes.", "hi": {"look": "टुकड़ों पर पानी की बूँदें दिखने लगती हैं।", "text": "करेले हल्के से छील लें और पतले गोल टुकड़ों में काट लें। इनमें ज़्यादातर नमक और आधी हल्दी मलें, फिर 20 मिनट छोड़ दें।"}, "hi-Latn": {"look": "Tukdon par paani ki boondein dikhne lagti hain.", "text": "Karele halke se chheel lein aur patle gol tukdon mein kaat lein. Inme zyaadatar namak aur aadhi haldi malein, phir 20 minute chhod dein."}}'::jsonb, null, 1200, true, null, 'Water beads appear on the slices.', '{"en": "Water beads appear on the slices.", "look": "Water beads appear on the slices."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'karela-sabzi'), 2, 'Squeeze the slices firmly by the handful and throw away the bitter water.', '{"en": "Squeeze the slices firmly by the handful and throw away the bitter water.", "hi": {"text": "मुट्ठी भर-भर के टुकड़ों को कस के निचोड़ें और कड़वा पानी फेंक दें।", "touch": "टुकड़े नरम और काफ़ी सूखे लगते हैं।"}, "hi-Latn": {"text": "Mutthi bhar-bhar ke tukdon ko kas ke nichodein aur kadwa paani phenk dein.", "touch": "Tukde naram aur kaafi sookhe lagte hain."}}'::jsonb, null, null, false, null, 'The slices feel limp and fairly dry.', '{"en": "The slices feel limp and fairly dry.", "touch": "The slices feel limp and fairly dry."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'karela-sabzi'), 3, 'Heat the oil in a kadai on medium heat. Add the cumin seeds and asafoetida.', '{"en": "Heat the oil in a kadai on medium heat. Add the cumin seeds and asafoetida.", "hi": {"sound": "जीरा चटकने लगता है।", "text": "कढ़ाई में मध्यम आँच पर तेल गरम करें। उसमें जीरा और हींग डालें।"}, "hi-Latn": {"sound": "Jeera chatakne lagta hai.", "text": "Kadai mein medium aanch par tel garam karein. Usme jeera aur hing daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin crackles.', '{"en": "The cumin crackles.", "heat": "medium", "sound": "The cumin crackles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'karela-sabzi'), 4, 'Add the squeezed bitter gourd and fry it uncovered, stirring now and then.', '{"en": "Add the squeezed bitter gourd and fry it uncovered, stirring now and then.", "hi": {"look": "टुकड़े सिकुड़ जाते हैं और किनारे भूरे हो जाते हैं।", "text": "निचोड़ा हुआ करेला डालें और बिना ढके भूनें, बीच-बीच में चलाते रहें।"}, "hi-Latn": {"look": "Tukde sikud jaate hain aur kinare bhoore ho jaate hain.", "text": "Nichoda hua karela daalein aur bina dhake bhunein, beech-beech mein chalate rahein."}}'::jsonb, (select id from public.techniques where slug = 'shallow_fry'), 720, true, null, 'The slices shrink and the edges turn brown.', '{"en": "The slices shrink and the edges turn brown.", "heat": "medium", "look": "The slices shrink and the edges turn brown."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'karela-sabzi'), 5, 'Add the sliced onions and cook them with the bitter gourd.', '{"en": "Add the sliced onions and cook them with the bitter gourd.", "hi": {"look": "प्याज़ नरम और सुनहरा हो जाता है।", "text": "कटे प्याज़ डालें और करेले के साथ पकाएँ।"}, "hi-Latn": {"look": "Pyaaz naram aur sunehra ho jaata hai.", "text": "Kate pyaaz daalein aur karele ke saath pakayein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 420, true, null, 'The onions turn soft and golden.', '{"en": "The onions turn soft and golden.", "heat": "medium", "look": "The onions turn soft and golden."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'karela-sabzi'), 6, 'Lower the heat. Add the rest of the turmeric, the red chilli powder, coriander powder and jaggery. Taste first, then add only a pinch of salt if needed, and stir-fry well.', '{"en": "Lower the heat. Add the rest of the turmeric, the red chilli powder, coriander powder and jaggery. Taste first, then add only a pinch of salt if needed, and stir-fry well.", "hi": {"smell": "मसालों की भुनी हुई खुशबू आने लगती है।", "text": "आँच धीमी करें। बची हुई हल्दी, लाल मिर्च पाउडर, धनिया पाउडर और गुड़ डालें। पहले चखें, ज़रूरत हो तो बस चुटकी भर नमक डालें, और अच्छे से भूनें।"}, "hi-Latn": {"smell": "Masalon ki bhuni hui khushboo aane lagti hai.", "text": "Aanch dheemi karein. Bachi hui haldi, laal mirch powder, dhaniya powder aur gud daalein. Pehle chakhein, zaroorat ho to bas chutki bhar namak daalein, aur achhe se bhunein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 240, true, null, 'The spices smell roasted.', '{"en": "The spices smell roasted.", "heat": "low", "smell": "The spices smell roasted."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'karela-sabzi'), 7, 'Sprinkle in the amchur, mix and cook for 2 minutes. Garnish with coriander leaves if you like, then serve.', '{"en": "Sprinkle in the amchur, mix and cook for 2 minutes. Garnish with coriander leaves if you like, then serve.", "hi": {"look": "सब्ज़ी सूखी और चमकदार दिखती है, और हर टुकड़े पर मसाला लिपटा होता है।", "text": "अमचूर छिड़कें, मिलाएँ और 2 मिनट पकाएँ। चाहें तो हरा धनिया डालें, फिर परोसें।"}, "hi-Latn": {"look": "Sabzi sookhi aur chamakdaar dikhti hai, aur har tukde par masala lipta hota hai.", "text": "Amchur chhidkein, milayein aur 2 minute pakayein. Chahein to hara dhaniya daalein, phir parosein."}}'::jsonb, null, 120, false, null, 'The sabzi looks dry and glossy, and the masala coats every slice.', '{"en": "The sabzi looks dry and glossy, and the masala coats every slice.", "heat": "low", "look": "The sabzi looks dry and glossy, and the masala coats every slice."}'::jsonb, null, null)
