insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'lauki-sabzi'), 1, 'Peel the lauki, taste a tiny raw piece from the cut end, then cut it into 1 cm cubes; chop the tomatoes, ginger and green chillies.', '{"en": "Peel the lauki, taste a tiny raw piece from the cut end, then cut it into 1 cm cubes; chop the tomatoes, ginger and green chillies.", "hi": {"safety": "अगर लौकी कड़वी लगे तो टुकड़ा थूक दें और पूरी लौकी फेंक दें; उसे न पकाएँ।", "text": "लौकी छीलें, कटे सिरे से एक छोटा कच्चा टुकड़ा चखें, फिर उसे 1 सेमी के टुकड़ों में काटें; टमाटर, अदरक और हरी मिर्च बारीक काट लें।"}, "hi-Latn": {"safety": "Agar lauki kadvi lage to tukda thook dein aur poori lauki phenk dein; use na pakayein.", "text": "Lauki chheelein, kate sire se ek chhota kachcha tukda chakhein, phir use 1 cm ke tukdon mein kaatein; tamatar, adrak aur hari mirch baareek kaat lein."}}'::jsonb, null, 480, true, null, null, '{}'::jsonb, null, 'If the lauki tastes bitter, spit it out and throw the whole lauki away; do not cook it.'),
  ((select id from public.recipes where household_id is null and slug = 'lauki-sabzi'), 2, 'Heat the oil in a kadai, then add cumin seeds and hing.', '{"en": "Heat the oil in a kadai, then add cumin seeds and hing.", "hi": {"look": "जीरे का रंग थोड़ा गहरा हो जाता है।", "smell": "जीरे की गरम, भुनी हुई खुशबू आती है।", "sound": "जीरा चटकने और तड़तड़ाने लगता है।", "text": "कड़ाही में तेल गरम करें, फिर जीरा और हींग डालें।"}, "hi-Latn": {"look": "Jeere ka rang thoda gehra ho jaata hai.", "smell": "Jeere ki garam, bhuni hui khushboo aati hai.", "sound": "Jeera chatakne aur tadtadane lagta hai.", "text": "Kadai mein tel garam karein, phir jeera aur hing daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin turns a shade darker. The cumin sizzles and crackles. A warm, nutty jeera smell rises.', '{"en": "The cumin turns a shade darker. The cumin sizzles and crackles. A warm, nutty jeera smell rises.", "heat": "medium", "look": "The cumin turns a shade darker.", "smell": "A warm, nutty jeera smell rises.", "sound": "The cumin sizzles and crackles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'lauki-sabzi'), 3, 'Add ginger and green chillies, stir for 30 seconds, then add tomatoes, turmeric, coriander powder, red chilli powder and salt and cook until mushy.', '{"en": "Add ginger and green chillies, stir for 30 seconds, then add tomatoes, turmeric, coriander powder, red chilli powder and salt and cook until mushy.", "hi": {"look": "टमाटर गल जाते हैं और किनारों पर तेल दिखने लगता है।", "smell": "कच्चे मसाले की महक पकी हुई खुशबू में बदल जाती है।", "text": "अदरक और हरी मिर्च डालकर 30 सेकंड चलाएँ, फिर टमाटर, हल्दी, धनिया पाउडर, लाल मिर्च और नमक डालकर टमाटर गलने तक पकाएँ।"}, "hi-Latn": {"look": "Tamatar gal jaate hain aur kinaron par tel dikhne lagta hai.", "smell": "Kachche masale ki mehak paki hui khushboo mein badal jaati hai.", "text": "Adrak aur hari mirch daalkar 30 second chalayein, phir tamatar, haldi, dhaniya powder, laal mirch aur namak daalkar tamatar galne tak pakayein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 300, true, null, 'The tomatoes break down and oil shows at the edges. The raw masala smell turns rich and cooked.', '{"en": "The tomatoes break down and oil shows at the edges. The raw masala smell turns rich and cooked.", "heat": "medium", "look": "The tomatoes break down and oil shows at the edges.", "smell": "The raw masala smell turns rich and cooked."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'lauki-sabzi'), 4, 'Add the lauki, mix well, cover and cook, stirring every 5 minutes; sprinkle 2 tablespoons of water only if it starts sticking.', '{"en": "Add the lauki, mix well, cover and cook, stirring every 5 minutes; sprinkle 2 tablespoons of water only if it starts sticking.", "hi": {"look": "लौकी पारदर्शी सी हो जाती है और अपना पानी छोड़ती है।", "text": "लौकी डालकर अच्छी तरह मिलाएँ, ढककर पकाएँ और हर 5 मिनट में चलाएँ; अगर चिपकने लगे तभी 2 बड़े चम्मच पानी छिड़कें।", "touch": "चम्मच से दबाने पर टुकड़ा आसानी से दब जाता है।"}, "hi-Latn": {"look": "Lauki transparent si ho jaati hai aur apna paani chhodti hai.", "text": "Lauki daalkar achchhi tarah milayein, dhakkar pakayein aur har 5 minute mein chalayein; agar chipakne lage tabhi 2 bade chammach paani chhidkein.", "touch": "Chammach se dabane par tukda aasaani se dab jaata hai."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 900, true, null, 'The lauki turns translucent and gives out its own water. A cube crushes easily when pressed with the spoon.', '{"en": "The lauki turns translucent and gives out its own water. A cube crushes easily when pressed with the spoon.", "heat": "low", "look": "The lauki turns translucent and gives out its own water.", "touch": "A cube crushes easily when pressed with the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'lauki-sabzi'), 5, 'Uncover and cook until the extra water dries up, then stir in the garam masala if using.', '{"en": "Uncover and cook until the extra water dries up, then stir in the garam masala if using.", "hi": {"look": "मसाला लौकी के टुकड़ों पर लिपट जाता है और थोड़ी सी ग्रेवी बचती है।", "text": "ढक्कन हटाकर अतिरिक्त पानी सूखने तक पकाएँ, फिर चाहें तो गरम मसाला मिलाएँ।"}, "hi-Latn": {"look": "Masala lauki ke tukdon par lipat jaata hai aur thodi si gravy bachti hai.", "text": "Dhakkan hatakar extra paani sookhne tak pakayein, phir chahein to garam masala milayein."}}'::jsonb, null, 180, true, null, 'The masala clings to the lauki pieces with just a little gravy left.', '{"en": "The masala clings to the lauki pieces with just a little gravy left.", "heat": "medium", "look": "The masala clings to the lauki pieces with just a little gravy left."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'lauki-sabzi'), 6, 'Turn off the heat, sprinkle chopped coriander leaves and serve hot with roti.', '{"en": "Turn off the heat, sprinkle chopped coriander leaves and serve hot with roti.", "hi": {"text": "आँच बंद करें, ऊपर से कटा हरा धनिया डालें और गरम रोटी के साथ परोसें।"}, "hi-Latn": {"text": "Aanch band karein, upar se kata hara dhaniya daalein aur garam roti ke saath parosein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'lauki-sabzi') and step_no > 6;

