-- Recipe: lobia (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('lobia', 'Lobia Masala', '{"en": "Lobia Masala", "hi": "लोबिया मसाला", "hi-Latn": "Lobia Masala"}'::jsonb, 'Soft black eyed peas simmered in a homestyle onion-tomato masala, a simple weekday dal to eat with roti or rice.', '{"hi": "प्याज़-टमाटर के घर जैसे मसाले में पकी नरम लोबिया, रोटी या चावल के साथ खाने वाली रोज़ की सादी दाल।", "hi-Latn": "Pyaaz-tamatar ke ghar jaise masale mein paki naram lobia, roti ya chawal ke saath khaane wali roz ki saadi dal."}'::jsonb, 'north_indian', 'main', 'veg', 4, 15, 40, 2, 2, array['pressure_cooker', 'kadai', 'gas_stove']::text[], array['comforting', 'high_protein']::text[], '{"acid": 0.4, "crunch": 0, "heat": 0.4, "rich": 0.5, "starch": 0.6, "sweet": 0}'::jsonb, array['dal']::text[], 'curated', 'in_review', false)
