insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'lobia'), 1, 'Rinse the lobia and soak it in plenty of water for 6 to 8 hours, then drain and rinse again.', '{"en": "Rinse the lobia and soak it in plenty of water for 6 to 8 hours, then drain and rinse again.", "hi": {"look": "दाने फूलकर लगभग दोगुने हो जाते हैं।", "text": "लोबिया धोकर भरपूर पानी में 6 से 8 घंटे भिगो दें, फिर पानी निकालकर दोबारा धो लें।"}, "hi-Latn": {"look": "Daane phoolkar lagbhag dugne ho jaate hain.", "text": "Lobia dhokar bharpoor paani mein 6 se 8 ghante bhigo dein, phir paani nikaalkar dobara dho lein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 21600, true, null, 'The beans swell to about double their size.', '{"en": "The beans swell to about double their size.", "look": "The beans swell to about double their size."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'lobia'), 2, 'Put the lobia in the pressure cooker with about 3 cups fresh water, half the salt and the turmeric, and cook on medium heat for 4 whistles; let the pressure drop on its own.', '{"en": "Put the lobia in the pressure cooker with about 3 cups fresh water, half the salt and the turmeric, and cook on medium heat for 4 whistles; let the pressure drop on its own.", "hi": {"text": "लोबिया को कुकर में लगभग 3 कप ताज़ा पानी, आधा नमक और हल्दी के साथ डालें और मध्यम आँच पर 4 सीटी लगाएँ; प्रेशर अपने आप उतरने दें।", "touch": "एक दाना उँगलियों में आसानी से मसल जाता है।"}, "hi-Latn": {"text": "Lobia ko cooker mein lagbhag 3 cup taaza paani, aadha namak aur haldi ke saath daalein aur medium aanch par 4 seeti lagayein; pressure apne aap utarne dein.", "touch": "Ek daana ungliyon mein aasani se masal jaata hai."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 900, true, 4, 'A bean mashes easily between your fingers.', '{"en": "A bean mashes easily between your fingers.", "heat": "medium", "touch": "A bean mashes easily between your fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'lobia'), 3, 'Heat oil in a kadai on medium heat and add cumin seeds and the bay leaf.', '{"en": "Heat oil in a kadai on medium heat and add cumin seeds and the bay leaf.", "hi": {"sound": "जीरा चटकने लगता है।", "text": "कड़ाही में मध्यम आँच पर तेल गरम करें और जीरा व तेज पत्ता डालें।"}, "hi-Latn": {"sound": "Jeera chatakne lagta hai.", "text": "Kadai mein medium aanch par tel garam karein aur jeera va tej patta daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin crackles.', '{"en": "The cumin crackles.", "heat": "medium", "sound": "The cumin crackles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'lobia'), 4, 'Add the chopped onion and fry, stirring often, until golden.', '{"en": "Add the chopped onion and fry, stirring often, until golden.", "hi": {"look": "प्याज़ किनारों से सुनहरा भूरा हो जाता है।", "text": "कटा प्याज़ डालें और बार-बार चलाते हुए सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz kinaaron se sunehra bhoora ho jaata hai.", "text": "Kata pyaaz daalein aur baar-baar chalaate hue sunehra hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 480, true, null, 'The onion turns golden brown at the edges.', '{"en": "The onion turns golden brown at the edges.", "heat": "medium", "look": "The onion turns golden brown at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'lobia'), 5, 'Add ginger garlic paste and slit green chilli and stir for a minute.', '{"en": "Add ginger garlic paste and slit green chilli and stir for a minute.", "hi": {"smell": "लहसुन की कच्ची महक चली जाती है।", "text": "अदरक लहसुन पेस्ट और चीरी हुई हरी मिर्च डालकर एक मिनट चलाएँ।"}, "hi-Latn": {"smell": "Lahsun ki kachchi mehak chali jaati hai.", "text": "Adrak lahsun paste aur cheeri hui hari mirch daalkar ek minute chalaayein."}}'::jsonb, null, 60, false, null, 'The raw garlic smell goes away.', '{"en": "The raw garlic smell goes away.", "heat": "medium", "smell": "The raw garlic smell goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'lobia'), 6, 'Add tomato, red chilli powder, coriander powder and the rest of the salt, and cook until the masala is soft.', '{"en": "Add tomato, red chilli powder, coriander powder and the rest of the salt, and cook until the masala is soft.", "hi": {"look": "मसाले के किनारों पर तेल दिखने लगता है।", "text": "टमाटर, लाल मिर्च, धनिया पाउडर और बाकी नमक डालें और मसाला नरम होने तक भूनें।"}, "hi-Latn": {"look": "Masale ke kinaaron par tel dikhne lagta hai.", "text": "Tamatar, laal mirch, dhaniya powder aur baaki namak daalein aur masala naram hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 420, true, null, 'Oil shows at the sides of the masala.', '{"en": "Oil shows at the sides of the masala.", "heat": "medium", "look": "Oil shows at the sides of the masala."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'lobia'), 7, 'Add the cooked lobia with its cooking water, mash a few beans with the ladle and simmer on low heat until thick.', '{"en": "Add the cooked lobia with its cooking water, mash a few beans with the ladle and simmer on low heat until thick.", "hi": {"look": "ग्रेवी गाढ़ी होकर दानों पर लिपटने लगती है।", "text": "पकी लोबिया उसके पानी समेत डालें, कलछी से कुछ दाने मसल दें और धीमी आँच पर गाढ़ा होने तक पकाएँ।"}, "hi-Latn": {"look": "Gravy gaadhi hokar daanon par lipatne lagti hai.", "text": "Paki lobia uske paani samet daalein, kalchhi se kuch daane masal dein aur dheemi aanch par gaadha hone tak pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 600, true, null, 'The gravy turns thick and coats the beans.', '{"en": "The gravy turns thick and coats the beans.", "heat": "low", "look": "The gravy turns thick and coats the beans."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'lobia'), 8, 'Stir in garam masala, switch off the heat, top with coriander leaves and serve hot.', '{"en": "Stir in garam masala, switch off the heat, top with coriander leaves and serve hot.", "hi": {"text": "गरम मसाला मिलाएँ, आँच बंद करें, हरा धनिया डालें और गरमागरम परोसें।"}, "hi-Latn": {"text": "Garam masala milaayein, aanch band karein, hara dhaniya daalein aur garmagaram parosein."}}'::jsonb, null, 60, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'lobia') and step_no > 8;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'lobia');

-- Recipe: malai-kofta (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('malai-kofta', 'Malai Kofta', '{"en": "Malai Kofta", "hi": "मलाई कोफ्ता", "hi-Latn": "Malai Kofta"}'::jsonb, 'Soft fried paneer and potato balls served in a smooth, mildly sweet onion, tomato and cashew gravy finished with cream. A North Indian favourite for a special lunch or dinner with roti, naan or jeera rice.', '{"hi": "पनीर और आलू के नरम तले हुए कोफ्ते, प्याज़, टमाटर और काजू की चिकनी, हल्की मीठी ग्रेवी में, ऊपर से मलाई डालकर। रोटी, नान या जीरा राइस के साथ खास दिन के खाने के लिए उत्तर भारत की पसंदीदा सब्ज़ी।", "hi-Latn": "Paneer aur aloo ke naram tale hue kofte, pyaaz, tamatar aur kaju ki smooth, halki meethi gravy mein, upar se malai daal kar. Roti, naan ya jeera rice ke saath khaas din ke khaane ke liye North Indian favourite sabzi."}'::jsonb, 'north_indian_mughlai_', 'main', 'veg', 4, 25, 45, 3, 2, array['pressure_cooker', 'kadai', 'mixer_grinder', 'gas_stove']::text[], array['festive', 'comforting', 'kids_friendly']::text[], '{"acid": 0.3, "crunch": 0.1, "heat": 0.2, "rich": 0.8, "starch": 0.4, "sweet": 0.3}'::jsonb, array['dairy', 'sabzi']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
  description = excluded.description, descriptions = excluded.descriptions, cuisine_region = excluded.cuisine_region, course = excluded.course,
  diet = excluded.diet, base_servings = excluded.base_servings, prep_time_min = excluded.prep_time_min,
  cook_time_min = excluded.cook_time_min, difficulty = excluded.difficulty,
  spice_level = excluded.spice_level, equipment = excluded.equipment, tags = excluded.tags,
  flavor_profile = excluded.flavor_profile, food_groups = excluded.food_groups,
  review_status = excluded.review_status, is_published = excluded.is_published;

