insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'malai-kofta'), 1, 'Pressure-cook the potatoes with a little water, then peel and mash them while warm.', '{"en": "Pressure-cook the potatoes with a little water, then peel and mash them while warm.", "hi": {"safety": "कुकर का प्रेशर अपने आप उतरने के बाद ही खोलें।", "text": "आलू को थोड़े पानी के साथ प्रेशर कुकर में पकाता हूँ, फिर छीलकर गरम-गरम मसल लेता हूँ।", "touch": "चाकू आलू में आसानी से घुस जाए।"}, "hi-Latn": {"safety": "Cooker ka pressure apne aap utarne ke baad hi kholein.", "text": "Aloo ko thode paani ke saath pressure cooker mein pakata hoon, phir chheel kar garam-garam masal leta hoon.", "touch": "Chaaku aloo mein aasaani se ghus jaaye."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), null, false, 3, 'A knife goes through the potato easily.', '{"en": "A knife goes through the potato easily.", "heat": "medium", "touch": "A knife goes through the potato easily."}'::jsonb, null, 'Open the cooker only after the pressure drops on its own.'),
  ((select id from public.recipes where household_id is null and slug = 'malai-kofta'), 2, 'Grate the paneer into the mashed potato, add cornflour, garam masala and a little salt, knead to a smooth dough and shape 12 round balls.', '{"en": "Grate the paneer into the mashed potato, add cornflour, garam masala and a little salt, knead to a smooth dough and shape 12 round balls.", "hi": {"text": "मसले आलू में पनीर कद्दूकस करता हूँ, कॉर्नफ्लोर, गरम मसाला और थोड़ा नमक डालकर चिकना गूंथता हूँ और 12 गोल कोफ्ते बनाता हूँ।", "touch": "कोफ्ते चिकने लगें, ऊपर कोई दरार न हो।"}, "hi-Latn": {"text": "Masle aloo mein paneer grate karta hoon, cornflour, garam masala aur thoda namak daal kar smooth goondhta hoon aur 12 gol kofte banata hoon.", "touch": "Kofte smooth lagein, upar koi darar na ho."}}'::jsonb, (select id from public.techniques where slug = 'shape'), null, false, null, 'The balls feel smooth with no cracks on the surface.', '{"en": "The balls feel smooth with no cracks on the surface.", "touch": "The balls feel smooth with no cracks on the surface."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'malai-kofta'), 3, 'Heat oil in a kadai and deep-fry the koftas a few at a time, turning gently, until golden all over.', '{"en": "Heat oil in a kadai and deep-fry the koftas a few at a time, turning gently, until golden all over.", "hi": {"look": "कोफ्ते चारों ओर से एक जैसे सुनहरे भूरे हो जाएँ।", "safety": "पहले एक कोफ्ता तलकर देखें; टूटे तो थोड़ा और कॉर्नफ्लोर मिलाएँ। गरम तेल के छींटों से बचने के लिए कोफ्ते धीरे से डालें।", "text": "कड़ाही में तेल गरम करके थोड़े-थोड़े कोफ्ते डालता हूँ और धीरे-धीरे पलटते हुए सुनहरा होने तक तलता हूँ।"}, "hi-Latn": {"look": "Kofte chaaron taraf se ek jaise sunehre brown ho jaayein.", "safety": "Pehle ek kofta tal kar dekhein; toote to thoda aur cornflour milaayein. Garam tel ke chheenton se bachne ke liye kofte dheere se daalein.", "text": "Kadai mein tel garam karke thode-thode kofte daalta hoon aur dheere-dheere palatte hue sunehra hone tak talta hoon."}}'::jsonb, (select id from public.techniques where slug = 'deep_fry'), 300, true, null, 'Koftas turn evenly golden brown.', '{"en": "Koftas turn evenly golden brown.", "heat": "medium", "look": "Koftas turn evenly golden brown."}'::jsonb, null, 'Fry one kofta first to test; if it breaks, add a little more cornflour. Slide them in gently to avoid hot oil splashes.'),
  ((select id from public.recipes where household_id is null and slug = 'malai-kofta'), 4, 'In another pan heat 1 tablespoon oil with the butter, add cumin and bay leaf, then add sliced onion and sauté until soft and light golden.', '{"en": "In another pan heat 1 tablespoon oil with the butter, add cumin and bay leaf, then add sliced onion and sauté until soft and light golden.", "hi": {"look": "प्याज़ नरम और हल्का सुनहरा हो जाए।", "sound": "जीरा डालते ही चटकने लगे।", "text": "दूसरे बर्तन में 1 बड़ा चम्मच तेल और मक्खन गरम करता हूँ, जीरा और तेज पत्ता डालता हूँ, फिर कटा प्याज़ डालकर नरम और हल्का सुनहरा होने तक भूनता हूँ।"}, "hi-Latn": {"look": "Pyaaz naram aur halka sunehra ho jaaye.", "sound": "Jeera daalte hi chatakne lage.", "text": "Doosre bartan mein 1 bada chammach tel aur makhan garam karta hoon, jeera aur tej patta daalta hoon, phir kata pyaaz daal kar naram aur halka sunehra hone tak bhoonta hoon."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 360, true, null, 'Onions turn soft and light golden. Cumin crackles as soon as it hits the fat.', '{"en": "Onions turn soft and light golden. Cumin crackles as soon as it hits the fat.", "heat": "medium", "look": "Onions turn soft and light golden.", "sound": "Cumin crackles as soon as it hits the fat."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'malai-kofta'), 5, 'Add ginger garlic paste, chopped tomato, cashews and green chilli, and cook until the tomatoes are completely mushy.', '{"en": "Add ginger garlic paste, chopped tomato, cashews and green chilli, and cook until the tomatoes are completely mushy.", "hi": {"look": "टमाटर पूरी तरह गल जाएँ और किनारों पर तेल दिखे।", "smell": "अदरक लहसुन की कच्ची महक चली जाए।", "text": "अदरक लहसुन पेस्ट, कटा टमाटर, काजू और हरी मिर्च डालकर टमाटर पूरी तरह गलने तक पकाता हूँ।"}, "hi-Latn": {"look": "Tamatar poori tarah gal jaayein aur kinaaron par tel dikhe.", "smell": "Adrak lahsun ki kachchi mehak chali jaaye.", "text": "Adrak lahsun paste, kata tamatar, kaju aur hari mirch daal kar tamatar poori tarah galne tak pakata hoon."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 480, true, null, 'Tomatoes break down fully and oil shows at the edges. The raw smell of ginger garlic goes away.', '{"en": "Tomatoes break down fully and oil shows at the edges. The raw smell of ginger garlic goes away.", "heat": "medium", "look": "Tomatoes break down fully and oil shows at the edges.", "smell": "The raw smell of ginger garlic goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'malai-kofta'), 6, 'Remove the bay leaf, let the mixture cool a little and grind it to a very smooth paste with a splash of water.', '{"en": "Remove the bay leaf, let the mixture cool a little and grind it to a very smooth paste with a splash of water.", "hi": {"look": "पेस्ट मुलायम हो, काजू के टुकड़े न दिखें।", "safety": "पीसने से पहले ठंडा करें; गरम मिश्रण से मिक्सर का ढक्कन खुल सकता है।", "text": "तेज पत्ता निकालकर मिश्रण थोड़ा ठंडा करता हूँ और थोड़ा पानी डालकर एकदम चिकना पीस लेता हूँ।"}, "hi-Latn": {"look": "Paste silky ho, kaju ke tukde na dikhein.", "safety": "Peesne se pehle thanda karein; garam mixture se mixer ka dhakkan khul sakta hai.", "text": "Tej patta nikaal kar mixture thoda thanda karta hoon aur thoda paani daal kar ekdum smooth pees leta hoon."}}'::jsonb, null, null, false, null, 'The paste is silky with no cashew bits.', '{"en": "The paste is silky with no cashew bits.", "look": "The paste is silky with no cashew bits."}'::jsonb, null, 'Let it cool before grinding; hot mixture can push the mixer lid open.'),
  ((select id from public.recipes where household_id is null and slug = 'malai-kofta'), 7, 'Pour the paste back into the pan, add turmeric, kashmiri chilli powder, coriander powder and salt, then add about a cup of water and simmer.', '{"en": "Pour the paste back into the pan, add turmeric, kashmiri chilli powder, coriander powder and salt, then add about a cup of water and simmer.", "hi": {"look": "ग्रेवी गाढ़ी होकर गहरे नारंगी रंग की हो जाए।", "safety": "आधा ढककर पकाएँ; गाढ़ी ग्रेवी छींटे मारती है।", "text": "पेस्ट वापस बर्तन में डालता हूँ, हल्दी, कश्मीरी मिर्च, धनिया पाउडर और नमक डालकर लगभग एक कप पानी मिलाता हूँ और धीमी आँच पर पकाता हूँ।"}, "hi-Latn": {"look": "Gravy gaadhi hokar gehre naarangi rang ki ho jaaye.", "safety": "Aadha dhak kar pakaayein; gaadhi gravy chheente maarti hai.", "text": "Paste wapas bartan mein daalta hoon, haldi, kashmiri mirch, dhaniya powder aur namak daal kar lagbhag ek cup paani milaata hoon aur dheemi aanch par pakata hoon."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 480, true, null, 'The gravy thickens and turns a deep orange.', '{"en": "The gravy thickens and turns a deep orange.", "heat": "low", "look": "The gravy thickens and turns a deep orange."}'::jsonb, null, 'Cover partly; thick gravy can splutter.'),
  ((select id from public.recipes where household_id is null and slug = 'malai-kofta'), 8, 'Stir in the cream, sugar and crushed kasuri methi and warm through without boiling hard.', '{"en": "Stir in the cream, sugar and crushed kasuri methi and warm through without boiling hard.", "hi": {"look": "ग्रेवी मलाईदार और हल्की नारंगी हो जाए।", "smell": "कसूरी मेथी की खुशबू आए।", "text": "मलाई, चीनी और मसली हुई कसूरी मेथी मिलाकर बिना तेज़ उबाले गरम करता हूँ।"}, "hi-Latn": {"look": "Gravy creamy aur halki naarangi ho jaaye.", "smell": "Kasuri methi ki khushboo aaye.", "text": "Malai, cheeni aur masli hui kasuri methi mila kar bina tez ubaale garam karta hoon."}}'::jsonb, null, 120, false, null, 'The gravy turns creamy and pale orange. Kasuri methi smells fragrant.', '{"en": "The gravy turns creamy and pale orange. Kasuri methi smells fragrant.", "heat": "low", "look": "The gravy turns creamy and pale orange.", "smell": "Kasuri methi smells fragrant."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'malai-kofta'), 9, 'Place the koftas in a serving bowl and pour the hot gravy over them just before eating, garnished with coriander.', '{"en": "Place the koftas in a serving bowl and pour the hot gravy over them just before eating, garnished with coriander.", "hi": {"text": "कोफ्ते परोसने के बर्तन में रखता हूँ और खाने से ठीक पहले ऊपर से गरम ग्रेवी डालकर हरा धनिया सजाता हूँ।"}, "hi-Latn": {"text": "Kofte serving bowl mein rakhta hoon aur khaane se theek pehle upar se garam gravy daal kar hara dhaniya sajaata hoon."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
