-- Recipe: masala-oats (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('masala-oats', 'Masala Oats', '{"en": "Masala Oats", "hi": "मसाला ओट्स", "hi-Latn": "Masala Oats"}'::jsonb, 'A quick, savoury breakfast of rolled oats cooked with onion, tomato, carrot and peas in a cumin-mustard tadka with everyday Indian spices, finished with coriander and a squeeze of lemon.', '{"hi": "झटपट बनने वाला नमकीन नाश्ता, जिसमें रोल्ड ओट्स को प्याज़, टमाटर, गाजर और मटर के साथ जीरा-राई के तड़के और रोज़ के मसालों में पकाया जाता है, ऊपर से हरा धनिया और नींबू।", "hi-Latn": "Jhatpat banne wala namkeen nashta, jisme rolled oats ko pyaaz, tamatar, gajar aur matar ke saath jeera-rai ke tadke aur roz ke masalon mein pakaya jata hai, upar se hara dhaniya aur nimbu."}'::jsonb, 'pan_indian', 'breakfast', 'vegan', 4, 10, 15, 1, 2, array['kadai', 'gas_stove']::text[], array['quick', 'one_pot', 'light', 'tiffin']::text[], '{"acid": 0.3, "crunch": 0.1, "heat": 0.3, "rich": 0.2, "starch": 0.6, "sweet": 0.1}'::jsonb, array['grain', 'sabzi']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
  description = excluded.description, descriptions = excluded.descriptions, cuisine_region = excluded.cuisine_region, course = excluded.course,
  diet = excluded.diet, base_servings = excluded.base_servings, prep_time_min = excluded.prep_time_min,
  cook_time_min = excluded.cook_time_min, difficulty = excluded.difficulty,
  spice_level = excluded.spice_level, equipment = excluded.equipment, tags = excluded.tags,
  flavor_profile = excluded.flavor_profile, food_groups = excluded.food_groups,
  review_status = excluded.review_status, is_published = excluded.is_published;

