insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'masala-oats'), 1, 'Finely chop the onion, tomato, green chilli and ginger, and dice the carrot small.', '{"en": "Finely chop the onion, tomato, green chilli and ginger, and dice the carrot small.", "hi": {"text": "प्याज़, टमाटर, हरी मिर्च और अदरक बारीक काट लो, और गाजर छोटे टुकड़ों में काट लो।"}, "hi-Latn": {"text": "Pyaaz, tamatar, hari mirch aur adrak bareek kaat lo, aur gajar chhote tukdon mein kaat lo."}}'::jsonb, null, 300, true, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masala-oats'), 2, 'Heat the oil in a kadai, add mustard seeds, cumin seeds and curry leaves.', '{"en": "Heat the oil in a kadai, add mustard seeds, cumin seeds and curry leaves.", "hi": {"safety": "कढ़ी पत्ता छिटकता है, चेहरा थोड़ा दूर रखो।", "sound": "राई चटकने लगे।", "text": "कढ़ाई में तेल गरम करो, राई, जीरा और कढ़ी पत्ता डालो।"}, "hi-Latn": {"safety": "Kadi patta chhitakta hai, chehra thoda door rakho.", "sound": "Rai chatakne lage.", "text": "Kadai mein tel garam karo, rai, jeera aur kadi patta daalo."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The mustard seeds crackle and pop.', '{"en": "The mustard seeds crackle and pop.", "heat": "medium", "sound": "The mustard seeds crackle and pop."}'::jsonb, null, 'Curry leaves splutter, so keep your face back.'),
  ((select id from public.recipes where household_id is null and slug = 'masala-oats'), 3, 'Add onion, green chilli and ginger and sauté until the onion turns soft and light pink.', '{"en": "Add onion, green chilli and ginger and sauté until the onion turns soft and light pink.", "hi": {"look": "प्याज़ नरम और पारदर्शी हो, किनारे हल्के गुलाबी।", "text": "प्याज़, हरी मिर्च और अदरक डालकर प्याज़ नरम और हल्का गुलाबी होने तक भूनो।"}, "hi-Latn": {"look": "Pyaaz naram aur transparent ho, kinare halke gulabi.", "text": "Pyaaz, hari mirch aur adrak daalkar pyaaz naram aur halka gulabi hone tak bhuno."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 180, true, null, 'Onion is soft and translucent with light pink edges.', '{"en": "Onion is soft and translucent with light pink edges.", "heat": "medium", "look": "Onion is soft and translucent with light pink edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masala-oats'), 4, 'Add carrot, peas, tomato, turmeric, red chilli powder and salt, and cook until the tomato turns mushy.', '{"en": "Add carrot, peas, tomato, turmeric, red chilli powder and salt, and cook until the tomato turns mushy.", "hi": {"look": "टमाटर गल जाए और किनारों पर तेल दिखे।", "text": "गाजर, मटर, टमाटर, हल्दी, लाल मिर्च और नमक डालो, और टमाटर गलने तक पकाओ।"}, "hi-Latn": {"look": "Tamatar gal jaaye aur kinaron par tel dikhe.", "text": "Gajar, matar, tamatar, haldi, laal mirch aur namak daalo, aur tamatar galne tak pakao."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 240, true, null, 'Tomato breaks down and oil shows at the edges.', '{"en": "Tomato breaks down and oil shows at the edges.", "heat": "medium", "look": "Tomato breaks down and oil shows at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masala-oats'), 5, 'Pour in about 3 cups of water and bring it to a boil.', '{"en": "Pour in about 3 cups of water and bring it to a boil.", "hi": {"look": "पानी पूरा खदबदाने लगे।", "text": "लगभग 3 कप पानी डालो और उबाल आने दो।"}, "hi-Latn": {"look": "Paani poora khadbadane lage.", "text": "Lagbhag 3 cup paani daalo aur ubaal aane do."}}'::jsonb, null, 180, true, null, 'Water is bubbling all over.', '{"en": "Water is bubbling all over.", "heat": "high", "look": "Water is bubbling all over."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masala-oats'), 6, 'Stir in the oats and garam masala and simmer, stirring often, until the oats are soft and the mix is thick but still loose.', '{"en": "Stir in the oats and garam masala and simmer, stirring often, until the oats are soft and the mix is thick but still loose.", "hi": {"look": "ओट्स फूल जाएं और मिश्रण ढीले दलिए जैसा दिखे।", "safety": "गरम ओट्स छिटकते हैं, लंबे चम्मच से चलाओ।", "text": "ओट्स और गरम मसाला डालकर चलाते रहो और धीमी आंच पर पकाओ, जब तक ओट्स नरम हो जाएं और मिश्रण गाढ़ा पर थोड़ा ढीला रहे।"}, "hi-Latn": {"look": "Oats phool jaayein aur mixture dheele daliye jaisa dikhe.", "safety": "Garam oats chhitakte hain, lambe chammach se chalao.", "text": "Oats aur garam masala daalkar chalate raho aur dheemi aanch par pakao, jab tak oats naram ho jaayein aur mixture gaadha par thoda dheela rahe."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 240, true, null, 'Oats swell and the mix looks like a loose porridge.', '{"en": "Oats swell and the mix looks like a loose porridge.", "heat": "low", "look": "Oats swell and the mix looks like a loose porridge."}'::jsonb, null, 'Hot oats splutter, so stir with a long spoon.'),
  ((select id from public.recipes where household_id is null and slug = 'masala-oats'), 7, 'Turn off the heat, add chopped coriander and a squeeze of lemon, and serve hot.', '{"en": "Turn off the heat, add chopped coriander and a squeeze of lemon, and serve hot.", "hi": {"smell": "ताज़े धनिए और नींबू की खुशबू आए।", "text": "आंच बंद करो, कटा हरा धनिया और नींबू निचोड़ो, और गरम परोसो।"}, "hi-Latn": {"smell": "Taaze dhaniye aur nimbu ki khushboo aaye.", "text": "Aanch band karo, kata hara dhaniya aur nimbu nichodo, aur garam paroso."}}'::jsonb, null, null, false, null, 'Fresh coriander and lemon smell comes up.', '{"en": "Fresh coriander and lemon smell comes up.", "smell": "Fresh coriander and lemon smell comes up."}'::jsonb, null, null)
