-- Recipe: masala-omelette (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('masala-omelette', 'Masala Omelette', '{"en": "Masala Omelette", "hi": "मसाला ऑमलेट", "hi-Latn": "Masala Omelette"}'::jsonb, 'A soft, fully cooked egg omelette loaded with chopped onion, tomato, green chilli and coriander, spiced with turmeric and red chilli. It is the everyday Indian breakfast omelette, eaten hot with bread or roti.', '{"hi": "प्याज़, टमाटर, हरी मिर्च और हरे धनिये से भरा, हल्दी और लाल मिर्च वाला नरम और पूरा पका अंडे का ऑमलेट। यह रोज़ का देसी नाश्ता है, जिसे गरम-गरम ब्रेड या रोटी के साथ खाया जाता है।", "hi-Latn": "Pyaaz, tamatar, hari mirch aur hare dhaniye se bhara, haldi aur laal mirch wala naram aur poora paka ande ka omelette. Yeh roz ka desi nashta hai, jise garam-garam bread ya roti ke saath khaya jaata hai."}'::jsonb, 'pan_indian', 'breakfast', 'eggetarian', 4, 10, 15, 1, 2, array['tawa', 'gas_stove']::text[], array['quick', 'high_protein']::text[], '{"acid": 0.1, "crunch": 0.1, "heat": 0.3, "rich": 0.4, "starch": 0, "sweet": 0}'::jsonb, array['protein']::text[], 'curated', 'in_review', false)
