insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'masala-omelette'), 1, 'Finely chop the onion, tomato, green chillies and coriander leaves.', '{"en": "Finely chop the onion, tomato, green chillies and coriander leaves.", "hi": {"text": "प्याज़, टमाटर, हरी मिर्च और हरा धनिया बारीक काट लें।"}, "hi-Latn": {"text": "Pyaaz, tamatar, hari mirch aur hara dhaniya bareek kaat lein."}}'::jsonb, null, 300, true, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masala-omelette'), 2, 'Break the eggs into a bowl, add salt, turmeric, red chilli powder and black pepper, and whisk well with a fork.', '{"en": "Break the eggs into a bowl, add salt, turmeric, red chilli powder and black pepper, and whisk well with a fork.", "hi": {"look": "अंडा एक-सा पीला हो जाए और ऊपर हल्का झाग आ जाए।", "text": "अंडे एक कटोरे में तोड़ें, नमक, हल्दी, लाल मिर्च और काली मिर्च डालें और काँटे से अच्छी तरह फेंटें।"}, "hi-Latn": {"look": "Anda ek-sa peela ho jaaye aur upar halka jhaag aa jaaye.", "text": "Ande ek katori mein todein, namak, haldi, laal mirch aur kaali mirch daalein aur kaante se achhi tarah phentein."}}'::jsonb, (select id from public.techniques where slug = 'batter'), 120, false, null, 'The egg turns an even yellow with a light froth on top.', '{"en": "The egg turns an even yellow with a light froth on top.", "look": "The egg turns an even yellow with a light froth on top."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masala-omelette'), 3, 'Stir the chopped vegetables into the egg and cook it soon after mixing.', '{"en": "Stir the chopped vegetables into the egg and cook it soon after mixing.", "hi": {"safety": "कच्चे अंडे का घोल बाहर रखा न छोड़ें, तुरंत पकाएँ।", "text": "कटी सब्ज़ियाँ अंडे में मिलाएँ और मिलाने के तुरंत बाद पकाएँ।"}, "hi-Latn": {"safety": "Kachche ande ka ghol bahar rakha na chhodein, turant pakaayein.", "text": "Kati sabziyaan ande mein milaayein aur milaane ke turant baad pakaayein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, 'Do not leave the raw egg mixture standing out; cook it right away.'),
  ((select id from public.recipes where household_id is null and slug = 'masala-omelette'), 4, 'Heat the tawa on medium heat and spread about 2 teaspoons of oil over it.', '{"en": "Heat the tawa on medium heat and spread about 2 teaspoons of oil over it.", "hi": {"look": "तेल चमकने लगे और आसानी से फैल जाए।", "text": "तवा मध्यम आँच पर गरम करें और उस पर लगभग 2 छोटे चम्मच तेल फैलाएँ।"}, "hi-Latn": {"look": "Tel chamakne lage aur aasaani se fail jaaye.", "text": "Tawa medium aanch par garam karein aur us par lagbhag 2 chhote chammach tel failaayein."}}'::jsonb, null, 120, false, null, 'The oil shimmers and spreads easily.', '{"en": "The oil shimmers and spreads easily.", "heat": "medium", "look": "The oil shimmers and spreads easily."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masala-omelette'), 5, 'Pour in a quarter of the egg mixture, tilt the tawa to spread it into a round, and cook on low-medium heat.', '{"en": "Pour in a quarter of the egg mixture, tilt the tawa to spread it into a round, and cook on low-medium heat.", "hi": {"look": "किनारे सख़्त हो जाएँ और ऊपर का हिस्सा लगभग जम जाए।", "sound": "हल्की, लगातार छन-छन की आवाज़।", "text": "अंडे के घोल का चौथाई हिस्सा डालें, तवा घुमाकर गोल फैलाएँ और धीमी-मध्यम आँच पर पकाएँ।"}, "hi-Latn": {"look": "Kinaare sakht ho jaayein aur upar ka hissa lagbhag jam jaaye.", "sound": "Halki, lagaataar chhan-chhan ki aawaaz.", "text": "Ande ke ghol ka chauthai hissa daalein, tawa ghumaakar gol failaayein aur dheemi-medium aanch par pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 120, false, null, 'The edges turn firm and the top is mostly set. A soft, steady sizzle.', '{"en": "The edges turn firm and the top is mostly set. A soft, steady sizzle.", "heat": "medium", "look": "The edges turn firm and the top is mostly set.", "sound": "A soft, steady sizzle."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masala-omelette'), 6, 'Flip the omelette with a spatula and cook the other side until it is set all the way through.', '{"en": "Flip the omelette with a spatula and cook the other side until it is set all the way through.", "hi": {"look": "दोनों तरफ़ सुनहरे धब्बे हों और कहीं गीला अंडा न दिखे।", "safety": "अंडा पूरी तरह जमने तक पकाएँ, अंदर कुछ भी कच्चा या बहता न रहे।", "text": "पलटे से ऑमलेट पलटें और दूसरी तरफ़ तब तक पकाएँ जब तक पूरा अंदर तक पक न जाए।", "touch": "बीच में दबाने पर सख़्त लगे और वापस उभर आए।"}, "hi-Latn": {"look": "Dono taraf sunehre dhabbe hon aur kahin geela anda na dikhe.", "safety": "Anda poori tarah jamne tak pakaayein, andar kuch bhi kachcha ya behta na rahe.", "text": "Palte se omelette palatein aur doosri taraf tab tak pakaayein jab tak poora andar tak pak na jaaye.", "touch": "Beech mein dabaane par sakht lage aur waapas ubhar aaye."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 120, false, null, 'Both sides have golden spots and no wet egg shows. The centre feels firm and springs back when pressed.', '{"en": "Both sides have golden spots and no wet egg shows. The centre feels firm and springs back when pressed.", "heat": "medium", "look": "Both sides have golden spots and no wet egg shows.", "touch": "The centre feels firm and springs back when pressed."}'::jsonb, null, 'Cook until the egg is fully set with no runny part inside.'),
  ((select id from public.recipes where household_id is null and slug = 'masala-omelette'), 7, 'Repeat with the remaining mixture, adding a little oil each time, and serve hot.', '{"en": "Repeat with the remaining mixture, adding a little oil each time, and serve hot.", "hi": {"text": "बाकी घोल से इसी तरह ऑमलेट बनाएँ, हर बार थोड़ा तेल डालें, और गरम परोसें।"}, "hi-Latn": {"text": "Baaki ghol se isi tarah omelette banaayein, har baar thoda tel daalein, aur garam parosein."}}'::jsonb, null, 540, true, null, null, '{"heat": "medium"}'::jsonb, null, null)
