insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'masoor-dal'), 1, 'Wash the masoor dal 3 to 4 times in water and soak it for 15 minutes.', '{"en": "Wash the masoor dal 3 to 4 times in water and soak it for 15 minutes.", "hi": {"look": "धोने का पानी लगभग साफ़ निकलने लगे।", "text": "मसूर दाल को 3-4 बार पानी में धोकर 15 मिनट भिगो दें।"}, "hi-Latn": {"look": "Dhone ka paani lagbhag saaf nikalne lage.", "text": "Masoor dal ko 3-4 baar paani mein dhokar 15 minute bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 900, true, null, 'The washing water runs almost clear.', '{"en": "The washing water runs almost clear.", "look": "The washing water runs almost clear."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masoor-dal'), 2, 'Drain the dal and put it in the pressure cooker with 700 ml water, the turmeric and the salt. Cook for 2 whistles on medium heat, then let the pressure drop on its own.', '{"en": "Drain the dal and put it in the pressure cooker with 700 ml water, the turmeric and the salt. Cook for 2 whistles on medium heat, then let the pressure drop on its own.", "hi": {"safety": "ढक्कन तभी खोलें जब पूरा प्रेशर निकल जाए।", "text": "दाल का पानी निकालकर उसे कुकर में डालें, साथ में 700 ml पानी, हल्दी और नमक डालें। मध्यम आँच पर 2 सीटी आने दें, फिर प्रेशर अपने आप उतरने दें।"}, "hi-Latn": {"safety": "Dhakkan tabhi kholein jab poora pressure nikal jaaye.", "text": "Dal ka paani nikaalkar use cooker mein daalein, saath mein 700 ml paani, haldi aur namak daalein. Medium aanch par 2 seeti aane dein, phir pressure apne aap utarne dein."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 600, true, 2, null, '{"heat": "medium"}'::jsonb, null, 'Open the lid only after all the pressure has gone.'),
  ((select id from public.recipes where household_id is null and slug = 'masoor-dal'), 3, 'Open the cooker and whisk the dal with a ladle until it is smooth.', '{"en": "Open the cooker and whisk the dal with a ladle until it is smooth.", "hi": {"look": "दाल मलाईदार हो जाए और कोई साबुत दाना न दिखे।", "text": "कुकर खोलकर दाल को कलछी से घोंटकर एकसार कर लें।"}, "hi-Latn": {"look": "Dal malaidaar ho jaaye aur koi saabut daana na dikhe.", "text": "Cooker kholkar dal ko kalchhi se ghontkar eksaar kar lein."}}'::jsonb, null, null, false, null, 'The dal is creamy and no whole grains are left.', '{"en": "The dal is creamy and no whole grains are left.", "look": "The dal is creamy and no whole grains are left."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masoor-dal'), 4, 'Heat the ghee in a kadai on medium heat. Add the cumin seeds and asafoetida, then add the chopped garlic and green chilli.', '{"en": "Heat the ghee in a kadai on medium heat. Add the cumin seeds and asafoetida, then add the chopped garlic and green chilli.", "hi": {"look": "लहसुन हल्का सुनहरा हो जाए।", "smell": "भुने लहसुन की खुशबू आए।", "sound": "जीरा चटकने लगे।", "text": "कड़ाही में मध्यम आँच पर घी गरम करें। जीरा और हींग डालें, फिर कटा लहसुन और हरी मिर्च डालें।"}, "hi-Latn": {"look": "Lehsun halka sunehra ho jaaye.", "smell": "Bhune lehsun ki khushboo aaye.", "sound": "Jeera chatakne lage.", "text": "Kadai mein medium aanch par ghee garam karein. Jeera aur hing daalein, phir kata lehsun aur hari mirch daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The garlic turns light golden. The cumin crackles. It smells of roasted garlic.', '{"en": "The garlic turns light golden. The cumin crackles. It smells of roasted garlic.", "heat": "medium", "look": "The garlic turns light golden.", "smell": "It smells of roasted garlic.", "sound": "The cumin crackles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masoor-dal'), 5, 'Add the chopped onion and sauté on medium heat until it turns golden.', '{"en": "Add the chopped onion and sauté on medium heat until it turns golden.", "hi": {"look": "प्याज़ सुनहरा भूरा हो जाए।", "text": "कटा प्याज़ डालें और मध्यम आँच पर सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz sunehra bhoora ho jaaye.", "text": "Kata pyaaz daalein aur medium aanch par sunehra hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 300, true, null, 'The onion turns golden brown.', '{"en": "The onion turns golden brown.", "heat": "medium", "look": "The onion turns golden brown."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masoor-dal'), 6, 'Add the chopped tomato and red chilli powder. Cook until the tomato is soft and the ghee separates.', '{"en": "Add the chopped tomato and red chilli powder. Cook until the tomato is soft and the ghee separates.", "hi": {"look": "मसाले के किनारों पर घी दिखने लगे।", "text": "कटा टमाटर और लाल मिर्च पाउडर डालें। टमाटर गलने और घी अलग होने तक पकाएँ।", "touch": "टमाटर चम्मच से आसानी से मसल जाए।"}, "hi-Latn": {"look": "Masale ke kinaaron par ghee dikhne lage.", "text": "Kata tamatar aur laal mirch powder daalein. Tamatar galne aur ghee alag hone tak pakaayein.", "touch": "Tamatar chammach se aasaani se masal jaaye."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 300, true, null, 'Ghee shows at the edges of the masala. The tomato mashes easily with the spoon.', '{"en": "Ghee shows at the edges of the masala. The tomato mashes easily with the spoon.", "heat": "medium", "look": "Ghee shows at the edges of the masala.", "touch": "The tomato mashes easily with the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masoor-dal'), 7, 'Pour in the dal and add up to 100 ml water if it is too thick. Simmer on low heat for 5 minutes and check the salt.', '{"en": "Pour in the dal and add up to 100 ml water if it is too thick. Simmer on low heat for 5 minutes and check the salt.", "hi": {"look": "दाल हल्के-हल्के उबले और कलछी से आसानी से गिरे।", "text": "दाल डालें और गाढ़ी हो तो 100 ml तक पानी मिलाएँ। धीमी आँच पर 5 मिनट उबालें और नमक चख लें।"}, "hi-Latn": {"look": "Dal halke-halke ubale aur kalchhi se aasaani se gire.", "text": "Dal daalein aur gaadhi ho to 100 ml tak paani milaayein. Dheemi aanch par 5 minute ubaalein aur namak chakh lein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, true, null, 'The dal bubbles gently and pours easily from the ladle.', '{"en": "The dal bubbles gently and pours easily from the ladle.", "heat": "low", "look": "The dal bubbles gently and pours easily from the ladle."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'masoor-dal'), 8, 'Turn off the heat, add the chopped coriander, squeeze in lemon if you like, and serve hot.', '{"en": "Turn off the heat, add the chopped coriander, squeeze in lemon if you like, and serve hot.", "hi": {"text": "आँच बंद करें, कटा हरा धनिया डालें, चाहें तो नींबू निचोड़ें और गरम परोसें।"}, "hi-Latn": {"text": "Aanch band karein, kata hara dhaniya daalein, chaahein to nimbu nichodein aur garam parosein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'masoor-dal') and step_no > 8;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'masoor-dal');

