  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('matar-paneer', 'Matar Paneer', '{"en": "Matar Paneer", "hi": "मटर पनीर", "hi-Latn": "Matar Paneer"}'::jsonb, 'Soft paneer and green peas in an onion-tomato gravy with Kashmiri chilli, finished with kasuri methi.', '{"hi": "नरम पनीर और हरे मटर, कश्मीरी मिर्च वाली प्याज़-टमाटर की ग्रेवी में, ऊपर से कसूरी मेथी।", "hi-Latn": "Naram paneer aur hare matar, Kashmiri mirch wali pyaaz-tamatar ki gravy mein, upar se kasoori methi."}'::jsonb, 'punjabi', 'main', 'veg', 4, 15, 35, 2, 2, array['kadai', 'mixer_grinder']::text[], array['comforting', 'high_protein']::text[], '{"acid": 0.4, "crunch": 0, "heat": 0.3, "rich": 0.7, "starch": 0.2, "sweet": 0.1}'::jsonb, array['sabzi', 'dairy', 'protein']::text[], 'curated', 'draft', false)
