insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'mix-veg'), 1, 'Cut potato, carrot, beans, cauliflower and capsicum into small even pieces, and finely chop onion, tomato and green chilli.', '{"en": "Cut potato, carrot, beans, cauliflower and capsicum into small even pieces, and finely chop onion, tomato and green chilli.", "hi": {"text": "आलू, गाजर, बीन्स, गोभी और शिमला मिर्च को छोटे बराबर टुकड़ों में काटो, और प्याज़, टमाटर व हरी मिर्च बारीक काट लो।"}, "hi-Latn": {"text": "Aloo, gajar, beans, gobhi aur shimla mirch ko chhote barabar tukdon mein kaato, aur pyaaz, tamatar va hari mirch bareek kaat lo."}}'::jsonb, null, 600, true, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'mix-veg'), 2, 'Heat oil in a kadai, add cumin seeds, then add onion and fry until golden.', '{"en": "Heat oil in a kadai, add cumin seeds, then add onion and fry until golden.", "hi": {"look": "प्याज़ हल्का सुनहरा हो जाए।", "sound": "तेल में डालते ही जीरा चटकने लगे।", "text": "कढ़ाई में तेल गरम करो, जीरा डालो, फिर प्याज़ डालकर सुनहरा होने तक भूनो।"}, "hi-Latn": {"look": "Pyaaz halka sunehra ho jaaye.", "sound": "Tel mein daalte hi jeera chatakne lage.", "text": "Kadai mein tel garam karo, jeera daalo, phir pyaaz daalkar sunehra hone tak bhuno."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 300, true, null, 'Onion turns light golden. Cumin crackles as soon as it hits the oil.', '{"en": "Onion turns light golden. Cumin crackles as soon as it hits the oil.", "heat": "medium", "look": "Onion turns light golden.", "sound": "Cumin crackles as soon as it hits the oil."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'mix-veg'), 3, 'Add ginger garlic paste and green chilli and stir for a minute.', '{"en": "Add ginger garlic paste and green chilli and stir for a minute.", "hi": {"smell": "लहसुन की कच्ची महक चली जाए।", "text": "अदरक लहसुन पेस्ट और हरी मिर्च डालकर एक मिनट चलाओ।"}, "hi-Latn": {"smell": "Lahsun ki kachchi mehak chali jaaye.", "text": "Adrak lahsun paste aur hari mirch daalkar ek minute chalao."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 60, false, null, 'The raw garlic smell goes away.', '{"en": "The raw garlic smell goes away.", "heat": "medium", "smell": "The raw garlic smell goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'mix-veg'), 4, 'Add tomato, turmeric, red chilli powder, coriander powder and salt, and cook the masala until soft.', '{"en": "Add tomato, turmeric, red chilli powder, coriander powder and salt, and cook the masala until soft.", "hi": {"look": "टमाटर गल जाएं और किनारों पर तेल दिखने लगे।", "text": "टमाटर, हल्दी, लाल मिर्च पाउडर, धनिया पाउडर और नमक डालो, और मसाला नरम होने तक भूनो।"}, "hi-Latn": {"look": "Tamatar gal jaayein aur kinaron par tel dikhne lage.", "text": "Tamatar, haldi, laal mirch powder, dhaniya powder aur namak daalo, aur masala naram hone tak bhuno."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 300, true, null, 'Tomatoes turn mushy and oil shows at the edges.', '{"en": "Tomatoes turn mushy and oil shows at the edges.", "heat": "medium", "look": "Tomatoes turn mushy and oil shows at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'mix-veg'), 5, 'Add all the vegetables except capsicum, mix well with the masala, sprinkle about a quarter cup of water, cover and cook, stirring now and then.', '{"en": "Add all the vegetables except capsicum, mix well with the masala, sprinkle about a quarter cup of water, cover and cook, stirring now and then.", "hi": {"text": "शिमला मिर्च छोड़कर सारी सब्ज़ियां डालो, मसाले में अच्छे से मिलाओ, लगभग चौथाई कप पानी छिड़को, ढककर पकाओ और बीच-बीच में चलाते रहो।", "touch": "आलू और गाजर में चाकू आसानी से चला जाए।"}, "hi-Latn": {"text": "Shimla mirch chhodkar saari sabziyaan daalo, masale mein achchhe se milao, lagbhag chauthai cup paani chhidko, dhakkar pakao aur beech-beech mein chalate raho.", "touch": "Aloo aur gajar mein chaaku aasaani se chala jaaye."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 720, true, null, 'A knife goes easily through the potato and carrot.', '{"en": "A knife goes easily through the potato and carrot.", "heat": "low", "touch": "A knife goes easily through the potato and carrot."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'mix-veg'), 6, 'Add capsicum and cook uncovered so it stays a little crisp.', '{"en": "Add capsicum and cook uncovered so it stays a little crisp.", "hi": {"look": "शिमला मिर्च चमकीली हरी रहे।", "text": "शिमला मिर्च डालो और बिना ढके पकाओ ताकि वह थोड़ी कुरकुरी रहे।"}, "hi-Latn": {"look": "Shimla mirch chamkeeli hari rahe.", "text": "Shimla mirch daalo aur bina dhake pakao taaki woh thodi kurkuri rahe."}}'::jsonb, null, 180, true, null, 'Capsicum stays bright green.', '{"en": "Capsicum stays bright green.", "heat": "medium", "look": "Capsicum stays bright green."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'mix-veg'), 7, 'Stir in garam masala and crushed kasuri methi if using, switch off the heat and top with coriander leaves.', '{"en": "Stir in garam masala and crushed kasuri methi if using, switch off the heat and top with coriander leaves.", "hi": {"smell": "गरम मसाले की खुशबू आने लगे।", "text": "गरम मसाला और चाहो तो मसली हुई कसूरी मेथी मिलाओ, गैस बंद करो और ऊपर से हरा धनिया डालो।"}, "hi-Latn": {"smell": "Garam masale ki khushboo aane lage.", "text": "Garam masala aur chaho to masli hui kasuri methi milao, gas band karo aur upar se hara dhaniya daalo."}}'::jsonb, null, 60, false, null, 'A warm garam masala aroma comes up.', '{"en": "A warm garam masala aroma comes up.", "heat": "low", "smell": "A warm garam masala aroma comes up."}'::jsonb, null, null)
