insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('moong-chilla', 'Moong Dal Chilla', '{"en": "Moong Dal Chilla", "hi": "मूंग दाल चीला", "hi-Latn": "Moong Dal Chilla"}'::jsonb, 'Thin, savoury pancakes made from soaked and ground yellow moong dal, with onion, green chilli, ginger and coriander. They are cooked on a tawa until golden and crisp at the edges. Serve hot with green chutney or ketchup.', '{"hi": "भीगी और पिसी हुई पीली मूंग दाल से बने पतले, नमकीन चीले, जिनमें प्याज़, हरी मिर्च, अदरक और हरा धनिया पड़ता है। इन्हें तवे पर सुनहरा होने तक सेका जाता है, किनारे कुरकुरे हो जाते हैं। हरी चटनी या केचप के साथ गरम परोसें।", "hi-Latn": "Bhigi aur pisi hui peeli moong dal se bane patle, namkeen chille, jinmein pyaaz, hari mirch, adrak aur hara dhaniya padta hai. Inhe tawe par sunehra hone tak seka jata hai, kinaare kurkure ho jaate hain. Hari chutney ya ketchup ke saath garam parosein."}'::jsonb, 'north_indian', 'breakfast', 'veg', 4, 200, 25, 2, 2, array['mixer_grinder', 'tawa', 'gas_stove']::text[], array['high_protein', 'kids_friendly', 'tiffin']::text[], '{"acid": 0.1, "crunch": 0.3, "heat": 0.3, "rich": 0.3, "starch": 0.4, "sweet": 0}'::jsonb, array['dal']::text[], 'curated', 'in_review', false)
