insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'moong-chilla'), 1, 'Wash the moong dal two or three times and soak it in plenty of water for 3 hours.', '{"en": "Wash the moong dal two or three times and soak it in plenty of water for 3 hours.", "hi": {"look": "दाल फूल जाती है और उंगलियों से दबाने पर आसानी से टूट जाती है।", "text": "मूंग दाल को दो-तीन बार धोकर भरपूर पानी में 3 घंटे भिगो दें।"}, "hi-Latn": {"look": "Dal phool jaati hai aur ungliyon se dabane par aasaani se toot jaati hai.", "text": "Moong dal ko do-teen baar dhokar bharpoor paani mein 3 ghante bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 10800, true, null, 'The dal swells and breaks easily when pressed between your fingers.', '{"en": "The dal swells and breaks easily when pressed between your fingers.", "look": "The dal swells and breaks easily when pressed between your fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-chilla'), 2, 'Drain the dal and grind it with ginger, green chilli and about half a cup of water into a smooth, thick batter.', '{"en": "Drain the dal and grind it with ginger, green chilli and about half a cup of water into a smooth, thick batter.", "hi": {"text": "दाल का पानी निकाल दें और उसे अदरक, हरी मिर्च और लगभग आधा कप पानी के साथ पीसकर चिकना, गाढ़ा घोल बना लें।", "touch": "उंगलियों में रगड़ने पर घोल चिकना लगता है और उसमें दरदरापन नहीं होता।"}, "hi-Latn": {"text": "Dal ka paani nikaal dein aur use adrak, hari mirch aur lagbhag aadha cup paani ke saath peeskar chikna, gaadha ghol bana lein.", "touch": "Ungliyon mein ragadne par ghol chikna lagta hai aur usmein dardarapan nahi hota."}}'::jsonb, (select id from public.techniques where slug = 'batter'), 180, true, null, 'The batter feels smooth with no gritty bits when rubbed between your fingers.', '{"en": "The batter feels smooth with no gritty bits when rubbed between your fingers.", "touch": "The batter feels smooth with no gritty bits when rubbed between your fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-chilla'), 3, 'Stir in salt, turmeric, cumin seeds, asafoetida, onion, tomato if using, and coriander leaves, adding a little water to make a pourable batter.', '{"en": "Stir in salt, turmeric, cumin seeds, asafoetida, onion, tomato if using, and coriander leaves, adding a little water to make a pourable batter.", "hi": {"look": "घोल करछी से धीरे-धीरे गिरता है, डोसे के घोल जैसा।", "text": "घोल में नमक, हल्दी, जीरा, हींग, प्याज़, टमाटर (अगर डाल रहे हैं) और हरा धनिया मिलाएं, और थोड़ा पानी डालकर घोल को बहने लायक बना लें।"}, "hi-Latn": {"look": "Ghol karchhi se dheere-dheere girta hai, dose ke ghol jaisa.", "text": "Ghol mein namak, haldi, jeera, hing, pyaaz, tamatar (agar daal rahe hain) aur hara dhaniya milayein, aur thoda paani daalkar ghol ko behne laayak bana lein."}}'::jsonb, null, null, false, null, 'The batter flows slowly off the ladle, like dosa batter.', '{"en": "The batter flows slowly off the ladle, like dosa batter.", "look": "The batter flows slowly off the ladle, like dosa batter."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-chilla'), 4, 'Heat the tawa on medium heat and wipe it with a few drops of oil.', '{"en": "Heat the tawa on medium heat and wipe it with a few drops of oil.", "hi": {"sound": "तवे पर पानी के छींटे मारने पर वे छनछनाकर तुरंत उड़ जाते हैं।", "text": "तवे को मध्यम आंच पर गरम करें और उस पर कुछ बूंदें तेल लगाकर पोंछ दें।"}, "hi-Latn": {"sound": "Tawe par paani ke chheente maarne par woh chhanchhanakar turant ud jaate hain.", "text": "Tawe ko madhyam aanch par garam karein aur us par kuch boondein tel lagakar ponchh dein."}}'::jsonb, null, 120, false, null, 'A few drops of water sprinkled on the tawa sizzle and vanish at once.', '{"en": "A few drops of water sprinkled on the tawa sizzle and vanish at once.", "heat": "medium", "sound": "A few drops of water sprinkled on the tawa sizzle and vanish at once."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-chilla'), 5, 'Pour a ladle of batter in the centre and spread it quickly into a thin circle, then drizzle a little oil around the edges.', '{"en": "Pour a ladle of batter in the centre and spread it quickly into a thin circle, then drizzle a little oil around the edges.", "hi": {"look": "ऊपर की सतह सूख जाती है और किनारे उठकर सुनहरे हो जाते हैं।", "text": "बीच में एक करछी घोल डालें और जल्दी से पतला गोल फैला दें, फिर किनारों पर थोड़ा तेल डालें।"}, "hi-Latn": {"look": "Upar ki satah sookh jaati hai aur kinaare uthkar sunehre ho jaate hain.", "text": "Beech mein ek karchhi ghol daalein aur jaldi se patla gol phaila dein, phir kinaaron par thoda tel daalein."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 120, false, null, 'The top turns dry, and the edges lift and turn golden.', '{"en": "The top turns dry, and the edges lift and turn golden.", "heat": "medium", "look": "The top turns dry, and the edges lift and turn golden."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-chilla'), 6, 'Flip the chilla and cook the other side until brown spots appear, then serve hot and make the rest the same way.', '{"en": "Flip the chilla and cook the other side until brown spots appear, then serve hot and make the rest the same way.", "hi": {"look": "दोनों तरफ़ सुनहरे-भूरे दाग आ जाते हैं।", "smell": "भुनी हुई दाल की खुशबू आती है।", "text": "चीले को पलटें और दूसरी तरफ़ भूरे दाग आने तक सेकें, फिर गरम परोसें और बाकी चीले भी इसी तरह बनाएं।", "touch": "बीच में दबाने पर चीला सख़्त लगता है, नरम या चिपचिपा नहीं।"}, "hi-Latn": {"look": "Dono taraf sunehre-bhure daag aa jaate hain.", "smell": "Bhuni hui dal ki khushboo aati hai.", "text": "Chille ko palatein aur doosri taraf bhure daag aane tak sekein, phir garam parosein aur baaki chille bhi isi tarah banayein.", "touch": "Beech mein dabaane par chilla sakht lagta hai, naram ya chipchipa nahi."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 120, false, null, 'Both sides have golden-brown spots. It smells of roasted dal. The chilla feels firm, not soft or sticky, when pressed in the centre.', '{"en": "Both sides have golden-brown spots. It smells of roasted dal. The chilla feels firm, not soft or sticky, when pressed in the centre.", "heat": "medium", "look": "Both sides have golden-brown spots.", "smell": "It smells of roasted dal.", "touch": "The chilla feels firm, not soft or sticky, when pressed in the centre."}'::jsonb, null, null)
