insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'moong-dal'), 1, 'Wash the moong dal in water 2 to 3 times and soak it in fresh water for 15 minutes, then drain.', '{"en": "Wash the moong dal in water 2 to 3 times and soak it in fresh water for 15 minutes, then drain.", "hi": {"look": "धोने का पानी लगभग साफ़ दिखने लगे।", "text": "मूंग दाल को 2 से 3 बार पानी से धोकर 15 मिनट के लिए ताज़े पानी में भिगो दें, फिर पानी निकाल दें।"}, "hi-Latn": {"look": "Dhone ka paani lagbhag saaf dikhne lage.", "text": "Moong dal ko 2 se 3 baar paani se dhokar 15 minute ke liye taaze paani mein bhigo dein, phir paani nikaal dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 900, true, null, 'The washing water runs almost clear.', '{"en": "The washing water runs almost clear.", "look": "The washing water runs almost clear."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-dal'), 2, 'Put the dal in the pressure cooker with 800 ml water, the turmeric and salt, and cook on medium heat for 3 whistles.', '{"en": "Put the dal in the pressure cooker with 800 ml water, the turmeric and salt, and cook on medium heat for 3 whistles.", "hi": {"safety": "ढक्कन खोलने से पहले प्रेशर अपने आप निकलने दें।", "text": "दाल को प्रेशर कुकर में 800 ml पानी, हल्दी और नमक के साथ डालें और मध्यम आँच पर 3 सीटी तक पकाएँ।"}, "hi-Latn": {"safety": "Dhakkan kholne se pehle pressure apne aap nikalne dein.", "text": "Dal ko pressure cooker mein 800 ml paani, haldi aur namak ke saath daalein aur medium aanch par 3 seeti tak pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 720, true, 3, null, '{"heat": "medium"}'::jsonb, null, 'Let the pressure drop on its own before opening the lid.'),
  ((select id from public.recipes where household_id is null and slug = 'moong-dal'), 3, 'Open the cooker and whisk the dal with a ladle until smooth.', '{"en": "Open the cooker and whisk the dal with a ladle until smooth.", "hi": {"look": "दाने टूटकर दाल मलाईदार हो जाए।", "text": "कुकर खोलें और करछी से दाल को अच्छी तरह घोटकर एकसार कर लें।"}, "hi-Latn": {"look": "Daane tootkar dal malaidaar ho jaaye.", "text": "Cooker kholein aur karchhi se dal ko achhi tarah ghotkar eksaar kar lein."}}'::jsonb, null, null, false, null, 'The grains have broken down into a creamy dal.', '{"en": "The grains have broken down into a creamy dal.", "look": "The grains have broken down into a creamy dal."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-dal'), 4, 'Heat ghee in a kadai, add cumin seeds and asafoetida, then the chopped garlic and ginger, and stir for a minute.', '{"en": "Heat ghee in a kadai, add cumin seeds and asafoetida, then the chopped garlic and ginger, and stir for a minute.", "hi": {"look": "लहसुन हल्का सुनहरा हो जाए।", "sound": "जीरा घी में चटकने लगे।", "text": "कढ़ाई में घी गरम करें, जीरा और हींग डालें, फिर कटा लहसुन और अदरक डालकर एक मिनट चलाएँ।"}, "hi-Latn": {"look": "Lehsun halka sunehra ho jaaye.", "sound": "Jeera ghee mein chatakne lage.", "text": "Kadai mein ghee garam karein, jeera aur hing daalein, phir kata lehsun aur adrak daalkar ek minute chalaayein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The garlic turns light golden. The cumin crackles in the ghee.', '{"en": "The garlic turns light golden. The cumin crackles in the ghee.", "heat": "medium", "look": "The garlic turns light golden.", "sound": "The cumin crackles in the ghee."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-dal'), 5, 'Add the chopped onion and green chilli and saute until the onion turns soft and golden.', '{"en": "Add the chopped onion and green chilli and saute until the onion turns soft and golden.", "hi": {"look": "प्याज़ नरम हो और किनारों से सुनहरा दिखे।", "text": "कटा प्याज़ और हरी मिर्च डालें और प्याज़ नरम और सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram ho aur kinaaron se sunehra dikhe.", "text": "Kata pyaaz aur hari mirch daalein aur pyaaz naram aur sunehra hone tak bhoonein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 240, true, null, 'The onion is soft and golden at the edges.', '{"en": "The onion is soft and golden at the edges.", "heat": "medium", "look": "The onion is soft and golden at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-dal'), 6, 'Add the chopped tomato and red chilli powder and cook, stirring, until the tomato is mushy.', '{"en": "Add the chopped tomato and red chilli powder and cook, stirring, until the tomato is mushy.", "hi": {"look": "मसाले के किनारों पर घी दिखने लगे।", "text": "कटा टमाटर और लाल मिर्च पाउडर डालें और चलाते हुए टमाटर गलने तक पकाएँ।"}, "hi-Latn": {"look": "Masale ke kinaaron par ghee dikhne lage.", "text": "Kata tamatar aur laal mirch powder daalein aur chalaate hue tamatar galne tak pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 240, true, null, 'Ghee starts to show at the sides of the masala.', '{"en": "Ghee starts to show at the sides of the masala.", "heat": "medium", "look": "Ghee starts to show at the sides of the masala."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-dal'), 7, 'Pour in the cooked dal, add a little hot water if it is too thick, and simmer for 5 minutes.', '{"en": "Pour in the cooked dal, add a little hot water if it is too thick, and simmer for 5 minutes.", "hi": {"look": "दाल करछी से आसानी से गिरे और हल्के-हल्के उबले।", "text": "पकी हुई दाल डालें, ज़्यादा गाढ़ी हो तो थोड़ा गरम पानी मिलाएँ और 5 मिनट धीमी आँच पर पकाएँ।"}, "hi-Latn": {"look": "Dal karchhi se aasaani se gire aur halke-halke ubale.", "text": "Paki hui dal daalein, zyada gaadhi ho to thoda garam paani milaayein aur 5 minute dheemi aanch par pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, true, null, 'The dal flows easily from the ladle and bubbles gently.', '{"en": "The dal flows easily from the ladle and bubbles gently.", "heat": "low", "look": "The dal flows easily from the ladle and bubbles gently."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moong-dal'), 8, 'Turn off the heat, sprinkle chopped coriander leaves, add lemon juice if you like, and serve hot.', '{"en": "Turn off the heat, sprinkle chopped coriander leaves, add lemon juice if you like, and serve hot.", "hi": {"text": "आँच बंद करें, कटा हरा धनिया डालें, चाहें तो नींबू का रस मिलाएँ और गरम परोसें।"}, "hi-Latn": {"text": "Aanch band karein, kata hara dhaniya daalein, chaahein to nimbu ka ras milaayein aur garam parosein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
