  source, review_status, is_published) values
  ('moth-dal', 'Rajasthani Moth Dal', '{"en": "Rajasthani Moth Dal", "hi": "राजस्थानी मोठ दाल", "hi-Latn": "Rajasthani Moth Dal"}'::jsonb, 'Whole moth beans soaked, pressure-cooked until soft, then simmered in a ghee tadka of cumin, garlic, onion and tomato. A thick, earthy everyday dal for bajra roti or rice.', '{"hi": "साबुत मोठ को भिगोकर कुकर में नरम पकाया जाता है, फिर घी में जीरा, लहसुन, प्याज़ और टमाटर के तड़के में उबाला जाता है। बाजरे की रोटी या चावल के साथ खाने वाली गाढ़ी, रोज़ की दाल।", "hi-Latn": "Saabut moth ko bhigokar cooker mein naram pakaya jaata hai, phir ghee mein jeera, lehsun, pyaaz aur tamatar ke tadke mein ubala jaata hai. Bajre ki roti ya chawal ke saath khaane wali gaadhi, roz ki dal."}'::jsonb, 'rajasthan', 'main', 'veg', 4, 15, 40, 2, 3, array['pressure_cooker', 'kadai', 'gas_stove']::text[], array['comforting']::text[], '{"acid": 0.3, "crunch": 0, "heat": 0.5, "rich": 0.4, "starch": 0.5, "sweet": 0}'::jsonb, array['dal']::text[], 'curated', 'in_review', false)
