insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'moth-dal'), 1, 'Wash the moth beans 2-3 times and soak them in plenty of water for 6 hours, then drain.', '{"en": "Wash the moth beans 2-3 times and soak them in plenty of water for 6 hours, then drain.", "hi": {"look": "दाने फूलकर लगभग दोगुने हो जाते हैं।", "text": "मोठ को 2-3 बार धोकर भरपूर पानी में 6 घंटे भिगो दें, फिर पानी निकाल दें।"}, "hi-Latn": {"look": "Daane phoolkar lagbhag dogune ho jaate hain.", "text": "Moth ko 2-3 baar dhokar bharpoor paani mein 6 ghante bhigo dein, phir paani nikaal dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 21600, true, null, 'The beans swell to almost double in size.', '{"en": "The beans swell to almost double in size.", "look": "The beans swell to almost double in size."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moth-dal'), 2, 'Pressure-cook the soaked moth with 700 ml water, the salt and turmeric for 4 whistles on medium heat, then let the pressure drop on its own.', '{"en": "Pressure-cook the soaked moth with 700 ml water, the salt and turmeric for 4 whistles on medium heat, then let the pressure drop on its own.", "hi": {"safety": "कुकर तभी खोलें जब प्रेशर पूरी तरह उतर जाए।", "text": "भीगे मोठ को 700 ml पानी, नमक और हल्दी के साथ कुकर में मध्यम आँच पर 4 सीटी तक पकाएँ, फिर प्रेशर अपने आप उतरने दें।", "touch": "दाना उँगलियों में आसानी से मसल जाता है।"}, "hi-Latn": {"safety": "Cooker tabhi kholein jab pressure poori tarah utar jaaye.", "text": "Bheege moth ko 700 ml paani, namak aur haldi ke saath cooker mein medium aanch par 4 seeti tak pakayein, phir pressure apne aap utarne dein.", "touch": "Daana ungliyon mein aasaani se masal jaata hai."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 1200, true, 4, 'A bean mashes easily between your fingers.', '{"en": "A bean mashes easily between your fingers.", "heat": "medium", "touch": "A bean mashes easily between your fingers."}'::jsonb, null, 'Open the cooker only after the pressure has fully gone down.'),
  ((select id from public.recipes where household_id is null and slug = 'moth-dal'), 3, 'Heat ghee in a kadai, add cumin seeds and asafoetida, then add chopped garlic, ginger and green chilli and stir for a minute.', '{"en": "Heat ghee in a kadai, add cumin seeds and asafoetida, then add chopped garlic, ginger and green chilli and stir for a minute.", "hi": {"smell": "लहसुन की कच्ची महक भुनी हुई खुशबू में बदल जाती है।", "sound": "घी में जीरा चटकता है।", "text": "कड़ाही में घी गरम करें, जीरा और हींग डालें, फिर कटा लहसुन, अदरक और हरी मिर्च डालकर एक मिनट चलाएँ।"}, "hi-Latn": {"smell": "Lehsun ki kachchi mehak bhuni hui khushboo mein badal jaati hai.", "sound": "Ghee mein jeera chatakta hai.", "text": "Kadai mein ghee garam karein, jeera aur hing daalein, phir kata lehsun, adrak aur hari mirch daalkar ek minute chalayein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 120, false, null, 'The cumin crackles in the ghee. The raw garlic smell turns nutty.', '{"en": "The cumin crackles in the ghee. The raw garlic smell turns nutty.", "heat": "medium", "smell": "The raw garlic smell turns nutty.", "sound": "The cumin crackles in the ghee."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moth-dal'), 4, 'Add the chopped onion and cook, stirring often, until golden.', '{"en": "Add the chopped onion and cook, stirring often, until golden.", "hi": {"look": "प्याज़ के किनारे हल्के सुनहरे हो जाते हैं।", "text": "कटा प्याज़ डालें और बार-बार चलाते हुए सुनहरा होने तक पकाएँ।"}, "hi-Latn": {"look": "Pyaaz ke kinaare halke sunehre ho jaate hain.", "text": "Kata pyaaz daalein aur baar-baar chalaate hue sunehra hone tak pakayein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 360, true, null, 'The onion turns light golden at the edges.', '{"en": "The onion turns light golden at the edges.", "heat": "medium", "look": "The onion turns light golden at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moth-dal'), 5, 'Add chopped tomato, red chilli powder and coriander powder and cook until the tomato is soft and the masala leaves ghee at the sides.', '{"en": "Add chopped tomato, red chilli powder and coriander powder and cook until the tomato is soft and the masala leaves ghee at the sides.", "hi": {"look": "मसाले के किनारों पर घी अलग दिखने लगता है।", "text": "कटा टमाटर, लाल मिर्च पाउडर और धनिया पाउडर डालें और टमाटर गलने तक, मसाला किनारों पर घी छोड़ने तक भूनें।", "touch": "टमाटर कलछी से दबाने पर मसल जाता है।"}, "hi-Latn": {"look": "Masale ke kinaaron par ghee alag dikhne lagta hai.", "text": "Kata tamatar, laal mirch powder aur dhaniya powder daalein aur tamatar galne tak, masala kinaaron par ghee chhodne tak bhunein.", "touch": "Tamatar kalchhi se dabaane par masal jaata hai."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 360, true, null, 'Ghee separates at the edges of the masala. The tomato mashes under the spoon.', '{"en": "Ghee separates at the edges of the masala. The tomato mashes under the spoon.", "heat": "medium", "look": "Ghee separates at the edges of the masala.", "touch": "The tomato mashes under the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moth-dal'), 6, 'Pour in the cooked moth with its water, lightly mash a few beans with the ladle and simmer, adding a little hot water if too thick.', '{"en": "Pour in the cooked moth with its water, lightly mash a few beans with the ladle and simmer, adding a little hot water if too thick.", "hi": {"look": "दाल गाढ़ी हो जाती है पर कलछी से बहती रहती है।", "sound": "हल्की खदबदाहट।", "text": "पकी मोठ पानी समेत डालें, कलछी से कुछ दाने हल्के मसल दें और धीमी आँच पर उबालें; ज़्यादा गाढ़ी हो तो थोड़ा गरम पानी डालें।"}, "hi-Latn": {"look": "Dal gaadhi ho jaati hai par kalchhi se behti rehti hai.", "sound": "Halki khadbadaahat.", "text": "Paki moth paani samet daalein, kalchhi se kuch daane halke masal dein aur dheemi aanch par ubaalein; zyada gaadhi ho to thoda garam paani daalein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 480, true, null, 'The dal is thick but still flows off the ladle. Gentle bubbling.', '{"en": "The dal is thick but still flows off the ladle. Gentle bubbling.", "heat": "low", "look": "The dal is thick but still flows off the ladle.", "sound": "Gentle bubbling."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'moth-dal'), 7, 'Turn off the heat, stir in garam masala, top with chopped coriander leaves and a squeeze of lemon if you like, and serve hot.', '{"en": "Turn off the heat, stir in garam masala, top with chopped coriander leaves and a squeeze of lemon if you like, and serve hot.", "hi": {"smell": "गरम मसाले और हरे धनिये की ताज़ा खुशबू।", "text": "आँच बंद करें, गरम मसाला मिलाएँ, ऊपर से कटा हरा धनिया और चाहें तो नींबू निचोड़ें, और गरम परोसें।"}, "hi-Latn": {"smell": "Garam masale aur hare dhaniye ki taaza khushboo.", "text": "Aanch band karein, garam masala milayein, upar se kata hara dhaniya aur chahein to nimbu nichodein, aur garam parosein."}}'::jsonb, null, null, false, null, 'Fresh aroma of garam masala and coriander.', '{"en": "Fresh aroma of garam masala and coriander.", "smell": "Fresh aroma of garam masala and coriander."}'::jsonb, null, null)
