-- Recipe: palak-paneer (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('palak-paneer', 'Palak Paneer', '{"en": "Palak Paneer", "hi": "पालक पनीर", "hi-Latn": "Palak Paneer"}'::jsonb, 'Soft paneer cubes in a smooth, mildly spiced spinach gravy, made the everyday home way and eaten with roti or rice.', '{"hi": "मुलायम पनीर के टुकड़े, हल्के मसाले वाली चिकनी पालक की ग्रेवी में। घर का रोज़ वाला तरीका, रोटी या चावल के साथ।", "hi-Latn": "Mulayam paneer ke tukde, halke masale wali chikni palak ki gravy mein. Ghar ka roz wala tareeka, roti ya chawal ke saath."}'::jsonb, 'north_indian', 'main', 'veg', 4, 15, 25, 2, 2, array['kadai', 'mixer_grinder', 'gas_stove']::text[], array['comforting', 'kids_friendly']::text[], '{"acid": 0.2, "crunch": 0, "heat": 0.3, "rich": 0.5, "starch": 0.1, "sweet": 0.1}'::jsonb, array['greens', 'dairy', 'sabzi']::text[], 'curated', 'in_review', false)
