insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'palak-paneer'), 1, 'Wash the spinach well, boil it in a large pot of water for 2 minutes, then drain and put it straight into cold water.', '{"en": "Wash the spinach well, boil it in a large pot of water for 2 minutes, then drain and put it straight into cold water.", "hi": {"look": "पत्ते चमकीले हरे होकर नरम पड़ जाते हैं।", "safety": "उबलता पानी अपने से दूर की तरफ़ गिराएँ ताकि भाप से न जलें।", "text": "पालक को अच्छे से धोकर बड़े बर्तन में उबलते पानी में 2 मिनट उबालें, फिर छानकर तुरंत ठंडे पानी में डाल दें।"}, "hi-Latn": {"look": "Patte chamkile hare hokar naram pad jaate hain.", "safety": "Ubalta paani apne se door ki taraf giraayein taaki bhaap se na jalein.", "text": "Palak ko achhe se dhokar bade bartan mein ubalte paani mein 2 minute ubaalein, phir chhaankar turant thande paani mein daal dein."}}'::jsonb, null, 120, false, null, 'Leaves turn bright green and go limp.', '{"en": "Leaves turn bright green and go limp.", "heat": "high", "look": "Leaves turn bright green and go limp."}'::jsonb, null, 'Pour the boiling water away from you to avoid steam burns.'),
  ((select id from public.recipes where household_id is null and slug = 'palak-paneer'), 2, 'Squeeze the spinach lightly and grind it with garlic, ginger and green chilli to a smooth puree.', '{"en": "Squeeze the spinach lightly and grind it with garlic, ginger and green chilli to a smooth puree.", "hi": {"look": "प्यूरी चिकनी और गहरी हरी हो जाती है।", "text": "पालक को हल्का निचोड़कर लहसुन, अदरक और हरी मिर्च के साथ चिकना पीस लें।"}, "hi-Latn": {"look": "Puree chikni aur gehri hari ho jaati hai.", "text": "Palak ko halka nichodkar lahsun, adrak aur hari mirch ke saath chikna pees lein."}}'::jsonb, null, 120, false, null, 'Puree is smooth and deep green.', '{"en": "Puree is smooth and deep green.", "look": "Puree is smooth and deep green."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'palak-paneer'), 3, 'Heat oil in a kadai, add cumin seeds, then add the onion and fry until golden.', '{"en": "Heat oil in a kadai, add cumin seeds, then add the onion and fry until golden.", "hi": {"look": "प्याज़ नरम और हल्का सुनहरा हो जाता है।", "safety": "गरम तेल: कड़ाही को अकेला न छोड़ें, बच्चों को दूर रखें और तेल के पास पानी न रखें।", "sound": "तेल में डालते ही जीरा चटकता है।", "text": "कड़ाही में तेल गरम करें, जीरा डालें, फिर प्याज़ डालकर सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram aur halka sunehra ho jaata hai.", "safety": "Garam tel: kadai ko akela na chhodein, bachchon ko door rakhein aur tel ke paas paani na rakhein.", "sound": "Tel mein daalte hi jeera chatakta hai.", "text": "Kadai mein tel garam karein, jeera daalein, phir pyaaz daalkar sunehra hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 360, true, null, 'Onion turns soft and light golden. Cumin seeds crackle as soon as they hit the oil.', '{"en": "Onion turns soft and light golden. Cumin seeds crackle as soon as they hit the oil.", "heat": "medium", "look": "Onion turns soft and light golden.", "sound": "Cumin seeds crackle as soon as they hit the oil."}'::jsonb, null, 'Hot oil: never leave the kadai, keep children away, and keep water away from the oil.'),
  ((select id from public.recipes where household_id is null and slug = 'palak-paneer'), 4, 'Add tomato, turmeric, kashmiri chilli powder, coriander powder and salt, and cook until the tomato is mushy.', '{"en": "Add tomato, turmeric, kashmiri chilli powder, coriander powder and salt, and cook until the tomato is mushy.", "hi": {"look": "किनारों पर तेल छूटने लगता है।", "safety": "टमाटर डालते समय गरम तेल छिटक सकता है; धीरे से डालें और थोड़ा पीछे रहें।", "smell": "मसालों की कच्ची महक चली जाती है।", "text": "टमाटर, हल्दी, कश्मीरी मिर्च, धनिया पाउडर और नमक डालकर टमाटर गलने तक पकाएँ।"}, "hi-Latn": {"look": "Kinaaron par tel chhootne lagta hai.", "safety": "Tamatar daalte samay garam tel chhitak sakta hai; dheere se daalein aur thoda peeche rahein.", "smell": "Masaalon ki kachchi mehak chali jaati hai.", "text": "Tamatar, haldi, kashmiri mirch, dhaniya powder aur namak daalkar tamatar galne tak pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 300, true, null, 'Oil starts to separate at the edges. Raw smell of spices goes away.', '{"en": "Oil starts to separate at the edges. Raw smell of spices goes away.", "heat": "medium", "look": "Oil starts to separate at the edges.", "smell": "Raw smell of spices goes away."}'::jsonb, null, 'Hot oil can splutter when the tomato goes in; add it gently and stand back.'),
  ((select id from public.recipes where household_id is null and slug = 'palak-paneer'), 5, 'Add the spinach puree and about half a cup of water, then simmer, stirring now and then.', '{"en": "Add the spinach puree and about half a cup of water, then simmer, stirring now and then.", "hi": {"look": "ग्रेवी गाढ़ी होती है और हरी बनी रहती है।", "safety": "गाढ़ी ग्रेवी उछल सकती है; पकते समय ढक्कन आधा ढककर रखें।", "sound": "ग्रेवी धीरे-धीरे बुलबुले छोड़ती है।", "text": "पालक की प्यूरी और लगभग आधा कप पानी डालें, फिर बीच-बीच में चलाते हुए धीमी आँच पर पकाएँ।"}, "hi-Latn": {"look": "Gravy gaadhi hoti hai aur hari bani rehti hai.", "safety": "Gaadhi gravy uchhal sakti hai; pakte samay dhakkan aadha dhakkar rakhein.", "sound": "Gravy dheere-dheere bulbule chhodti hai.", "text": "Palak ki puree aur lagbhag aadha cup paani daalein, phir beech-beech mein chalaate hue dheemi aanch par pakaayein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, true, null, 'Gravy thickens and stays green. Gravy bubbles gently.', '{"en": "Gravy thickens and stays green. Gravy bubbles gently.", "heat": "low", "look": "Gravy thickens and stays green.", "sound": "Gravy bubbles gently."}'::jsonb, null, 'Thick gravy can splash; keep the lid half on while it simmers.'),
  ((select id from public.recipes where household_id is null and slug = 'palak-paneer'), 6, 'Add paneer cubes, garam masala and crushed kasuri methi, and cook for 2 minutes.', '{"en": "Add paneer cubes, garam masala and crushed kasuri methi, and cook for 2 minutes.", "hi": {"text": "पनीर के टुकड़े, गरम मसाला और मसली हुई कसूरी मेथी डालकर 2 मिनट पकाएँ।", "touch": "चम्मच से दबाने पर पनीर नरम लगता है।"}, "hi-Latn": {"text": "Paneer ke tukde, garam masala aur masli hui kasuri methi daalkar 2 minute pakaayein.", "touch": "Chammach se dabaane par paneer naram lagta hai."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 120, false, null, 'Paneer feels soft when pressed with the spoon.', '{"en": "Paneer feels soft when pressed with the spoon.", "heat": "low", "touch": "Paneer feels soft when pressed with the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'palak-paneer'), 7, 'Turn off the heat, swirl in the cream if using, and serve hot.', '{"en": "Turn off the heat, swirl in the cream if using, and serve hot.", "hi": {"look": "हरी ग्रेवी पर मलाई की हल्की सफ़ेद धारियाँ दिखती हैं।", "text": "आँच बंद करें, चाहें तो मलाई डालकर हल्का मिलाएँ और गरम परोसें।"}, "hi-Latn": {"look": "Hari gravy par malai ki halki safed dhaariyaan dikhti hain.", "text": "Aanch band karein, chahein to malai daalkar halka milaayein aur garam parosein."}}'::jsonb, null, null, false, null, 'Cream makes light white streaks on the green gravy.', '{"en": "Cream makes light white streaks on the green gravy.", "look": "Cream makes light white streaks on the green gravy."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'palak-paneer') and step_no > 7;

