-- Recipe: panchmel-dal (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('panchmel-dal', 'Panchmel Dal', '{"en": "Panchmel Dal", "hi": "पंचमेल दाल", "hi-Latn": "Panchmel Dal"}'::jsonb, 'Rajasthani five-lentil dal, pressure-cooked soft and finished with a ghee tadka of cumin, cloves, hing and tomato. It goes well with bati, roti or rice.', '{"hi": "राजस्थानी पाँच दालों वाली दाल। दालें प्रेशर कुकर में नरम पकाई जाती हैं, फिर ऊपर से घी में जीरा, लौंग, हींग और टमाटर का तड़का लगता है। बाटी, रोटी या चावल के साथ बढ़िया लगती है।", "hi-Latn": "Rajasthani paanch daalon wali dal. Daalein pressure cooker mein naram pakayi jaati hain, phir upar se ghee mein jeera, laung, hing aur tamatar ka tadka lagta hai. Baati, roti ya chawal ke saath badhiya lagti hai."}'::jsonb, 'rajasthani', 'main', 'veg', 4, 35, 35, 2, 2, array['pressure_cooker', 'kadai', 'gas_stove']::text[], array['comforting', 'high_protein']::text[], '{"acid": 0.3, "crunch": 0, "heat": 0.4, "rich": 0.6, "starch": 0.5, "sweet": 0}'::jsonb, array['dal']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
  description = excluded.description, descriptions = excluded.descriptions, cuisine_region = excluded.cuisine_region, course = excluded.course,
  diet = excluded.diet, base_servings = excluded.base_servings, prep_time_min = excluded.prep_time_min,
  cook_time_min = excluded.cook_time_min, difficulty = excluded.difficulty,
  spice_level = excluded.spice_level, equipment = excluded.equipment, tags = excluded.tags,
  flavor_profile = excluded.flavor_profile, food_groups = excluded.food_groups,
  review_status = excluded.review_status, is_published = excluded.is_published;

