insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'panchmel-dal'), 1, 'Wash all five dals together in 3 to 4 changes of water, then soak them in fresh water for 30 minutes.', '{"en": "Wash all five dals together in 3 to 4 changes of water, then soak them in fresh water for 30 minutes.", "hi": {"look": "धोने का पानी लगभग साफ़ दिखने लगे।", "text": "पाँचों दालें एक साथ 3-4 पानी से धो लें, फिर ताज़े पानी में 30 मिनट भिगो दें।"}, "hi-Latn": {"look": "Dhone ka paani lagbhag saaf dikhne lage.", "text": "Paanchon daalein ek saath 3-4 paani se dho lein, phir taaze paani mein 30 minute bhigo dein."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 1800, true, null, 'The washing water runs almost clear.', '{"en": "The washing water runs almost clear.", "look": "The washing water runs almost clear."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'panchmel-dal'), 2, 'Drain the dals and put them in the pressure cooker with 800 ml water, the turmeric and the salt. Cook on medium heat for 4 whistles, then let the pressure drop on its own.', '{"en": "Drain the dals and put them in the pressure cooker with 800 ml water, the turmeric and the salt. Cook on medium heat for 4 whistles, then let the pressure drop on its own.", "hi": {"safety": "प्रेशर पूरा उतरने के बाद ही कुकर खोलें।", "text": "दालों का पानी निकालकर उन्हें कुकर में 800 मिली पानी, हल्दी और नमक के साथ डालें। मध्यम आँच पर 4 सीटी लगाएँ, फिर प्रेशर अपने आप उतरने दें।"}, "hi-Latn": {"safety": "Pressure poora utarne ke baad hi cooker kholein.", "text": "Daalon ka paani nikaal kar unhein cooker mein 800 ml paani, haldi aur namak ke saath daalein. Medium aanch par 4 seeti lagayein, phir pressure apne aap utarne dein."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 900, true, 4, null, '{"heat": "medium"}'::jsonb, null, 'Open the cooker only after the pressure has fully dropped.'),
  ((select id from public.recipes where household_id is null and slug = 'panchmel-dal'), 3, 'Open the cooker and whisk the dal well with a ladle. Add up to 200 ml hot water for a medium-thick consistency.', '{"en": "Open the cooker and whisk the dal well with a ladle. Add up to 200 ml hot water for a medium-thick consistency.", "hi": {"look": "चना दाल नरम हो और दाल मलाईदार, एकसार दिखे।", "text": "कुकर खोलकर करछी से दाल अच्छी तरह घोट लें। मध्यम गाढ़ापन लाने के लिए ज़रूरत हो तो 200 मिली तक गरम पानी मिलाएँ।", "touch": "चने का दाना उंगलियों में आसानी से मसल जाए।"}, "hi-Latn": {"look": "Chana dal naram ho aur dal malaidaar, eksaar dikhe.", "text": "Cooker khol kar karchhi se dal achhi tarah ghot lein. Medium gaadhapan laane ke liye zarurat ho to 200 ml tak garam paani milayein.", "touch": "Chane ka daana ungliyon mein aasaani se masal jaaye."}}'::jsonb, null, 120, false, null, 'The chana dal is soft and the dal looks creamy and well blended. A chana dal grain mashes easily between your fingers.', '{"en": "The chana dal is soft and the dal looks creamy and well blended. A chana dal grain mashes easily between your fingers.", "look": "The chana dal is soft and the dal looks creamy and well blended.", "touch": "A chana dal grain mashes easily between your fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'panchmel-dal'), 4, 'Heat the ghee in a kadai on medium heat. Add the cumin seeds, bay leaf, cloves, dry red chillies and asafoetida.', '{"en": "Heat the ghee in a kadai on medium heat. Add the cumin seeds, bay leaf, cloves, dry red chillies and asafoetida.", "hi": {"look": "जीरा थोड़ा गहरा हो जाए।", "smell": "हींग और लौंग की तेज़ खुशबू आए।", "sound": "जीरा घी में चटकने लगे।", "text": "कढ़ाई में मध्यम आँच पर घी गरम करें। जीरा, तेज पत्ता, लौंग, सूखी लाल मिर्च और हींग डालें।"}, "hi-Latn": {"look": "Jeera thoda gehra ho jaaye.", "smell": "Hing aur laung ki tez khushboo aaye.", "sound": "Jeera ghee mein chatakne lage.", "text": "Kadhai mein medium aanch par ghee garam karein. Jeera, tej patta, laung, sookhi laal mirch aur hing daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin turns a shade darker. The cumin crackles in the ghee. Hing and cloves smell strongly fragrant.', '{"en": "The cumin turns a shade darker. The cumin crackles in the ghee. Hing and cloves smell strongly fragrant.", "heat": "medium", "look": "The cumin turns a shade darker.", "smell": "Hing and cloves smell strongly fragrant.", "sound": "The cumin crackles in the ghee."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'panchmel-dal'), 5, 'Add the ginger, garlic and green chillies and sauté for 1 minute. Then add the tomato, red chilli powder and coriander powder and cook until the tomato is soft and the ghee separates.', '{"en": "Add the ginger, garlic and green chillies and sauté for 1 minute. Then add the tomato, red chilli powder and coriander powder and cook until the tomato is soft and the ghee separates.", "hi": {"look": "टमाटर गल जाए और किनारों पर घी दिखने लगे।", "smell": "लहसुन की कच्ची महक चली जाए।", "text": "अदरक, लहसुन और हरी मिर्च डालकर 1 मिनट भूनें। फिर टमाटर, लाल मिर्च पाउडर और धनिया पाउडर डालें। टमाटर गलने और घी अलग होने तक पकाएँ।"}, "hi-Latn": {"look": "Tamatar gal jaaye aur kinaaron par ghee dikhne lage.", "smell": "Lehsun ki kachchi mehak chali jaaye.", "text": "Adrak, lehsun aur hari mirch daal kar 1 minute bhunein. Phir tamatar, laal mirch powder aur dhaniya powder daalein. Tamatar galne aur ghee alag hone tak pakayein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 300, true, null, 'The tomato turns mushy and ghee shows at the edges. The raw garlic smell is gone.', '{"en": "The tomato turns mushy and ghee shows at the edges. The raw garlic smell is gone.", "heat": "medium", "look": "The tomato turns mushy and ghee shows at the edges.", "smell": "The raw garlic smell is gone."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'panchmel-dal'), 6, 'Pour the dal into the kadai and stir. Simmer on low heat for 5 minutes, stirring now and then.', '{"en": "Pour the dal into the kadai and stir. Simmer on low heat for 5 minutes, stirring now and then.", "hi": {"look": "तड़का अच्छे से मिल जाए और दाल धीरे-धीरे उबले।", "safety": "उबलती दाल के छींटे उड़ते हैं, इसलिए लंबी करछी से चलाएँ।", "sound": "हल्की खदबद की आवाज़ आए।", "text": "दाल को कढ़ाई में डालकर मिलाएँ। धीमी आँच पर 5 मिनट उबालें, बीच-बीच में चलाते रहें।"}, "hi-Latn": {"look": "Tadka achhe se mil jaaye aur dal dheere-dheere ubale.", "safety": "Ubalti dal ke chheente udte hain, isliye lambi karchhi se chalayein.", "sound": "Halki khadbad ki aawaaz aaye.", "text": "Dal ko kadhai mein daal kar milayein. Dheemi aanch par 5 minute ubaalein, beech-beech mein chalaate rahein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, true, null, 'The tadka is mixed through and the dal bubbles gently. A soft blup-blup of bubbling.', '{"en": "The tadka is mixed through and the dal bubbles gently. A soft blup-blup of bubbling.", "heat": "low", "look": "The tadka is mixed through and the dal bubbles gently.", "sound": "A soft blup-blup of bubbling."}'::jsonb, null, 'The dal splutters as it bubbles, so stir with a long ladle.'),
  ((select id from public.recipes where household_id is null and slug = 'panchmel-dal'), 7, 'Turn off the heat. Stir in the garam masala, then add the lemon juice and coriander leaves, if using, and serve hot.', '{"en": "Turn off the heat. Stir in the garam masala, then add the lemon juice and coriander leaves, if using, and serve hot.", "hi": {"smell": "गरम मसाले की गरम, सोंधी खुशबू आए।", "text": "आँच बंद करें। गरम मसाला मिलाएँ, फिर चाहें तो नींबू का रस और हरा धनिया डालें और गरमागरम परोसें।"}, "hi-Latn": {"smell": "Garam masale ki garam, sondhi khushboo aaye.", "text": "Aanch band karein. Garam masala milayein, phir chahein to nimbu ka ras aur hara dhaniya daalein aur garamagaram parosein."}}'::jsonb, null, null, false, null, 'The garam masala smells warm and fragrant.', '{"en": "The garam masala smells warm and fragrant.", "smell": "The garam masala smells warm and fragrant."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
