-- Recipe: paneer-bhurji (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('paneer-bhurji', 'Paneer Bhurji', '{"en": "Paneer Bhurji", "hi": "पनीर भुर्जी", "hi-Latn": "Paneer Bhurji"}'::jsonb, 'Crumbled paneer tossed with onion, tomato and green chilli in a quick, soft, lightly spiced masala. It is ready in about 20 minutes and goes well with roti, paratha or buttered pav.', '{"hi": "मसला हुआ पनीर प्याज़, टमाटर और हरी मिर्च के हल्के मसाले में जल्दी से पकाया जाता है। करीब 20 मिनट में बन जाता है और रोटी, पराठे या मक्खन लगे पाव के साथ बढ़िया लगता है।", "hi-Latn": "Masla hua paneer pyaaz, tamatar aur hari mirch ke halke masale mein jaldi se pakaya jaata hai. Kareeb 20 minute mein ban jaata hai aur roti, parathe ya makhan lage pav ke saath badhiya lagta hai."}'::jsonb, 'north_indian', 'main', 'veg', 4, 10, 15, 1, 2, array['kadai', 'gas_stove']::text[], array['quick', 'high_protein']::text[], '{"acid": 0.3, "crunch": 0.1, "heat": 0.4, "rich": 0.6, "starch": 0, "sweet": 0.1}'::jsonb, array['dairy', 'protein', 'sabzi']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
