insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'paneer-bhurji'), 1, 'Crumble the paneer with your fingers into small, uneven crumbs.', '{"en": "Crumble the paneer with your fingers into small, uneven crumbs.", "hi": {"text": "पनीर को उंगलियों से छोटे-छोटे टुकड़ों में मसल लो।", "touch": "टुकड़े नरम लगें और कोई बड़ी गांठ न बचे।"}, "hi-Latn": {"text": "Paneer ko ungliyon se chhote-chhote tukdon mein masal lo.", "touch": "Tukde naram lagein aur koi badi gaanth na bache."}}'::jsonb, null, null, false, null, 'The crumbs feel soft and there are no big lumps left.', '{"en": "The crumbs feel soft and there are no big lumps left.", "touch": "The crumbs feel soft and there are no big lumps left."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'paneer-bhurji'), 2, 'Heat the oil and butter in a kadai on medium heat, then add the cumin seeds.', '{"en": "Heat the oil and butter in a kadai on medium heat, then add the cumin seeds.", "hi": {"smell": "जीरे की भुनी खुशबू आए।", "sound": "जीरा चटकने लगे।", "text": "कढ़ाई में तेल और मक्खन मध्यम आंच पर गरम करो, फिर जीरा डालो।"}, "hi-Latn": {"smell": "Jeere ki bhuni khushboo aaye.", "sound": "Jeera chatakne lage.", "text": "Kadai mein tel aur makhan medium aanch par garam karo, phir jeera daalo."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin crackles. The cumin smells toasty.', '{"en": "The cumin crackles. The cumin smells toasty.", "heat": "medium", "smell": "The cumin smells toasty.", "sound": "The cumin crackles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'paneer-bhurji'), 3, 'Add the onion, green chilli and ginger and sauté until the onion turns soft and light golden.', '{"en": "Add the onion, green chilli and ginger and sauté until the onion turns soft and light golden.", "hi": {"look": "प्याज़ हल्का सुनहरा हो जाए।", "text": "प्याज़, हरी मिर्च और अदरक डालकर तब तक भूनो जब तक प्याज़ नरम और हल्का सुनहरा न हो जाए।"}, "hi-Latn": {"look": "Pyaaz halka sunehra ho jaaye.", "text": "Pyaaz, hari mirch aur adrak daalkar tab tak bhuno jab tak pyaaz naram aur halka sunehra na ho jaaye."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 300, true, null, 'The onion turns light golden.', '{"en": "The onion turns light golden.", "heat": "medium", "look": "The onion turns light golden."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'paneer-bhurji'), 4, 'Add the tomato, salt, turmeric, red chilli powder and coriander powder, and cook until the tomato is mushy and the oil shows at the sides.', '{"en": "Add the tomato, salt, turmeric, red chilli powder and coriander powder, and cook until the tomato is mushy and the oil shows at the sides.", "hi": {"look": "टमाटर गल जाए और किनारों पर तेल दिखे।", "text": "टमाटर, नमक, हल्दी, लाल मिर्च और धनिया पाउडर डालो, और तब तक पकाओ जब तक टमाटर गल न जाए और किनारों पर तेल न दिखे।"}, "hi-Latn": {"look": "Tamatar gal jaaye aur kinaron par tel dikhe.", "text": "Tamatar, namak, haldi, laal mirch aur dhaniya powder daalo, aur tab tak pakao jab tak tamatar gal na jaaye aur kinaron par tel na dikhe."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 300, true, null, 'The tomato is mushy and oil shows at the sides.', '{"en": "The tomato is mushy and oil shows at the sides.", "heat": "medium", "look": "The tomato is mushy and oil shows at the sides."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'paneer-bhurji'), 5, 'Lower the heat, add the crumbled paneer, garam masala and milk, and mix gently for 2 to 3 minutes so the paneer stays soft.', '{"en": "Lower the heat, add the crumbled paneer, garam masala and milk, and mix gently for 2 to 3 minutes so the paneer stays soft.", "hi": {"look": "पनीर पर मसाला बराबर लग जाए और वह नम दिखे।", "text": "आंच धीमी करो, मसला हुआ पनीर, गरम मसाला और दूध डालो, और 2-3 मिनट हल्के हाथ से मिलाओ ताकि पनीर नरम रहे।", "touch": "पनीर अभी भी नरम लगे, रबड़ जैसा नहीं।"}, "hi-Latn": {"look": "Paneer par masala barabar lag jaaye aur woh nam dikhe.", "text": "Aanch dheemi karo, masla hua paneer, garam masala aur doodh daalo, aur 2-3 minute halke haath se milao taaki paneer naram rahe.", "touch": "Paneer abhi bhi naram lage, rubber jaisa nahi."}}'::jsonb, null, 180, true, null, 'The paneer is evenly coated in masala and looks moist. The paneer still feels soft, not rubbery.', '{"en": "The paneer is evenly coated in masala and looks moist. The paneer still feels soft, not rubbery.", "heat": "low", "look": "The paneer is evenly coated in masala and looks moist.", "touch": "The paneer still feels soft, not rubbery."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'paneer-bhurji'), 6, 'Turn off the heat, sprinkle the coriander leaves on top, and serve hot with roti or pav.', '{"en": "Turn off the heat, sprinkle the coriander leaves on top, and serve hot with roti or pav.", "hi": {"text": "गैस बंद करो, ऊपर से हरा धनिया डालो और रोटी या पाव के साथ गरम परोसो।"}, "hi-Latn": {"text": "Gas band karo, upar se hara dhaniya daalo aur roti ya pav ke saath garam paroso."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
