  is_optional, group_name, role, substitutes, sort_order) values
  ((select id from public.recipes where household_id is null and slug = 'plain-dal'), (select id from public.ingredients where canonical_name = 'toor dal'), 'toor dal', 125, 'g', '1 katori', false, null, 'protein', jsonb_build_array(jsonb_build_object('ingredient_id', (select id from public.ingredients where canonical_name = 'masoor dal'), 'ingredient', 'masoor dal', 'ratio', 1, 'note', null), jsonb_build_object('ingredient_id', (select id from public.ingredients where canonical_name = 'yellow moong dal'), 'ingredient', 'yellow moong dal', 'ratio', 1, 'note', null)), 0),
  ((select id from public.recipes where household_id is null and slug = 'plain-dal'), (select id from public.ingredients where canonical_name = 'turmeric powder'), 'turmeric powder', 1.5, 'g', 'aadha chhota chammach', false, null, 'spice', '[]'::jsonb, 1),
