insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('puri', 'Puri', '{"en": "Puri", "hi": "पूरी", "hi-Latn": "Puri"}'::jsonb, 'Puffed fried wheat puris. The dough is stiffer than roti dough, so they puff and don''t soak up oil. A spoon of suji makes them crisp.', '{"hi": "फूली हुई तली गेहूँ की पूरियाँ। आटा रोटी से सख़्त गूँधा जाता है, ताकि पूरी फूले और तेल न सोखे। एक चम्मच सूजी से कुरकुरी बनती हैं।", "hi-Latn": "Phooli hui tali gehun ki puriyaan. Aata roti se sakht goondha jaata hai, taaki puri phoole aur tel na sokhe. Ek chammach suji se kurkuri banti hain."}'::jsonb, 'generic_north', 'component', 'vegan', 2, 20, 15, 2, 1, array['kadai']::text[], array['basics', 'festive']::text[], '{"acid": 0, "crunch": 0.5, "heat": 0, "rich": 0.6, "starch": 1, "sweet": 0}'::jsonb, array['grain']::text[], 'curated', 'draft', false)
