insert into public.recipe_variation_rules (recipe_id, rule_type, condition, action, note) values
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 'equipment', '{"missing_equipment": "pressure_cooker"}'::jsonb, '{"at_step": 2, "method": "boil", "minutes": 90}'::jsonb, 'Boil hard for the first 10 minutes, then simmer covered until every bean is completely soft.'),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 'time', '{"max_time_min": 45}'::jsonb, '{"requires": "soaked_or_cooked_rajma"}'::jsonb, 'Only quick if the rajma is already soaked or boiled.');

-- Recipe: rasam (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('rasam', 'Tomato Rasam', '{"en": "Tomato Rasam", "hi": "टमाटर रसम", "hi-Latn": "Tamatar Rasam"}'::jsonb, 'A thin, tangy South Indian rasam of tomato, tamarind and crushed pepper-garlic, made with a little toor dal and finished with a ghee tadka. Drink it hot or pour it over rice.', '{"hi": "टमाटर, इमली और कुटी काली मिर्च-लहसुन से बना पतला, खट्टा दक्षिण भारतीय रसम, जिसमें थोड़ी अरहर दाल और ऊपर से घी का तड़का होता है। इसे गरम-गरम पिएं या चावल के साथ खाएं।", "hi-Latn": "Tamatar, imli aur kuti kaali mirch-lahsun se bana patla, khatta South Indian rasam, jismein thodi toor dal aur upar se ghee ka tadka hota hai. Ise garam-garam piyo ya chawal ke saath khao."}'::jsonb, 'tamil_nadu', 'main', 'veg', 4, 15, 30, 2, 3, array['pressure_cooker', 'kadai', 'gas_stove']::text[], array['comforting', 'light', 'one_pot']::text[], '{"acid": 0.8, "crunch": 0, "heat": 0.5, "rich": 0.2, "starch": 0.1, "sweet": 0.1}'::jsonb, array['dal', 'sabzi']::text[], 'curated', 'in_review', false)
