insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'rasam'), 1, 'Wash the toor dal, add turmeric and 1 cup water, and pressure-cook for 3 whistles, then mash it smooth once the pressure drops.', '{"en": "Wash the toor dal, add turmeric and 1 cup water, and pressure-cook for 3 whistles, then mash it smooth once the pressure drops.", "hi": {"look": "दाल मैश होकर चिकनी हो जाती है, कोई साबुत दाना नहीं दिखता।", "safety": "कुकर तभी खोलें जब प्रेशर अपने आप उतर जाए।", "text": "अरहर दाल धोकर उसमें हल्दी और 1 कप पानी डालें, प्रेशर कुकर में 3 सीटी तक पकाएं, फिर प्रेशर उतरने पर उसे चिकना मैश कर लें।"}, "hi-Latn": {"look": "Dal mash hokar smooth ho jaati hai, koi saabut daana nahi dikhta.", "safety": "Cooker tabhi kholo jab pressure apne aap utar jaaye.", "text": "Toor dal dhokar usmein haldi aur 1 cup paani daalo, pressure cooker mein 3 seeti tak pakao, phir pressure utarne par use smooth mash kar lo."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 720, true, 3, 'The dal mashes into a smooth paste with no whole grains left.', '{"en": "The dal mashes into a smooth paste with no whole grains left.", "heat": "medium", "look": "The dal mashes into a smooth paste with no whole grains left."}'::jsonb, null, 'Open the cooker only after the pressure drops by itself.'),
  ((select id from public.recipes where household_id is null and slug = 'rasam'), 2, 'Soak the tamarind in 1 cup warm water for 10 minutes, squeeze it well and strain out the pulp water.', '{"en": "Soak the tamarind in 1 cup warm water for 10 minutes, squeeze it well and strain out the pulp water.", "hi": {"text": "इमली को 1 कप गुनगुने पानी में 10 मिनट भिगोएं, अच्छी तरह मसलें और उसका पानी छान लें।", "touch": "इमली नरम हो जाती है और उंगलियों में आसानी से घुल जाती है।"}, "hi-Latn": {"text": "Imli ko 1 cup gungune paani mein 10 minute bhigo do, achhi tarah masal kar uska paani chhaan lo.", "touch": "Imli naram ho jaati hai aur ungliyon mein aasaani se ghul jaati hai."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 600, true, null, 'The tamarind turns soft and comes apart easily between your fingers.', '{"en": "The tamarind turns soft and comes apart easily between your fingers.", "touch": "The tamarind turns soft and comes apart easily between your fingers."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rasam'), 3, 'Coarsely crush the garlic, black pepper and cumin seeds together with a rolling pin or in a mortar.', '{"en": "Coarsely crush the garlic, black pepper and cumin seeds together with a rolling pin or in a mortar.", "hi": {"look": "दरदरे टुकड़े दिखें, बारीक पाउडर नहीं।", "smell": "काली मिर्च और लहसुन की तीखी खुशबू आती है।", "text": "लहसुन, काली मिर्च और जीरा को बेलन या खल-बट्टे से एक साथ दरदरा कूट लें।"}, "hi-Latn": {"look": "Dardare tukde dikhen, baarik powder nahi.", "smell": "Kaali mirch aur lahsun ki teekhi khushboo aati hai.", "text": "Lahsun, kaali mirch aur jeera ko belan ya khal-batte se ek saath dardara kooti lo."}}'::jsonb, null, null, false, null, 'Coarse, rough bits, not a fine powder. A sharp smell of pepper and garlic.', '{"en": "Coarse, rough bits, not a fine powder. A sharp smell of pepper and garlic.", "look": "Coarse, rough bits, not a fine powder.", "smell": "A sharp smell of pepper and garlic."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rasam'), 4, 'In a kadai, add the tamarind water, chopped tomatoes, crushed masala, rasam powder, salt, a few curry leaves and jaggery if using, and boil on medium heat for 8 to 10 minutes.', '{"en": "In a kadai, add the tamarind water, chopped tomatoes, crushed masala, rasam powder, salt, a few curry leaves and jaggery if using, and boil on medium heat for 8 to 10 minutes.", "hi": {"look": "टमाटर नरम होकर गल जाते हैं।", "smell": "इमली की कच्ची महक चली जाती है।", "text": "कड़ाही में इमली का पानी, कटे टमाटर, कुटा मसाला, रसम पाउडर, नमक, कुछ कढ़ी पत्ते और चाहें तो गुड़ डालें, और मध्यम आंच पर 8 से 10 मिनट उबालें।"}, "hi-Latn": {"look": "Tamatar naram hokar gal jaate hain.", "smell": "Imli ki kachchi mehak chali jaati hai.", "text": "Kadai mein imli ka paani, kate tamatar, kuta masala, rasam powder, namak, kuch kadi patte aur chaho to gud daalo, aur medium aanch par 8 se 10 minute ubaalo."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 600, true, null, 'The tomatoes turn soft and mushy. The raw tamarind smell goes away.', '{"en": "The tomatoes turn soft and mushy. The raw tamarind smell goes away.", "heat": "medium", "look": "The tomatoes turn soft and mushy.", "smell": "The raw tamarind smell goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rasam'), 5, 'Add the mashed dal and 2 cups water, stir, and heat on low just until froth rises on top, then switch off without letting it boil hard.', '{"en": "Add the mashed dal and 2 cups water, stir, and heat on low just until froth rises on top, then switch off without letting it boil hard.", "hi": {"look": "ऊपर हल्का झाग जमा होकर उठने लगता है।", "text": "मैश की हुई दाल और 2 कप पानी डालकर चलाएं, धीमी आंच पर तब तक गरम करें जब तक ऊपर झाग न उठे, फिर तेज़ उबाल आने से पहले गैस बंद कर दें।"}, "hi-Latn": {"look": "Upar halka jhaag jama hokar uthne lagta hai.", "text": "Mash ki hui dal aur 2 cup paani daalkar chalao, dheemi aanch par tab tak garam karo jab tak upar jhaag na uthe, phir tez ubaal aane se pehle gas band kar do."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, true, null, 'A light froth gathers and rises on the surface.', '{"en": "A light froth gathers and rises on the surface.", "heat": "low", "look": "A light froth gathers and rises on the surface."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rasam'), 6, 'Heat ghee in a small pan, add mustard seeds, and when they crackle add dry red chillies, asafoetida and curry leaves, then pour the tadka into the rasam.', '{"en": "Heat ghee in a small pan, add mustard seeds, and when they crackle add dry red chillies, asafoetida and curry leaves, then pour the tadka into the rasam.", "hi": {"safety": "कढ़ी पत्ते डालते समय थोड़ा पीछे हटें, गरम घी छिटकता है।", "smell": "घी और हींग की सौंधी खुशबू आती है।", "sound": "राई चटकती है और कढ़ी पत्ते छनछनाते हैं।", "text": "छोटे पैन में घी गरम करें, राई डालें, और जब वह चटकने लगे तो सूखी लाल मिर्च, हींग और कढ़ी पत्ते डालें, फिर यह तड़का रसम में डाल दें।"}, "hi-Latn": {"safety": "Kadi patte daalte samay thoda peeche hato, garam ghee chhitakta hai.", "smell": "Ghee aur hing ki saundhi khushboo aati hai.", "sound": "Rai chatakti hai aur kadi patte chhanchhanate hain.", "text": "Chhote pan mein ghee garam karo, rai daalo, aur jab woh chatakne lage to sookhi laal mirch, hing aur kadi patte daalo, phir yeh tadka rasam mein daal do."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 120, false, null, 'The mustard seeds crackle and the curry leaves sizzle. A nutty smell of ghee and hing.', '{"en": "The mustard seeds crackle and the curry leaves sizzle. A nutty smell of ghee and hing.", "heat": "medium", "smell": "A nutty smell of ghee and hing.", "sound": "The mustard seeds crackle and the curry leaves sizzle."}'::jsonb, null, 'Stand back when adding the curry leaves, the hot ghee splutters.'),
  ((select id from public.recipes where household_id is null and slug = 'rasam'), 7, 'Add the chopped coriander leaves, cover for 5 minutes, and serve hot with rice or in a cup.', '{"en": "Add the chopped coriander leaves, cover for 5 minutes, and serve hot with rice or in a cup.", "hi": {"smell": "रसम से काली मिर्च और ताज़े धनिए की खुशबू आती है।", "text": "कटा हरा धनिया डालें, 5 मिनट ढककर रखें, और चावल के साथ या कप में गरम-गरम परोसें।"}, "hi-Latn": {"smell": "Rasam se kaali mirch aur taaze dhaniye ki khushboo aati hai.", "text": "Kata hara dhaniya daalo, 5 minute dhak kar rakho, aur chawal ke saath ya cup mein garam-garam parosو."}}'::jsonb, null, 300, true, null, 'The rasam smells of pepper and fresh coriander.', '{"en": "The rasam smells of pepper and fresh coriander.", "smell": "The rasam smells of pepper and fresh coriander."}'::jsonb, null, null)
