-- Recipe: rava-dosa (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('rava-dosa', 'Rava Dosa', '{"en": "Rava Dosa", "hi": "रवा डोसा", "hi-Latn": "Rava Dosa"}'::jsonb, 'A crisp, lacy South Indian dosa made from a thin batter of semolina, rice flour and a little refined flour, flecked with onion, green chilli, ginger, cumin and curry leaves. It needs no grinding or fermenting. Serve hot with coconut chutney or sambar.', '{"hi": "सूजी, चावल के आटे और थोड़े मैदे के पतले घोल से बना कुरकुरा, जालीदार दक्षिण भारतीय डोसा। इसमें प्याज़, हरी मिर्च, अदरक, जीरा और करी पत्ता पड़ता है। न पीसना है, न खमीर उठाना है। गरम-गरम नारियल चटनी या सांभर के साथ परोसें।", "hi-Latn": "Suji, chawal ke aate aur thode maide ke patle ghol se bana crispy, jaalidaar South Indian dosa. Isme pyaaz, hari mirch, adrak, jeera aur curry patta padta hai. Na peesna hai, na khameer uthana hai. Garam-garam nariyal chutney ya sambar ke saath parosein."}'::jsonb, 'south_indian_karnataka_', 'breakfast', 'vegan', 4, 30, 30, 3, 2, array['tawa', 'gas_stove']::text[], array['quick']::text[], '{"acid": 0, "crunch": 0.7, "heat": 0.3, "rich": 0.3, "starch": 0.7, "sweet": 0}'::jsonb, array['grain']::text[], 'curated', 'in_review', false)
