-- Recipe: sabudana-khichdi (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('sabudana-khichdi', 'Sabudana Khichdi', '{"en": "Sabudana Khichdi", "hi": "साबूदाना खिचड़ी", "hi-Latn": "Sabudana Khichdi"}'::jsonb, 'A Maharashtrian breakfast and fast-day favourite: soaked sabudana pearls tossed in ghee with cumin, green chilli, soft potato cubes and crushed roasted peanuts, finished with lemon and coriander.', '{"hi": "महाराष्ट्र का पसंदीदा नाश्ता और व्रत का खाना। भीगे साबूदाने को घी में जीरा, हरी मिर्च, नरम आलू और भुनी कुटी मूंगफली के साथ हल्के हाथ से मिलाकर पकाया जाता है। ऊपर से नींबू और हरा धनिया डाला जाता है।", "hi-Latn": "Maharashtra ka pasandida nashta aur vrat ka khana. Bhige sabudane ko ghee mein jeera, hari mirch, naram aloo aur bhuni kuti moongphali ke saath halke haath se milakar pakaya jata hai. Upar se nimbu aur hara dhaniya dala jata hai."}'::jsonb, 'maharashtra', 'breakfast', 'veg', 4, 15, 20, 2, 2, array['kadai', 'gas_stove', 'mixer_grinder']::text[], array['fasting', 'comforting', 'one_pot']::text[], '{"acid": 0.2, "crunch": 0.3, "heat": 0.3, "rich": 0.5, "starch": 0.8, "sweet": 0.1}'::jsonb, array['grain', 'sabzi']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
