insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'sabudana-khichdi'), 1, 'Rinse the sabudana 2-3 times, then soak it in water that just reaches the top of the pearls for 5-6 hours or overnight.', '{"en": "Rinse the sabudana 2-3 times, then soak it in water that just reaches the top of the pearls for 5-6 hours or overnight.", "hi": {"look": "दाने फूल गए हैं और सारा पानी सोख लिया है।", "text": "साबूदाने को 2-3 बार धो लें, फिर इतने पानी में 5-6 घंटे या रात भर भिगो दें कि पानी बस दानों के ऊपर तक आए।", "touch": "दाना दो उंगलियों में आसानी से दब जाता है, बीच में सख्ती नहीं रहती।"}, "hi-Latn": {"look": "Daane phool gaye hain aur saara paani sokh liya hai.", "text": "Sabudane ko 2-3 baar dho lein, phir itne paani mein 5-6 ghante ya raat bhar bhigo dein ki paani bas daanon ke upar tak aaye.", "touch": "Daana do ungliyon mein aasani se dab jata hai, beech mein sakhti nahi rehti."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 18000, true, null, 'The pearls have swollen and the water is fully absorbed. A pearl squashes easily between two fingers with no hard centre.', '{"en": "The pearls have swollen and the water is fully absorbed. A pearl squashes easily between two fingers with no hard centre.", "look": "The pearls have swollen and the water is fully absorbed.", "touch": "A pearl squashes easily between two fingers with no hard centre."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sabudana-khichdi'), 2, 'Dry roast the peanuts in a kadai, then cool, rub off the skins and crush them coarsely in the mixer.', '{"en": "Dry roast the peanuts in a kadai, then cool, rub off the skins and crush them coarsely in the mixer.", "hi": {"look": "छिलके चटकने लगते हैं और मूंगफली सुनहरी हो जाती है।", "smell": "भुनी मूंगफली की खुशबू आने लगती है।", "text": "कढ़ाई में मूंगफली सूखी भून लें, फिर ठंडी करके छिलके रगड़कर निकालें और मिक्सी में दरदरा कूट लें।"}, "hi-Latn": {"look": "Chhilke chatakne lagte hain aur moongphali sunehri ho jati hai.", "smell": "Bhuni moongphali ki khushboo aane lagti hai.", "text": "Kadai mein moongphali sookhi bhoon lein, phir thandi karke chhilke ragadkar nikalein aur mixie mein dardara koot lein."}}'::jsonb, (select id from public.techniques where slug = 'dry_roast'), 360, true, null, 'The skins crack and the peanuts turn golden. A nutty roasted smell rises.', '{"en": "The skins crack and the peanuts turn golden. A nutty roasted smell rises.", "heat": "medium", "look": "The skins crack and the peanuts turn golden.", "smell": "A nutty roasted smell rises."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sabudana-khichdi'), 3, 'Mix the crushed peanuts, rock salt and sugar into the soaked sabudana so every pearl is coated.', '{"en": "Mix the crushed peanuts, rock salt and sugar into the soaked sabudana so every pearl is coated.", "hi": {"look": "दाने अलग-अलग और मूंगफली से लिपटे दिखते हैं, गुठलियां नहीं होतीं।", "text": "भीगे साबूदाने में कुटी मूंगफली, सेंधा नमक और चीनी मिला दें ताकि हर दाने पर लग जाए।"}, "hi-Latn": {"look": "Daane alag-alag aur moongphali se lipte dikhte hain, gutthliyan nahi hotin.", "text": "Bhige sabudane mein kuti moongphali, sendha namak aur cheeni mila dein taaki har daane par lag jaye."}}'::jsonb, null, null, false, null, 'The pearls look separate and dusted, not lumpy.', '{"en": "The pearls look separate and dusted, not lumpy.", "look": "The pearls look separate and dusted, not lumpy."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sabudana-khichdi'), 4, 'Heat ghee in the kadai, add cumin seeds, slit green chillies and curry leaves.', '{"en": "Heat ghee in the kadai, add cumin seeds, slit green chillies and curry leaves.", "hi": {"safety": "गरम घी में मिर्च और करी पत्ते छिटकते हैं, चेहरा दूर रखें।", "sound": "जीरा चटकने लगता है।", "text": "कढ़ाई में घी गरम करें, जीरा, लंबी कटी हरी मिर्च और करी पत्ते डालें।"}, "hi-Latn": {"safety": "Garam ghee mein mirch aur curry patte chhitakte hain, chehra door rakhein.", "sound": "Jeera chatakne lagta hai.", "text": "Kadai mein ghee garam karein, jeera, lambi kati hari mirch aur curry patte daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin crackles.', '{"en": "The cumin crackles.", "heat": "medium", "sound": "The cumin crackles."}'::jsonb, null, 'Chillies and curry leaves spit in hot ghee, so keep your face back.'),
  ((select id from public.recipes where household_id is null and slug = 'sabudana-khichdi'), 5, 'Add the peeled potato cubes, cover and cook until soft, stirring once or twice.', '{"en": "Add the peeled potato cubes, cover and cook until soft, stirring once or twice.", "hi": {"text": "छिले हुए आलू के टुकड़े डालें, ढककर नरम होने तक पकाएं, बीच में एक-दो बार चलाएं।", "touch": "चाकू की नोक आलू में आसानी से घुस जाती है।"}, "hi-Latn": {"text": "Chhile hue aloo ke tukde daalein, dhakkar naram hone tak pakayein, beech mein ek-do baar chalayein.", "touch": "Chaku ki nok aloo mein aasani se ghus jati hai."}}'::jsonb, null, 420, true, null, 'A knife tip goes through a cube easily.', '{"en": "A knife tip goes through a cube easily.", "heat": "low", "touch": "A knife tip goes through a cube easily."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sabudana-khichdi'), 6, 'Add the sabudana mix and toss gently, uncovered, until the pearls turn see-through.', '{"en": "Add the sabudana mix and toss gently, uncovered, until the pearls turn see-through.", "hi": {"look": "ज़्यादातर दाने पारदर्शी हो जाते हैं, बीच में सफेदी नहीं रहती; चिपचिपा होने से पहले उतार लें।", "text": "साबूदाने का मिश्रण डालें और बिना ढके हल्के हाथ से चलाते हुए पकाएं जब तक दाने पारदर्शी न हो जाएं।"}, "hi-Latn": {"look": "Zyadatar daane paardarshi ho jate hain, beech mein safedi nahi rehti; chipchipa hone se pehle utaar lein.", "text": "Sabudane ka mishran daalein aur bina dhake halke haath se chalate hue pakayein jab tak daane paardarshi na ho jayein."}}'::jsonb, null, 420, true, null, 'Most pearls turn translucent with no white centre; take it off before it turns sticky.', '{"en": "Most pearls turn translucent with no white centre; take it off before it turns sticky.", "heat": "low", "look": "Most pearls turn translucent with no white centre; take it off before it turns sticky."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sabudana-khichdi'), 7, 'Turn off the heat, squeeze in lemon juice, scatter coriander and serve hot.', '{"en": "Turn off the heat, squeeze in lemon juice, scatter coriander and serve hot.", "hi": {"text": "आंच बंद करें, नींबू का रस निचोड़ें, हरा धनिया डालें और गरम-गरम परोसें।"}, "hi-Latn": {"text": "Aanch band karein, nimbu ka ras nichodein, hara dhaniya daalein aur garam-garam parosein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'sabudana-khichdi') and step_no > 7;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'sabudana-khichdi');

