  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('sambar', 'Sambar', '{"en": "Sambar", "hi": "सांभर", "hi-Latn": "Sambar"}'::jsonb, 'A homestyle South Indian sambar of tangy tamarind, soft toor dal, drumstick and brinjal, finished with a mustard seed and curry leaf tadka. Serve it hot with rice, idli or dosa.', '{"hi": "खट्टी इमली, नरम अरहर दाल, सहजन और बैंगन से बना घर जैसा दक्षिण भारतीय सांभर, जिस पर राई और करी पत्ते का तड़का लगता है। इसे चावल, इडली या डोसा के साथ गरम परोसें।", "hi-Latn": "Khatti imli, naram arhar dal, sahjan aur baingan se bana ghar jaisa South Indian sambar, jis par rai aur kadi patte ka tadka lagta hai. Ise chawal, idli ya dosa ke saath garam parosein."}'::jsonb, 'south_indian', 'main', 'vegan', 4, 15, 35, 2, 3, array['pressure_cooker', 'kadai', 'gas_stove']::text[], array['comforting']::text[], '{"acid": 0.7, "crunch": 0.1, "heat": 0.4, "rich": 0.3, "starch": 0.4, "sweet": 0.1}'::jsonb, array['dal', 'sabzi']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
