insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'sambar'), 1, 'Wash the toor dal, add turmeric and 450 ml water, and pressure-cook for 3 whistles on medium heat, then mash it smooth.', '{"en": "Wash the toor dal, add turmeric and 450 ml water, and pressure-cook for 3 whistles on medium heat, then mash it smooth.", "hi": {"look": "दाल नरम हो जाती है और मैश करने पर चिकना पेस्ट बन जाती है।", "safety": "कुकर खोलने से पहले प्रेशर अपने आप उतरने दें।", "text": "अरहर दाल धोकर उसमें हल्दी और 450 ml पानी डालें, मध्यम आँच पर 3 सीटी तक प्रेशर कुक करें, फिर दाल को अच्छी तरह मैश करें।"}, "hi-Latn": {"look": "Dal naram ho jaati hai aur mash karne par chikna paste ban jaati hai.", "safety": "Cooker kholne se pehle pressure apne aap utarne dein.", "text": "Arhar dal dho kar usme haldi aur 450 ml paani daalein, medium aanch par 3 seeti tak pressure cook karein, phir dal ko achhi tarah mash karein."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 720, true, 3, 'The dal is soft and mashes into a smooth paste.', '{"en": "The dal is soft and mashes into a smooth paste.", "heat": "medium", "look": "The dal is soft and mashes into a smooth paste."}'::jsonb, null, 'Let the pressure drop on its own before you open the cooker.'),
  ((select id from public.recipes where household_id is null and slug = 'sambar'), 2, 'Soak the tamarind in 200 ml warm water for 10 minutes, then squeeze it well and strain out the juice.', '{"en": "Soak the tamarind in 200 ml warm water for 10 minutes, then squeeze it well and strain out the juice.", "hi": {"text": "इमली को 200 ml गुनगुने पानी में 10 मिनट भिगोएँ, फिर अच्छे से मसलकर उसका रस छान लें।", "touch": "गूदा नरम लगता है और रेशों से आसानी से अलग हो जाता है।"}, "hi-Latn": {"text": "Imli ko 200 ml gunguney paani mein 10 minute bhigoyein, phir achhe se masal kar uska ras chhaan lein.", "touch": "Gooda naram lagta hai aur reshon se aasani se alag ho jaata hai."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 600, true, null, 'The pulp feels soft and comes away from the fibres easily.', '{"en": "The pulp feels soft and comes away from the fibres easily.", "touch": "The pulp feels soft and comes away from the fibres easily."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sambar'), 3, 'Heat half the oil in a kadai, sauté the chopped onion until soft, then add the tomato and cook until mushy.', '{"en": "Heat half the oil in a kadai, sauté the chopped onion until soft, then add the tomato and cook until mushy.", "hi": {"look": "प्याज़ पारदर्शी हो जाता है और टमाटर गल जाता है।", "text": "कड़ाही में आधा तेल गरम करें, कटा प्याज़ नरम होने तक भूनें, फिर टमाटर डालकर गलने तक पकाएँ।"}, "hi-Latn": {"look": "Pyaaz transparent ho jaata hai aur tamatar gal jaata hai.", "text": "Kadai mein aadha tel garam karein, kata pyaaz naram hone tak bhunein, phir tamatar daal kar galne tak pakayein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 300, true, null, 'The onion turns translucent and the tomato breaks down.', '{"en": "The onion turns translucent and the tomato breaks down.", "heat": "medium", "look": "The onion turns translucent and the tomato breaks down."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sambar'), 4, 'Add the drumstick pieces, brinjal, salt and tamarind water, then cover and cook until the vegetables are tender.', '{"en": "Add the drumstick pieces, brinjal, salt and tamarind water, then cover and cook until the vegetables are tender.", "hi": {"text": "सहजन के टुकड़े, बैंगन, नमक और इमली का पानी डालें, फिर ढककर सब्ज़ियाँ नरम होने तक पकाएँ।", "touch": "चाकू सहजन और बैंगन में आसानी से चला जाता है।"}, "hi-Latn": {"text": "Sahjan ke tukde, baingan, namak aur imli ka paani daalein, phir dhak kar sabziyan naram hone tak pakayein.", "touch": "Chaaku sahjan aur baingan mein aasani se chala jaata hai."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 600, true, null, 'A knife goes easily through the drumstick and brinjal.', '{"en": "A knife goes easily through the drumstick and brinjal.", "heat": "medium", "touch": "A knife goes easily through the drumstick and brinjal."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sambar'), 5, 'Stir in the sambar powder, mashed dal, jaggery and about 400 ml water, then simmer until it thickens slightly.', '{"en": "Stir in the sambar powder, mashed dal, jaggery and about 400 ml water, then simmer until it thickens slightly.", "hi": {"look": "सांभर बहने लायक रहता है पर चम्मच के पीछे लिपट जाता है।", "smell": "सांभर मसाले की कच्ची महक चली जाती है।", "text": "सांभर मसाला, मैश की हुई दाल, गुड़ और लगभग 400 ml पानी मिलाएँ, फिर हल्का गाढ़ा होने तक धीमी आँच पर उबालें।"}, "hi-Latn": {"look": "Sambar behne laayak rehta hai par chammach ke peeche lipat jaata hai.", "smell": "Sambar masale ki kachchi mehak chali jaati hai.", "text": "Sambar masala, mash ki hui dal, gud aur lagbhag 400 ml paani milayein, phir halka gaadha hone tak dheemi aanch par ubaalein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 480, true, null, 'The sambar is pourable but coats the back of a spoon. The raw smell of the sambar powder goes away.', '{"en": "The sambar is pourable but coats the back of a spoon. The raw smell of the sambar powder goes away.", "heat": "low", "look": "The sambar is pourable but coats the back of a spoon.", "smell": "The raw smell of the sambar powder goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sambar'), 6, 'Heat the remaining oil in a small pan, crackle the mustard seeds, then add fenugreek seeds, dry red chillies, curry leaves and asafoetida.', '{"en": "Heat the remaining oil in a small pan, crackle the mustard seeds, then add fenugreek seeds, dry red chillies, curry leaves and asafoetida.", "hi": {"safety": "करी पत्ते डालते समय पीछे हटें, क्योंकि गरम तेल छिटकता है।", "smell": "करी पत्तों से खुशबू आती है।", "sound": "राई चट-चट करके फूटती है।", "text": "छोटे पैन में बचा हुआ तेल गरम करें, राई चटकाएँ, फिर मेथी दाना, सूखी लाल मिर्च, करी पत्ते और हींग डालें।"}, "hi-Latn": {"safety": "Kadi patte daalte samay peeche hatein, kyunki garam tel chhitakta hai.", "smell": "Kadi patton se khushboo aati hai.", "sound": "Rai chat-chat karke phootti hai.", "text": "Chhote pan mein bacha hua tel garam karein, rai chatkayein, phir methi dana, sookhi lal mirch, kadi patte aur hing daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The mustard seeds pop and crackle. The curry leaves smell fragrant.', '{"en": "The mustard seeds pop and crackle. The curry leaves smell fragrant.", "heat": "medium", "smell": "The curry leaves smell fragrant.", "sound": "The mustard seeds pop and crackle."}'::jsonb, null, 'Stand back as you add the curry leaves, because the hot oil splutters.'),
  ((select id from public.recipes where household_id is null and slug = 'sambar'), 7, 'Pour the tadka over the sambar, add chopped coriander, and keep it covered for 5 minutes before serving hot.', '{"en": "Pour the tadka over the sambar, add chopped coriander, and keep it covered for 5 minutes before serving hot.", "hi": {"sound": "तड़का सांभर में पड़ते ही छनछनाता है।", "text": "तड़का सांभर पर डालें, कटा हरा धनिया मिलाएँ और परोसने से पहले 5 मिनट ढककर रखें, फिर गरम परोसें।"}, "hi-Latn": {"sound": "Tadka sambar mein padte hi chhanchhanata hai.", "text": "Tadka sambar par daalein, kata hara dhaniya milayein aur parosne se pehle 5 minute dhak kar rakhein, phir garam parosein."}}'::jsonb, null, 300, true, null, 'The tadka sizzles as it hits the sambar.', '{"en": "The tadka sizzles as it hits the sambar.", "sound": "The tadka sizzles as it hits the sambar."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
