insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'shahi-paneer'), 1, 'Put chopped onion, tomato, cashews and green chilli in a pan with half a cup of water, cover and boil until the onion is soft, then let it cool.', '{"en": "Put chopped onion, tomato, cashews and green chilli in a pan with half a cup of water, cover and boil until the onion is soft, then let it cool.", "hi": {"look": "प्याज़ नरम और पारदर्शी हो जाए।", "text": "कटा प्याज़, टमाटर, काजू और हरी मिर्च आधा कप पानी के साथ पैन में डालें, ढककर प्याज़ नरम होने तक उबालें, फिर ठंडा होने दें।"}, "hi-Latn": {"look": "Pyaaz naram aur transparent ho jaaye.", "text": "Kata pyaaz, tamatar, kaju aur hari mirch aadha cup paani ke saath pan mein daalein, dhak kar pyaaz naram hone tak ubaalein, phir thanda hone dein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 480, true, null, 'Onion turns soft and see-through.', '{"en": "Onion turns soft and see-through.", "heat": "medium", "look": "Onion turns soft and see-through."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'shahi-paneer'), 2, 'Grind the cooled mixture to a very smooth paste.', '{"en": "Grind the cooled mixture to a very smooth paste.", "hi": {"look": "पेस्ट मुलायम हो, काजू के टुकड़े न दिखें।", "safety": "ठंडा होने के बाद ही पीसें, गरम मिश्रण जार से उछल सकता है।", "text": "ठंडे मिश्रण को एकदम चिकना पीस लें।"}, "hi-Latn": {"look": "Paste silky ho, kaju ke tukde na dikhein.", "safety": "Thanda hone ke baad hi peesein, garam mixture jar se uchhal sakta hai.", "text": "Thande mixture ko ekdum smooth pees lein."}}'::jsonb, null, null, false, null, 'Paste is silky with no bits of cashew.', '{"en": "Paste is silky with no bits of cashew.", "look": "Paste is silky with no bits of cashew."}'::jsonb, null, 'Grind only once it has cooled; hot mixture can burst out of the jar.'),
  ((select id from public.recipes where household_id is null and slug = 'shahi-paneer'), 3, 'Heat ghee in a kadai and add bay leaf, cardamom, cloves and cinnamon.', '{"en": "Heat ghee in a kadai and add bay leaf, cardamom, cloves and cinnamon.", "hi": {"smell": "गरम मसालों की मीठी खुशबू आए।", "sound": "मसाले हल्के से चटकें।", "text": "कढ़ाई में घी गरम करें और तेज पत्ता, इलायची, लौंग और दालचीनी डालें।"}, "hi-Latn": {"smell": "Garam masalon ki meethi khushboo aaye.", "sound": "Masale halke se chatkein.", "text": "Kadai mein ghee garam karein aur tej patta, elaichi, laung aur dalchini daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'Spices sizzle gently. Warm, sweet spice smell rises.', '{"en": "Spices sizzle gently. Warm, sweet spice smell rises.", "heat": "low", "smell": "Warm, sweet spice smell rises.", "sound": "Spices sizzle gently."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'shahi-paneer'), 4, 'Add ginger garlic paste and stir until the raw smell goes.', '{"en": "Add ginger garlic paste and stir until the raw smell goes.", "hi": {"smell": "लहसुन की कच्ची महक नरम हो जाए।", "text": "अदरक लहसुन पेस्ट डालें और कच्ची महक जाने तक चलाएँ।"}, "hi-Latn": {"smell": "Lehsun ki kachchi mehak naram ho jaaye.", "text": "Adrak lehsun paste daalein aur kachchi mehak jaane tak chalayein."}}'::jsonb, null, 60, false, null, 'Raw garlic smell turns mellow.', '{"en": "Raw garlic smell turns mellow.", "heat": "low", "smell": "Raw garlic smell turns mellow."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'shahi-paneer'), 5, 'Add the ground paste, kashmiri chilli powder and coriander powder, and cook stirring until ghee separates at the sides.', '{"en": "Add the ground paste, kashmiri chilli powder and coriander powder, and cook stirring until ghee separates at the sides.", "hi": {"look": "मसाला थोड़ा गहरा हो जाए और किनारों पर घी चमके।", "safety": "पेस्ट उछलता है, ढक्कन आधा रखें और लंबे चम्मच से चलाएँ।", "text": "पिसा पेस्ट, कश्मीरी मिर्च और धनिया पाउडर डालें, और किनारों पर घी अलग होने तक चलाते हुए भूनें।"}, "hi-Latn": {"look": "Masala thoda gehra ho jaaye aur kinaron par ghee chamke.", "safety": "Paste uchhalta hai, dhakkan aadha rakhein aur lambe chammach se chalayein.", "text": "Pisa paste, kashmiri mirch aur dhaniya powder daalein, aur kinaron par ghee alag hone tak chalate hue bhunein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 600, true, null, 'Masala darkens slightly and ghee shines at the edges.', '{"en": "Masala darkens slightly and ghee shines at the edges.", "heat": "medium", "look": "Masala darkens slightly and ghee shines at the edges."}'::jsonb, null, 'The paste splutters; keep a lid half on and stir with a long spoon.'),
  ((select id from public.recipes where household_id is null and slug = 'shahi-paneer'), 6, 'Pour in about one cup of water with salt and sugar, and simmer until the gravy is creamy.', '{"en": "Pour in about one cup of water with salt and sugar, and simmer until the gravy is creamy.", "hi": {"look": "ग्रेवी चम्मच के पीछे लिपटने लगे।", "text": "लगभग एक कप पानी, नमक और चीनी डालें, और ग्रेवी गाढ़ी-मलाईदार होने तक पकाएँ।"}, "hi-Latn": {"look": "Gravy chammach ke peeche lipatne lage.", "text": "Lagbhag ek cup paani, namak aur cheeni daalein, aur gravy creamy hone tak pakayein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, true, null, 'Gravy coats the back of the spoon.', '{"en": "Gravy coats the back of the spoon.", "heat": "medium", "look": "Gravy coats the back of the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'shahi-paneer'), 7, 'Add paneer cubes, cream, crushed kasuri methi and garam masala, and cook gently without a hard boil.', '{"en": "Add paneer cubes, cream, crushed kasuri methi and garam masala, and cook gently without a hard boil.", "hi": {"text": "पनीर के टुकड़े, क्रीम, मसली हुई कसूरी मेथी और गरम मसाला डालें, और तेज़ उबाल लाए बिना धीरे पकाएँ।", "touch": "चम्मच से दबाने पर पनीर नरम रहे।"}, "hi-Latn": {"text": "Paneer ke tukde, cream, masli hui kasuri methi aur garam masala daalein, aur tez ubaal laaye bina dheere pakayein.", "touch": "Chammach se dabaane par paneer naram rahe."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 180, true, null, 'Paneer stays soft when pressed with the spoon.', '{"en": "Paneer stays soft when pressed with the spoon.", "heat": "low", "touch": "Paneer stays soft when pressed with the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'shahi-paneer'), 8, 'Turn off the heat, sprinkle coriander leaves and serve hot with roti or rice.', '{"en": "Turn off the heat, sprinkle coriander leaves and serve hot with roti or rice.", "hi": {"text": "आँच बंद करें, ऊपर हरा धनिया डालें और रोटी या चावल के साथ गरम परोसें।"}, "hi-Latn": {"text": "Aanch band karein, upar hara dhaniya daalein aur roti ya chawal ke saath garam serve karein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
