  source, review_status, is_published) values
  ('sprouts-usal', 'Sprouts Usal', '{"en": "Sprouts Usal", "hi": "स्प्राउट्स उसल", "hi-Latn": "Sprouts Usal"}'::jsonb, 'A Maharashtrian weekday usal of moong sprouts cooked with onion, tomato and fresh coconut, finished with a squeeze of lemon. Serve with pav, chapati or rice.', '{"hi": "महाराष्ट्र की रोज़ की उसळ, जिसमें मूंग स्प्राउट्स को प्याज़, टमाटर और ताज़े नारियल के साथ पकाया जाता है और ऊपर से नींबू निचोड़ा जाता है। पाव, रोटी या चावल के साथ परोसें।", "hi-Latn": "Maharashtra ki roz wali usal, jisme moong sprouts ko pyaaz, tamatar aur taaze nariyal ke saath pakaya jaata hai aur upar se nimbu nichoda jaata hai. Pav, roti ya chawal ke saath parosein."}'::jsonb, 'maharashtra', 'main', 'vegan', 4, 10, 25, 2, 2, array['kadai', 'gas_stove']::text[], array['comforting', 'high_protein', 'one_pot', 'tiffin']::text[], '{"acid": 0.3, "crunch": 0.3, "heat": 0.6, "rich": 0.3, "starch": 0.4, "sweet": 0.1}'::jsonb, array['dal', 'protein']::text[], 'curated', 'in_review', false)
