insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'sprouts-usal'), 1, 'Rinse the moong sprouts in a strainer under running water and let them drain.', '{"en": "Rinse the moong sprouts in a strainer under running water and let them drain.", "hi": {"text": "मूंग स्प्राउट्स को छलनी में डालकर बहते पानी में धो लें और पानी निथरने दें।"}, "hi-Latn": {"text": "Moong sprouts ko chhalni mein daal kar behte paani mein dho lein aur paani nitharne dein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sprouts-usal'), 2, 'Heat oil in a kadai, add mustard seeds, then cumin seeds, curry leaves and asafoetida.', '{"en": "Heat oil in a kadai, add mustard seeds, then cumin seeds, curry leaves and asafoetida.", "hi": {"safety": "गरम तेल में करी पत्ता छिटकता है, थोड़ा पीछे रहें।", "sound": "राई चटकने लगती है।", "text": "कढ़ाई में तेल गरम करें, राई डालें, फिर जीरा, करी पत्ता और हींग डालें।"}, "hi-Latn": {"safety": "Garam tel mein kadi patta chhitakta hai, thoda peeche rahein.", "sound": "Rai chatakne lagti hai.", "text": "Kadai mein tel garam karein, rai daalein, phir jeera, kadi patta aur hing daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The mustard seeds crackle and pop.', '{"en": "The mustard seeds crackle and pop.", "heat": "medium", "sound": "The mustard seeds crackle and pop."}'::jsonb, null, 'Curry leaves splutter in hot oil, so stand back.'),
  ((select id from public.recipes where household_id is null and slug = 'sprouts-usal'), 3, 'Add the onion, garlic and green chilli and sauté until the onion turns light golden.', '{"en": "Add the onion, garlic and green chilli and sauté until the onion turns light golden.", "hi": {"look": "प्याज़ नरम और हल्का सुनहरा हो जाता है।", "smell": "लहसुन की कच्ची महक चली जाती है।", "text": "प्याज़, लहसुन और हरी मिर्च डालें और प्याज़ हल्का सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram aur halka sunehra ho jaata hai.", "smell": "Lehsun ki kachchi mehak chali jaati hai.", "text": "Pyaaz, lehsun aur hari mirch daalein aur pyaaz halka sunehra hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 240, true, null, 'The onion turns soft and light golden. The raw garlic smell goes away.', '{"en": "The onion turns soft and light golden. The raw garlic smell goes away.", "heat": "medium", "look": "The onion turns soft and light golden.", "smell": "The raw garlic smell goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sprouts-usal'), 4, 'Add the tomato, turmeric, red chilli powder and coriander powder, then cook until the tomato is mushy.', '{"en": "Add the tomato, turmeric, red chilli powder and coriander powder, then cook until the tomato is mushy.", "hi": {"look": "टमाटर गल जाता है और किनारों पर तेल दिखने लगता है।", "text": "टमाटर, हल्दी, लाल मिर्च पाउडर और धनिया पाउडर डालें और टमाटर गलने तक पकाएँ।"}, "hi-Latn": {"look": "Tamatar gal jaata hai aur kinaron par tel dikhne lagta hai.", "text": "Tamatar, haldi, laal mirch powder aur dhaniya powder daalein aur tamatar galne tak pakayein."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 300, true, null, 'The tomato breaks down and oil shows at the edges.', '{"en": "The tomato breaks down and oil shows at the edges.", "heat": "medium", "look": "The tomato breaks down and oil shows at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sprouts-usal'), 5, 'Add the sprouts, salt and 1 cup of water, then stir, cover and simmer until the sprouts are tender.', '{"en": "Add the sprouts, salt and 1 cup of water, then stir, cover and simmer until the sprouts are tender.", "hi": {"text": "स्प्राउट्स, नमक और 1 कप पानी डालें, फिर चलाएँ, ढककर स्प्राउट्स नरम होने तक धीमी आँच पर पकाएँ।", "touch": "उँगलियों से दबाने पर स्प्राउट नरम लगता है पर आकार बना रहता है।"}, "hi-Latn": {"text": "Sprouts, namak aur 1 cup paani daalein, phir chalayein, dhak kar sprouts naram hone tak dheemi aanch par pakayein.", "touch": "Ungliyon se dabane par sprout naram lagta hai par shape bani rehti hai."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 720, true, null, 'A sprout presses soft between your fingers but still holds its shape.', '{"en": "A sprout presses soft between your fingers but still holds its shape.", "heat": "low", "touch": "A sprout presses soft between your fingers but still holds its shape."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sprouts-usal'), 6, 'Stir in the grated coconut, garam masala and jaggery, then simmer until the gravy thickens a little.', '{"en": "Stir in the grated coconut, garam masala and jaggery, then simmer until the gravy thickens a little.", "hi": {"look": "ग्रेवी स्प्राउट्स पर हल्की-सी लिपटी दिखती है।", "text": "कद्दूकस किया नारियल, गरम मसाला और गुड़ मिलाएँ, फिर ग्रेवी थोड़ी गाढ़ी होने तक पकाएँ।"}, "hi-Latn": {"look": "Gravy sprouts par halki-si lipti dikhti hai.", "text": "Kaddukas kiya nariyal, garam masala aur gud milayein, phir gravy thodi gaadhi hone tak pakayein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 180, true, null, 'The gravy coats the sprouts loosely.', '{"en": "The gravy coats the sprouts loosely.", "heat": "low", "look": "The gravy coats the sprouts loosely."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'sprouts-usal'), 7, 'Turn off the heat, squeeze in the lemon, sprinkle coriander leaves and serve hot.', '{"en": "Turn off the heat, squeeze in the lemon, sprinkle coriander leaves and serve hot.", "hi": {"text": "आँच बंद करें, नींबू निचोड़ें, हरा धनिया डालें और गरम परोसें।"}, "hi-Latn": {"text": "Aanch band karein, nimbu nichodein, hara dhaniya daalein aur garam parosein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
