insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'tori-sabzi'), 1, 'Scrape off the hard ridges of the ridge gourd, wash and cut it into small cubes; chop the onion, tomato and green chilli.', '{"en": "Scrape off the hard ridges of the ridge gourd, wash and cut it into small cubes; chop the onion, tomato and green chilli.", "hi": {"text": "तोरी की सख़्त धारियाँ छील लो, धोकर छोटे टुकड़ों में काट लो; प्याज़, टमाटर और हरी मिर्च बारीक काट लो।"}, "hi-Latn": {"text": "Tori ki sakht dhaariyan chheel lo, dhokar chhote tukdon mein kaat lo; pyaaz, tamatar aur hari mirch bareek kaat lo."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'tori-sabzi'), 2, 'Heat the oil in a kadai, add cumin seeds and asafoetida.', '{"en": "Heat the oil in a kadai, add cumin seeds and asafoetida.", "hi": {"look": "जीरा थोड़ा गहरा हो जाए।", "sound": "जीरा चटकने लगे।", "text": "कड़ाही में तेल गरम करो, जीरा और हींग डालो।"}, "hi-Latn": {"look": "Jeera thoda gehra ho jaaye.", "sound": "Jeera chatakne lage.", "text": "Kadai mein tel garam karo, jeera aur hing daalo."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin turns a shade darker. The cumin crackles.', '{"en": "The cumin turns a shade darker. The cumin crackles.", "heat": "medium", "look": "The cumin turns a shade darker.", "sound": "The cumin crackles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'tori-sabzi'), 3, 'Add the onion and green chilli and fry until the onion turns light golden.', '{"en": "Add the onion and green chilli and fry until the onion turns light golden.", "hi": {"look": "प्याज़ हल्का सुनहरा हो जाए।", "text": "प्याज़ और हरी मिर्च डालकर प्याज़ हल्का सुनहरा होने तक भूनो।"}, "hi-Latn": {"look": "Pyaaz halka sunehra ho jaaye.", "text": "Pyaaz aur hari mirch daalkar pyaaz halka sunehra hone tak bhuno."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 240, true, null, 'The onion turns light golden.', '{"en": "The onion turns light golden.", "heat": "medium", "look": "The onion turns light golden."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'tori-sabzi'), 4, 'Add the tomato, turmeric, red chilli powder and coriander powder, and cook until the tomato is soft.', '{"en": "Add the tomato, turmeric, red chilli powder and coriander powder, and cook until the tomato is soft.", "hi": {"look": "टमाटर गल जाए और किनारों पर तेल दिखे।", "text": "टमाटर, हल्दी, लाल मिर्च और धनिया पाउडर डालकर टमाटर नरम होने तक भूनो।"}, "hi-Latn": {"look": "Tamatar gal jaaye aur kinaron par tel dikhe.", "text": "Tamatar, haldi, laal mirch aur dhaniya powder daalkar tamatar naram hone tak bhuno."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 240, true, null, 'The tomato turns mushy and oil shows at the edges.', '{"en": "The tomato turns mushy and oil shows at the edges.", "heat": "medium", "look": "The tomato turns mushy and oil shows at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'tori-sabzi'), 5, 'Add the ridge gourd and salt, mix, cover and cook in its own water without adding any water, stirring once or twice.', '{"en": "Add the ridge gourd and salt, mix, cover and cook in its own water without adding any water, stirring once or twice.", "hi": {"look": "टुकड़े नरम और पारदर्शी हो जाएँ।", "text": "तोरी और नमक डालकर मिलाओ, ढककर बिना पानी डाले उसके अपने पानी में पकाओ, बीच में एक-दो बार चलाओ।", "touch": "चम्मच से टुकड़ा आसानी से दब जाए।"}, "hi-Latn": {"look": "Tukde naram aur transparent ho jaayein.", "text": "Tori aur namak daalkar milao, dhak kar bina paani daale uske apne paani mein pakao, beech mein ek-do baar chalao.", "touch": "Chammach se tukda aasani se dab jaaye."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 720, true, null, 'The pieces turn soft and see-through. A piece mashes easily under the spoon.', '{"en": "The pieces turn soft and see-through. A piece mashes easily under the spoon.", "heat": "low", "look": "The pieces turn soft and see-through.", "touch": "A piece mashes easily under the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'tori-sabzi'), 6, 'Uncover and cook until the extra water dries a little, then sprinkle garam masala and coriander leaves.', '{"en": "Uncover and cook until the extra water dries a little, then sprinkle garam masala and coriander leaves.", "hi": {"look": "बस थोड़ी गाढ़ी ग्रेवी बचे।", "text": "ढक्कन हटाकर ज़्यादा पानी थोड़ा सूखने तक पकाओ, फिर गरम मसाला और हरा धनिया डालो।"}, "hi-Latn": {"look": "Bas thodi gaadhi gravy bache.", "text": "Dhakkan hatakar zyada paani thoda sookhne tak pakao, phir garam masala aur hara dhaniya daalo."}}'::jsonb, null, 120, false, null, 'Only a little thick gravy is left.', '{"en": "Only a little thick gravy is left.", "heat": "medium", "look": "Only a little thick gravy is left."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'tori-sabzi') and step_no > 6;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'tori-sabzi');

-- Recipe: upma (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('upma', 'Upma', '{"en": "Upma", "hi": "उपमा", "hi-Latn": "Upma"}'::jsonb, 'A soft, savoury South Indian breakfast of roasted semolina cooked in water with a mustard seed, dal and curry leaf tadka, onion, ginger and green chilli, finished with lemon and coriander.', '{"hi": "भुनी हुई सूजी से बना नरम, नमकीन दक्षिण भारतीय नाश्ता। इसमें राई, दाल और करी पत्ते का तड़का, प्याज़, अदरक और हरी मिर्च पड़ती है, और ऊपर से नींबू और हरा धनिया।", "hi-Latn": "Bhuni hui suji se bana naram, namkeen South Indian nashta. Isme rai, dal aur curry patte ka tadka, pyaaz, adrak aur hari mirch padti hai, aur upar se nimbu aur hara dhaniya."}'::jsonb, 'south_indian', 'breakfast', 'veg', 4, 10, 20, 2, 2, array['kadai', 'gas_stove']::text[], array['quick', 'comforting', 'tiffin']::text[], '{"acid": 0.2, "crunch": 0.2, "heat": 0.3, "rich": 0.3, "starch": 0.8, "sweet": 0}'::jsonb, array['grain', 'sabzi']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
  description = excluded.description, descriptions = excluded.descriptions, cuisine_region = excluded.cuisine_region, course = excluded.course,
  diet = excluded.diet, base_servings = excluded.base_servings, prep_time_min = excluded.prep_time_min,
  cook_time_min = excluded.cook_time_min, difficulty = excluded.difficulty,
  spice_level = excluded.spice_level, equipment = excluded.equipment, tags = excluded.tags,
  flavor_profile = excluded.flavor_profile, food_groups = excluded.food_groups,
  review_status = excluded.review_status, is_published = excluded.is_published;

