insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'upma'), 1, 'Dry roast the semolina in a kadai on low heat, stirring often, then tip it onto a plate.', '{"en": "Dry roast the semolina in a kadai on low heat, stirring often, then tip it onto a plate.", "hi": {"look": "दाने सूखे, अलग-अलग और हल्के क्रीम रंग के दिखने लगें।", "smell": "हल्की सौंधी खुशबू आने लगे।", "text": "कड़ाही में सूजी को धीमी आँच पर लगातार चलाते हुए सूखा भूनें, फिर प्लेट में निकाल लें।"}, "hi-Latn": {"look": "Daane sookhe, alag-alag aur halke cream rang ke dikhne lagein.", "smell": "Halki saundhi khushboo aane lage.", "text": "Kadai me suji ko dheemi aanch par lagatar chalate hue sookha bhunein, phir plate me nikaal lein."}}'::jsonb, (select id from public.techniques where slug = 'dry_roast'), 360, true, null, 'The grains look dry, separate and just turn pale cream. It smells lightly nutty.', '{"en": "The grains look dry, separate and just turn pale cream. It smells lightly nutty.", "heat": "low", "look": "The grains look dry, separate and just turn pale cream.", "smell": "It smells lightly nutty."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'upma'), 2, 'Heat the oil on medium, add mustard seeds, then urad dal and chana dal, and fry till the dals turn golden; add curry leaves, green chilli and ginger.', '{"en": "Heat the oil on medium, add mustard seeds, then urad dal and chana dal, and fry till the dals turn golden; add curry leaves, green chilli and ginger.", "hi": {"look": "दालें सुनहरी भूरी हो जाएँ।", "safety": "गरम तेल में करी पत्ते चटकते हैं, डालते समय थोड़ा पीछे रहें।", "sound": "राई चटकने लगे।", "text": "मध्यम आँच पर तेल गरम करें, राई डालें, फिर उड़द दाल और चना दाल डालकर सुनहरा होने तक भूनें; फिर करी पत्ते, हरी मिर्च और अदरक डालें।"}, "hi-Latn": {"look": "Dalein sunehri bhoori ho jayein.", "safety": "Garam tel me curry patte chatakte hain, daalte samay thoda peeche rahein.", "sound": "Rai chatakne lage.", "text": "Medium aanch par tel garam karein, rai daalein, phir urad dal aur chana dal daalkar sunehra hone tak bhunein; phir curry patte, hari mirch aur adrak daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 120, false, null, 'The dals turn golden brown. The mustard seeds crackle and pop.', '{"en": "The dals turn golden brown. The mustard seeds crackle and pop.", "heat": "medium", "look": "The dals turn golden brown.", "sound": "The mustard seeds crackle and pop."}'::jsonb, null, 'Curry leaves splutter in hot oil, so stand back as you add them.'),
  ((select id from public.recipes where household_id is null and slug = 'upma'), 3, 'Add the onion and sauté till soft.', '{"en": "Add the onion and sauté till soft.", "hi": {"look": "प्याज़ नरम और पारदर्शी हो जाए, भूरा नहीं।", "text": "प्याज़ डालें और नरम होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram aur transparent ho jaye, bhoora nahi.", "text": "Pyaaz daalein aur naram hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 180, true, null, 'The onion turns soft and see-through, not brown.', '{"en": "The onion turns soft and see-through, not brown.", "heat": "medium", "look": "The onion turns soft and see-through, not brown."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'upma'), 4, 'Pour in 3 cups (about 600 ml) of water, add the salt and bring it to a rolling boil.', '{"en": "Pour in 3 cups (about 600 ml) of water, add the salt and bring it to a rolling boil.", "hi": {"look": "पूरी सतह पर बड़े बुलबुले उठने लगें।", "safety": "पानी धीरे डालें, गरम तेल पर यह भाप के साथ सनसनाता है।", "text": "3 कप (लगभग 600 ml) पानी डालें, नमक डालें और तेज़ उबाल आने दें।"}, "hi-Latn": {"look": "Poori satah par bade bulbule uthne lagein.", "safety": "Paani dheere daalein, garam tel par yeh bhaap ke saath sansanata hai.", "text": "3 cup (lagbhag 600 ml) paani daalein, namak daalein aur tez ubaal aane dein."}}'::jsonb, null, 240, true, null, 'Big bubbles rise all over the surface.', '{"en": "Big bubbles rise all over the surface.", "heat": "high", "look": "Big bubbles rise all over the surface."}'::jsonb, null, 'Pour the water slowly as it hisses and steams on the hot oil.'),
  ((select id from public.recipes where household_id is null and slug = 'upma'), 5, 'Turn the heat to low and add the roasted semolina in a thin stream with one hand while stirring non-stop with the other.', '{"en": "Turn the heat to low and add the roasted semolina in a thin stream with one hand while stirring non-stop with the other.", "hi": {"look": "बिना गुठलियों के एकसार गाढ़ा हो जाए।", "safety": "गाढ़ा होता उपमा उछलता है, लंबी कलछी लें और हाथ ऊपर से दूर रखें।", "text": "आँच धीमी करें और एक हाथ से भुनी सूजी पतली धार में डालें, दूसरे हाथ से लगातार चलाते रहें।"}, "hi-Latn": {"look": "Bina guthliyon ke ekasaar gaadha ho jaye.", "safety": "Gaadha hota upma uchhalta hai, lambi kalchhi lein aur haath upar se door rakhein.", "text": "Aanch dheemi karein aur ek haath se bhuni suji patli dhaar me daalein, doosre haath se lagatar chalate rahein."}}'::jsonb, null, 120, false, null, 'It thickens smoothly with no lumps.', '{"en": "It thickens smoothly with no lumps.", "heat": "low", "look": "It thickens smoothly with no lumps."}'::jsonb, null, 'The thickening upma bubbles and spits, so use a long spoon and keep your hand away from the top.'),
  ((select id from public.recipes where household_id is null and slug = 'upma'), 6, 'Cover and cook on low, then stir in the ghee if using.', '{"en": "Cover and cook on low, then stir in the ghee if using.", "hi": {"look": "सारा पानी सोख लिया जाए और उपमा फूला-फूला दिखे।", "text": "ढककर धीमी आँच पर पकाएँ, फिर चाहें तो घी मिला दें।", "touch": "कलछी से दबाने पर दाने नरम लगें, किरकिरे नहीं।"}, "hi-Latn": {"look": "Saara paani sokh liya jaye aur upma phoola-phoola dikhe.", "text": "Dhakkar dheemi aanch par pakayein, phir chahein to ghee mila dein.", "touch": "Kalchhi se dabane par daane naram lagein, kirkire nahi."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 180, true, null, 'All the water is absorbed and the upma looks fluffy. The grains feel soft, not gritty, when pressed with the spoon.', '{"en": "All the water is absorbed and the upma looks fluffy. The grains feel soft, not gritty, when pressed with the spoon.", "heat": "low", "look": "All the water is absorbed and the upma looks fluffy.", "touch": "The grains feel soft, not gritty, when pressed with the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'upma'), 7, 'Turn off the heat, squeeze in the lemon, mix in the coriander leaves and serve hot.', '{"en": "Turn off the heat, squeeze in the lemon, mix in the coriander leaves and serve hot.", "hi": {"text": "गैस बंद करें, नींबू निचोड़ें, हरा धनिया मिलाएँ और गरमागरम परोसें।"}, "hi-Latn": {"text": "Gas band karein, nimbu nichodein, hara dhaniya milayein aur garmagaram parosein."}}'::jsonb, null, null, false, null, null, '{}'::jsonb, null, null)
