-- Recipe: uttapam (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('uttapam', 'Uttapam', '{"en": "Uttapam", "hi": "उत्तपम", "hi-Latn": "Uttapam"}'::jsonb, 'Thick, soft South Indian pancakes made from fermented idli dosa batter and topped with onion, tomato, green chilli and coriander. They are cooked on a tawa until golden underneath and served hot with chutney or sambar.', '{"hi": "इडली डोसा बैटर से बने मोटे, नरम दक्षिण भारतीय उत्तपम, जिन पर प्याज़, टमाटर, हरी मिर्च और हरा धनिया डाला जाता है। इन्हें तवे पर नीचे से सुनहरा होने तक सेंका जाता है और गरमागरम चटनी या सांबर के साथ परोसा जाता है।", "hi-Latn": "Idli dosa batter se bane mote, naram South Indian uttapam, jin par pyaaz, tamatar, hari mirch aur hara dhaniya daala jaata hai. Inhe tawe par neeche se sunehra hone tak senka jaata hai aur garamagaram chutney ya sambar ke saath parosa jaata hai."}'::jsonb, 'south_indian', 'breakfast', 'vegan', 4, 15, 30, 2, 2, array['tawa', 'gas_stove']::text[], array['comforting', 'kids_friendly', 'tiffin']::text[], '{"acid": 0.3, "crunch": 0.2, "heat": 0.3, "rich": 0.3, "starch": 0.7, "sweet": 0.1}'::jsonb, array['grain', 'dal', 'sabzi']::text[], 'curated', 'in_review', false)
on conflict (slug) where household_id is null do update set title = excluded.title, titles = excluded.titles,
  description = excluded.description, descriptions = excluded.descriptions, cuisine_region = excluded.cuisine_region, course = excluded.course,
  diet = excluded.diet, base_servings = excluded.base_servings, prep_time_min = excluded.prep_time_min,
  cook_time_min = excluded.cook_time_min, difficulty = excluded.difficulty,
  spice_level = excluded.spice_level, equipment = excluded.equipment, tags = excluded.tags,
  flavor_profile = excluded.flavor_profile, food_groups = excluded.food_groups,
  review_status = excluded.review_status, is_published = excluded.is_published;

