insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'uttapam'), 1, 'Finely chop the onion, tomato, green chilli and coriander, grate the carrot if using, and mix them in a bowl with a pinch of the salt.', '{"en": "Finely chop the onion, tomato, green chilli and coriander, grate the carrot if using, and mix them in a bowl with a pinch of the salt.", "hi": {"text": "प्याज़, टमाटर, हरी मिर्च और हरा धनिया बारीक काट लो। गाजर डाल रहे हो तो उसे कद्दूकस कर लो। सबको एक कटोरे में थोड़े से नमक के साथ मिला लो।"}, "hi-Latn": {"text": "Pyaaz, tamatar, hari mirch aur hara dhaniya baareek kaat lo. Gajar daal rahe ho to use kaddukas kar lo. Sabko ek katore mein thode se namak ke saath mila lo."}}'::jsonb, null, 600, true, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'uttapam'), 2, 'Stir the batter well, and add the rest of the salt only if your batter is unsalted.', '{"en": "Stir the batter well, and add the rest of the salt only if your batter is unsalted.", "hi": {"look": "बैटर गाढ़ा हो, पर करछी से धीरे-धीरे गिरे।", "smell": "हल्की खट्टी, अच्छी खुशबू आए।", "text": "बैटर को अच्छे से चला लो। अगर बैटर में नमक नहीं है, तभी बाकी नमक डालना।"}, "hi-Latn": {"look": "Batter gaadha ho, par karchhi se dheere-dheere gire.", "smell": "Halki khatti, achhi khushboo aaye.", "text": "Batter ko achhe se chala lo. Agar batter mein namak nahi hai, tabhi baaki namak daalna."}}'::jsonb, null, null, false, null, 'The batter is thick but pours slowly from the ladle. It smells pleasantly sour.', '{"en": "The batter is thick but pours slowly from the ladle. It smells pleasantly sour.", "look": "The batter is thick but pours slowly from the ladle.", "smell": "It smells pleasantly sour."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'uttapam'), 3, 'Heat the tawa on medium and grease it lightly with a few drops of oil.', '{"en": "Heat the tawa on medium and grease it lightly with a few drops of oil.", "hi": {"look": "तवे पर तेल चमकने लगे।", "text": "तवा मध्यम आँच पर गरम करो और कुछ बूँद तेल से हल्का चिकना कर लो।", "touch": "तवे के ऊपर हथेली रखो तो साफ़ गरमी महसूस हो।"}, "hi-Latn": {"look": "Tawe par tel chamakne lage.", "text": "Tawa medium aanch par garam karo aur kuch boond tel se halka chikna kar lo.", "touch": "Tawe ke upar hatheli rakho to saaf garmi mehsoos ho."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 180, true, null, 'The oil shimmers on the tawa. Your palm held above the tawa feels clear heat.', '{"en": "The oil shimmers on the tawa. Your palm held above the tawa feels clear heat.", "heat": "medium", "look": "The oil shimmers on the tawa.", "touch": "Your palm held above the tawa feels clear heat."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'uttapam'), 4, 'Pour one ladle of batter in the centre and spread it gently into a thick round about the size of a small plate.', '{"en": "Pour one ladle of batter in the centre and spread it gently into a thick round about the size of a small plate.", "hi": {"look": "उत्तपम मोटा ही रहे, डोसे जैसा पतला नहीं।", "sound": "बैटर तवे पर पड़ते ही हल्का छन्न करे।", "text": "बीच में एक करछी बैटर डालो और हल्के से फैलाकर छोटी प्लेट जितना मोटा गोल बना लो।"}, "hi-Latn": {"look": "Uttapam mota hi rahe, dose jaisa patla nahi.", "sound": "Batter tawe par padte hi halka chhann kare.", "text": "Beech mein ek karchhi batter daalo aur halke se phailakar chhoti plate jitna mota gol bana lo."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), null, false, null, 'The round stays thick, not thin like a dosa. The batter gives a soft sizzle as it touches the tawa.', '{"en": "The round stays thick, not thin like a dosa. The batter gives a soft sizzle as it touches the tawa.", "heat": "medium", "look": "The round stays thick, not thin like a dosa.", "sound": "The batter gives a soft sizzle as it touches the tawa."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'uttapam'), 5, 'Scatter a handful of the vegetable mix on top and press it lightly into the batter with the back of the ladle.', '{"en": "Scatter a handful of the vegetable mix on top and press it lightly into the batter with the back of the ladle.", "hi": {"text": "ऊपर से एक मुट्ठी सब्ज़ी का मिश्रण फैलाओ और करछी के पिछले हिस्से से हल्का दबा दो।"}, "hi-Latn": {"text": "Upar se ek mutthi sabzi ka mishran phailao aur karchhi ke pichhle hisse se halka daba do."}}'::jsonb, null, null, false, null, null, '{"heat": "medium"}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'uttapam'), 6, 'Drizzle a teaspoon of oil around the edge, cover and cook until the base is golden.', '{"en": "Drizzle a teaspoon of oil around the edge, cover and cook until the base is golden.", "hi": {"look": "ऊपर का हिस्सा गीला न रहे और किनारे सुनहरे होकर उठने लगें।", "smell": "सिंकने की अच्छी खुशबू आए।", "text": "किनारों पर एक छोटा चम्मच तेल डालो, ढककर नीचे से सुनहरा होने तक सेंको।"}, "hi-Latn": {"look": "Upar ka hissa geela na rahe aur kinare sunehre hokar uthne lagein.", "smell": "Sinkne ki achhi khushboo aaye.", "text": "Kinaron par ek chhota chammach tel daalo, dhakkar neeche se sunehra hone tak senko."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 180, true, null, 'The top is no longer wet and the edges turn golden and lift. It smells toasty.', '{"en": "The top is no longer wet and the edges turn golden and lift. It smells toasty.", "heat": "medium", "look": "The top is no longer wet and the edges turn golden and lift.", "smell": "It smells toasty."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'uttapam'), 7, 'Flip the uttapam and cook the topping side until the onions are lightly browned.', '{"en": "Flip the uttapam and cook the topping side until the onions are lightly browned.", "hi": {"safety": "अपने से दूर की तरफ़ पलटना, ताकि गरम तेल हाथ पर न छिटके।", "sound": "सब्ज़ियाँ तवे पर छनछनाएँ।", "text": "उत्तपम पलटो और सब्ज़ी वाली तरफ़ प्याज़ हल्का भूरा होने तक सेंको।"}, "hi-Latn": {"safety": "Apne se door ki taraf palatna, taaki garam tel haath par na chhitke.", "sound": "Sabziyaan tawe par chhanchhanayein.", "text": "Uttapam palto aur sabzi wali taraf pyaaz halka bhoora hone tak senko."}}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 120, false, null, 'The vegetables sizzle against the tawa.', '{"en": "The vegetables sizzle against the tawa.", "heat": "medium", "sound": "The vegetables sizzle against the tawa."}'::jsonb, null, 'Flip away from you so hot oil does not splash on your hand.'),
  ((select id from public.recipes where household_id is null and slug = 'uttapam'), 8, 'Serve hot with chutney or sambar, and repeat with the rest of the batter, greasing the tawa each time.', '{"en": "Serve hot with chutney or sambar, and repeat with the rest of the batter, greasing the tawa each time.", "hi": {"text": "गरमागरम चटनी या सांबर के साथ परोसो। बाकी बैटर से भी इसी तरह बनाओ, हर बार तवा चिकना करते रहना।"}, "hi-Latn": {"text": "Garamagaram chutney ya sambar ke saath paroso. Baaki batter se bhi isi tarah banao, har baar tawa chikna karte rehna."}}'::jsonb, null, null, false, null, null, '{"heat": "medium"}'::jsonb, null, null)
