-- Recipe: varan (in_review, not published)
insert into public.recipes (slug, title, titles, description, descriptions, cuisine_region, course, diet, base_servings,
  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('varan', 'Varan', '{"en": "Varan", "hi": "वरण", "hi-Latn": "Varan"}'::jsonb, 'A gentle, smooth toor dal cooked with just turmeric, asafoetida and salt, with a hint of jaggery. It is served hot over rice with a spoon of ghee as everyday varan bhaat.', '{"hi": "हल्दी, हींग और नमक के साथ पकी सादी और मुलायम तूर दाल, जिसमें थोड़ा सा गुड़ भी पड़ता है। इसे गरम चावल पर एक चम्मच घी डालकर रोज़ के वरण भात की तरह परोसा जाता है।", "hi-Latn": "Haldi, hing aur namak ke saath paki saadi aur mulayam toor dal, jismein thoda sa gud bhi padta hai. Ise garam chawal par ek chammach ghee daalkar roz ke varan bhaat ki tarah parosa jaata hai."}'::jsonb, 'maharashtra', 'main', 'veg', 4, 25, 25, 1, 1, array['pressure_cooker', 'gas_stove']::text[], array['comforting', 'kids_friendly', 'one_pot']::text[], '{"acid": 0.1, "crunch": 0, "heat": 0, "rich": 0.4, "starch": 0.5, "sweet": 0.1}'::jsonb, array['dal']::text[], 'curated', 'in_review', false)
