insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'varan'), 1, 'Wash the toor dal in water 3 times and soak it in fresh water for 20 minutes, then drain.', '{"en": "Wash the toor dal in water 3 times and soak it in fresh water for 20 minutes, then drain.", "hi": {"look": "धोने का पानी लगभग साफ़ हो जाता है।", "text": "तूर दाल को पानी में 3 बार धोकर साफ़ पानी में 20 मिनट भिगो दो, फिर पानी निकाल दो।", "touch": "भीगे दाने थोड़े फूले हुए लगते हैं।"}, "hi-Latn": {"look": "Dhone ka paani lagbhag saaf ho jaata hai.", "text": "Toor dal ko paani mein 3 baar dhokar saaf paani mein 20 minute bhigo do, phir paani nikaal do.", "touch": "Bheege daane thode phoole hue lagte hain."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 1200, true, null, 'The rinse water turns almost clear. The soaked grains feel slightly swollen.', '{"en": "The rinse water turns almost clear. The soaked grains feel slightly swollen.", "look": "The rinse water turns almost clear.", "touch": "The soaked grains feel slightly swollen."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'varan'), 2, 'Put the dal in the pressure cooker with 500 ml water, the turmeric and the asafoetida, and cook for 4 whistles on medium heat.', '{"en": "Put the dal in the pressure cooker with 500 ml water, the turmeric and the asafoetida, and cook for 4 whistles on medium heat.", "hi": {"safety": "ढक्कन खोलने से पहले प्रेशर अपने आप उतरने दो।", "sound": "4 साफ़ सीटियाँ सुनाई देती हैं।", "text": "दाल को प्रेशर कुकर में 500 ml पानी, हल्दी और हींग के साथ डालो और मध्यम आँच पर 4 सीटी आने तक पकाओ।"}, "hi-Latn": {"safety": "Dhakkan kholne se pehle pressure apne aap utarne do.", "sound": "4 saaf seetiyan sunaai deti hain.", "text": "Dal ko pressure cooker mein 500 ml paani, haldi aur hing ke saath daalo aur medium aanch par 4 seeti aane tak pakao."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 900, true, 4, 'You hear 4 clear whistles.', '{"en": "You hear 4 clear whistles.", "heat": "medium", "sound": "You hear 4 clear whistles."}'::jsonb, null, 'Let the pressure drop on its own before you open the lid.'),
  ((select id from public.recipes where household_id is null and slug = 'varan'), 3, 'Open the cooker and whisk or mash the dal with a ladle until completely smooth.', '{"en": "Open the cooker and whisk or mash the dal with a ladle until completely smooth.", "hi": {"look": "कोई साबुत दाना नहीं बचता और दाल मलाईदार पीली दिखती है।", "text": "कुकर खोलो और दाल को मथनी या करछी से तब तक घोटो जब तक वह पूरी तरह चिकनी न हो जाए।", "touch": "दाल बिना गुठलियों के मुलायम लगती है।"}, "hi-Latn": {"look": "Koi saabut daana nahin bachta aur dal malaidaar peeli dikhti hai.", "text": "Cooker kholo aur dal ko mathni ya karchhi se tab tak ghoto jab tak woh poori tarah chikni na ho jaaye.", "touch": "Dal bina guthliyon ke mulayam lagti hai."}}'::jsonb, null, 120, false, null, 'No whole grains are left and the dal looks creamy yellow. The dal feels silky with no lumps.', '{"en": "No whole grains are left and the dal looks creamy yellow. The dal feels silky with no lumps.", "look": "No whole grains are left and the dal looks creamy yellow.", "touch": "The dal feels silky with no lumps."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'varan'), 4, 'Add about 200 ml hot water, the salt and the jaggery, and simmer on low-medium heat for 5 minutes, stirring now and then.', '{"en": "Add about 200 ml hot water, the salt and the jaggery, and simmer on low-medium heat for 5 minutes, stirring now and then.", "hi": {"look": "दाल गाढ़ी है पर बहने लायक है, चिकने सूप जैसी।", "safety": "उबलती दाल छींटे मारती है, इसलिए लंबी करछी से चलाओ।", "sound": "धीमी, हल्की बुदबुदाहट।", "text": "लगभग 200 ml गरम पानी, नमक और गुड़ डालो और बीच-बीच में चलाते हुए धीमी-मध्यम आँच पर 5 मिनट उबालो।"}, "hi-Latn": {"look": "Dal gaadhi hai par behne laayak hai, chikne soup jaisi.", "safety": "Ubalti dal chheente maarti hai, isliye lambi karchhi se chalao.", "sound": "Dheemi, halki budbudaahat.", "text": "Lagbhag 200 ml garam paani, namak aur gud daalo aur beech-beech mein chalaate hue dheemi-medium aanch par 5 minute ubaalo."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, true, null, 'The dal is thick but pourable, like a smooth soup. Gentle, slow bubbling.', '{"en": "The dal is thick but pourable, like a smooth soup. Gentle, slow bubbling.", "heat": "medium", "look": "The dal is thick but pourable, like a smooth soup.", "sound": "Gentle, slow bubbling."}'::jsonb, null, 'Simmering dal can spit, so stir with a long ladle.'),
  ((select id from public.recipes where household_id is null and slug = 'varan'), 5, 'Serve the varan hot over steamed rice with a spoon of ghee on top and a squeeze of lemon if you like.', '{"en": "Serve the varan hot over steamed rice with a spoon of ghee on top and a squeeze of lemon if you like.", "hi": {"look": "घी दाल पर सुनहरा होकर पिघल जाता है।", "smell": "गरम घी की सौंधी, अच्छी खुशबू आती है।", "text": "वरण को गरम चावल पर ऊपर से एक चम्मच घी डालकर गरमागरम परोसो, चाहो तो थोड़ा नींबू निचोड़ लो।"}, "hi-Latn": {"look": "Ghee dal par sunehra hokar pighal jaata hai.", "smell": "Garam ghee ki saundhi, achhi khushboo aati hai.", "text": "Varan ko garam chawal par upar se ek chammach ghee daalkar garamagaram parosो, chaaho to thoda nimbu nichod lo."}}'::jsonb, null, null, false, null, 'The ghee melts into a golden pool on the dal. The warm ghee smells nutty and fragrant.', '{"en": "The ghee melts into a golden pool on the dal. The warm ghee smells nutty and fragrant.", "look": "The ghee melts into a golden pool on the dal.", "smell": "The warm ghee smells nutty and fragrant."}'::jsonb, null, null)
