  prep_time_min, cook_time_min, difficulty, spice_level, equipment, tags, flavor_profile, food_groups,
  source, review_status, is_published) values
  ('vegetable-dalia', 'Vegetable Dalia', '{"en": "Vegetable Dalia", "hi": "वेजिटेबल दलिया", "hi-Latn": "Vegetable Dalia"}'::jsonb, 'A savoury breakfast porridge of roasted broken wheat cooked in the pressure cooker with onion, tomato, carrot, peas and beans, tempered with cumin in ghee.', '{"hi": "भुने हुए दलिये का नमकीन नाश्ता, जो प्याज़, टमाटर, गाजर, मटर और बीन्स के साथ प्रेशर कुकर में पकता है और घी में जीरे का तड़का लगता है।", "hi-Latn": "Bhune hue daliye ka namkeen naashta, jo pyaaz, tamatar, gaajar, matar aur beans ke saath pressure cooker mein pakta hai aur ghee mein jeere ka tadka lagta hai."}'::jsonb, 'north_indian', 'breakfast', 'veg', 4, 10, 20, 1, 2, array['pressure_cooker', 'gas_stove']::text[], array['comforting', 'one_pot', 'kids_friendly', 'light']::text[], '{"acid": 0.2, "crunch": 0.1, "heat": 0.3, "rich": 0.3, "starch": 0.7, "sweet": 0.1}'::jsonb, array['grain', 'sabzi']::text[], 'curated', 'in_review', false)
