insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'vegetable-dalia'), 1, 'Heat half the ghee in the pressure cooker and roast the broken wheat, stirring, until golden.', '{"en": "Heat half the ghee in the pressure cooker and roast the broken wheat, stirring, until golden.", "hi": {"look": "दाने हल्के सुनहरे हो जाते हैं।", "smell": "सौंधी, भुनी हुई खुशबू आती है।", "text": "प्रेशर कुकर में आधा घी गरम करो और दलिये को चलाते हुए सुनहरा होने तक भूनो।"}, "hi-Latn": {"look": "Daane halke sunehre ho jaate hain.", "smell": "Saundhi, bhuni hui khushboo aati hai.", "text": "Pressure cooker mein aadha ghee garam karo aur daliye ko chalate hue sunehra hone tak bhuno."}}'::jsonb, (select id from public.techniques where slug = 'dry_roast'), 300, true, null, 'The grains turn light golden. It smells nutty and toasty.', '{"en": "The grains turn light golden. It smells nutty and toasty.", "heat": "medium", "look": "The grains turn light golden.", "smell": "It smells nutty and toasty."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'vegetable-dalia'), 2, 'Take the dalia out onto a plate, add the rest of the ghee and crackle the cumin seeds.', '{"en": "Take the dalia out onto a plate, add the rest of the ghee and crackle the cumin seeds.", "hi": {"sound": "जीरा चटकने लगता है।", "text": "दलिया एक प्लेट में निकाल लो, बचा हुआ घी डालो और जीरा चटकाओ।"}, "hi-Latn": {"sound": "Jeera chatakne lagta hai.", "text": "Dalia ek plate mein nikaal lo, bacha hua ghee daalo aur jeera chatkao."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin sizzles and crackles.', '{"en": "The cumin sizzles and crackles.", "heat": "medium", "sound": "The cumin sizzles and crackles."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'vegetable-dalia'), 3, 'Add chopped onion, ginger and green chilli and sauté until the onion is soft.', '{"en": "Add chopped onion, ginger and green chilli and sauté until the onion is soft.", "hi": {"look": "प्याज़ नरम और पारदर्शी हो जाता है।", "text": "कटा प्याज़, अदरक और हरी मिर्च डालकर प्याज़ नरम होने तक भूनो।"}, "hi-Latn": {"look": "Pyaaz naram aur transparent ho jaata hai.", "text": "Kata pyaaz, adrak aur hari mirch daalkar pyaaz naram hone tak bhuno."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 180, true, null, 'The onion turns soft and see-through.', '{"en": "The onion turns soft and see-through.", "heat": "medium", "look": "The onion turns soft and see-through."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'vegetable-dalia'), 4, 'Add chopped tomato, carrot, peas, beans, turmeric and salt and cook until the tomato softens.', '{"en": "Add chopped tomato, carrot, peas, beans, turmeric and salt and cook until the tomato softens.", "hi": {"look": "टमाटर गल जाता है।", "text": "कटा टमाटर, गाजर, मटर, बीन्स, हल्दी और नमक डालकर टमाटर नरम होने तक पकाओ।"}, "hi-Latn": {"look": "Tamatar gal jaata hai.", "text": "Kata tamatar, gaajar, matar, beans, haldi aur namak daalkar tamatar naram hone tak pakao."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 180, true, null, 'The tomato turns mushy.', '{"en": "The tomato turns mushy.", "heat": "medium", "look": "The tomato turns mushy."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'vegetable-dalia'), 5, 'Add the roasted dalia and 4 cups of water, stir, close the lid and pressure-cook.', '{"en": "Add the roasted dalia and 4 cups of water, stir, close the lid and pressure-cook.", "hi": {"safety": "कुकर खोलने से पहले प्रेशर अपने आप निकलने दो।", "text": "भुना दलिया और 4 कप पानी डालो, चलाओ, ढक्कन बंद करो और प्रेशर कुकर में पकाओ।"}, "hi-Latn": {"safety": "Cooker kholne se pehle pressure apne aap nikalne do.", "text": "Bhuna dalia aur 4 cup paani daalo, chalao, dhakkan band karo aur pressure cooker mein pakao."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), null, false, 3, null, '{"heat": "medium"}'::jsonb, null, 'Let the pressure drop on its own before opening the cooker.'),
  ((select id from public.recipes where household_id is null and slug = 'vegetable-dalia'), 6, 'Open the cooker, stir, add a little hot water if it is too thick, and finish with coriander leaves and a squeeze of lemon.', '{"en": "Open the cooker, stir, add a little hot water if it is too thick, and finish with coriander leaves and a squeeze of lemon.", "hi": {"look": "दलिया नरम और दलिये जैसा गाढ़ा हो जाता है।", "text": "कुकर खोलकर चलाओ, बहुत गाढ़ा हो तो थोड़ा गरम पानी डालो, और ऊपर से हरा धनिया और नींबू निचोड़ो।"}, "hi-Latn": {"look": "Dalia naram aur porridge jaisa gaadha ho jaata hai.", "text": "Cooker kholkar chalao, bahut gaadha ho to thoda garam paani daalo, aur upar se hara dhaniya aur nimbu nichodo."}}'::jsonb, null, null, false, null, 'The dalia is soft and porridge-like.', '{"en": "The dalia is soft and porridge-like.", "look": "The dalia is soft and porridge-like."}'::jsonb, null, null)
