insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'whole-moong'), 1, 'Wash the moong 2 to 3 times and soak it in plenty of water for about 4 hours.', '{"en": "Wash the moong 2 to 3 times and soak it in plenty of water for about 4 hours.", "hi": {"look": "दाने फूले हुए दिखते हैं और कुछ के छिलके फटने लगते हैं।", "text": "मूंग को 2-3 बार धोकर भरपूर पानी में लगभग 4 घंटे भिगो दें।", "touch": "भीगा दाना दबाने पर मोटा और हल्का नरम लगता है।"}, "hi-Latn": {"look": "Daane phoole hue dikhte hain aur kuch ke chhilke phatne lagte hain.", "text": "Moong ko 2-3 baar dhokar bharpoor paani mein lagbhag 4 ghante bhigo dein.", "touch": "Bheega daana dabane par mota aur halka naram lagta hai."}}'::jsonb, (select id from public.techniques where slug = 'soak'), 14400, true, null, 'The grains look swollen and a few skins start to split. A soaked grain is plump and slightly soft when pressed.', '{"en": "The grains look swollen and a few skins start to split. A soaked grain is plump and slightly soft when pressed.", "look": "The grains look swollen and a few skins start to split.", "touch": "A soaked grain is plump and slightly soft when pressed."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'whole-moong'), 2, 'Drain the moong, put it in the pressure cooker with 700 ml water, the salt and turmeric, and cook for 4 whistles on medium heat.', '{"en": "Drain the moong, put it in the pressure cooker with 700 ml water, the salt and turmeric, and cook for 4 whistles on medium heat.", "hi": {"look": "खोलने पर दाने नरम होते हैं और कुछ फट चुके होते हैं।", "safety": "कुकर तभी खोलें जब प्रेशर अपने आप पूरा निकल जाए।", "text": "मूंग का पानी निकाल दें, कुकर में 700 ml पानी, नमक और हल्दी के साथ डालें और मध्यम आँच पर 4 सीटी लगाएँ।", "touch": "दाना दो उंगलियों के बीच आसानी से मसल जाता है।"}, "hi-Latn": {"look": "Kholne par daane naram hote hain aur kuch phat chuke hote hain.", "safety": "Cooker tabhi kholein jab pressure apne aap poora nikal jaaye.", "text": "Moong ka paani nikaal dein, cooker mein 700 ml paani, namak aur haldi ke saath daalein aur medium aanch par 4 seeti lagayein.", "touch": "Daana do ungliyon ke beech aasaani se masal jaata hai."}}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 900, true, 4, 'After opening, the grains are soft and some have burst. A grain mashes easily between two fingers.', '{"en": "After opening, the grains are soft and some have burst. A grain mashes easily between two fingers.", "heat": "medium", "look": "After opening, the grains are soft and some have burst.", "touch": "A grain mashes easily between two fingers."}'::jsonb, null, 'Open the cooker only after the pressure has dropped on its own.'),
  ((select id from public.recipes where household_id is null and slug = 'whole-moong'), 3, 'Heat the ghee in a kadai on medium heat, add the cumin seeds and then the asafoetida.', '{"en": "Heat the ghee in a kadai on medium heat, add the cumin seeds and then the asafoetida.", "hi": {"look": "जीरा थोड़ा गहरा हो जाता है।", "smell": "भुने जीरे की गरम खुशबू आती है।", "sound": "घी में डालते ही जीरा चटकने लगता है।", "text": "कढ़ाई में मध्यम आँच पर घी गरम करें, जीरा डालें और फिर हींग डालें।"}, "hi-Latn": {"look": "Jeera thoda gehra ho jaata hai.", "smell": "Bhune jeere ki garam khushboo aati hai.", "sound": "Ghee mein daalte hi jeera chatakne lagta hai.", "text": "Kadai mein medium aanch par ghee garam karein, jeera daalein aur phir hing daalein."}}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin turns a shade darker. The cumin crackles as soon as it hits the ghee. A warm roasted jeera smell rises.', '{"en": "The cumin turns a shade darker. The cumin crackles as soon as it hits the ghee. A warm roasted jeera smell rises.", "heat": "medium", "look": "The cumin turns a shade darker.", "smell": "A warm roasted jeera smell rises.", "sound": "The cumin crackles as soon as it hits the ghee."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'whole-moong'), 4, 'Add the chopped onion, grated ginger, chopped garlic and slit green chilli, and saute until the onion is golden.', '{"en": "Add the chopped onion, grated ginger, chopped garlic and slit green chilli, and saute until the onion is golden.", "hi": {"look": "प्याज़ नरम हो जाता है और किनारों से हल्का सुनहरा हो जाता है।", "smell": "लहसुन की कच्ची गंध चली जाती है।", "text": "कटा प्याज़, कसा अदरक, कटा लहसुन और चीरी हुई हरी मिर्च डालें और प्याज़ सुनहरा होने तक भूनें।"}, "hi-Latn": {"look": "Pyaaz naram ho jaata hai aur kinaron se halka sunehra ho jaata hai.", "smell": "Lehsun ki kachchi gandh chali jaati hai.", "text": "Kata pyaaz, kasa adrak, kata lehsun aur cheeri hui hari mirch daalein aur pyaaz sunehra hone tak bhunein."}}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 360, true, null, 'The onion turns soft and light golden at the edges. The raw smell of garlic goes away.', '{"en": "The onion turns soft and light golden at the edges. The raw smell of garlic goes away.", "heat": "medium", "look": "The onion turns soft and light golden at the edges.", "smell": "The raw smell of garlic goes away."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'whole-moong'), 5, 'Add the chopped tomato, red chilli powder and coriander powder, and cook the masala until the tomato is mushy and ghee shows at the sides.', '{"en": "Add the chopped tomato, red chilli powder and coriander powder, and cook the masala until the tomato is mushy and ghee shows at the sides.", "hi": {"look": "मसाले के किनारों पर घी अलग होकर चमकने लगता है।", "text": "कटा टमाटर, लाल मिर्च पाउडर और धनिया पाउडर डालें, और मसाले को तब तक पकाएँ जब तक टमाटर गल न जाए और किनारों पर घी न दिखने लगे।", "touch": "टमाटर चम्मच से आसानी से मसल जाता है।"}, "hi-Latn": {"look": "Masale ke kinaron par ghee alag hokar chamakne lagta hai.", "text": "Kata tamatar, laal mirch powder aur dhaniya powder daalein, aur masale ko tab tak pakayein jab tak tamatar gal na jaaye aur kinaron par ghee na dikhne lage.", "touch": "Tamatar chammach se aasaani se masal jaata hai."}}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 360, true, null, 'Ghee separates and shines at the edges of the masala. The tomato mashes easily under the spoon.', '{"en": "Ghee separates and shines at the edges of the masala. The tomato mashes easily under the spoon.", "heat": "medium", "look": "Ghee separates and shines at the edges of the masala.", "touch": "The tomato mashes easily under the spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'whole-moong'), 6, 'Pour the cooked moong with its water into the masala, lightly mash a few grains, add a little hot water if it is too thick, and simmer.', '{"en": "Pour the cooked moong with its water into the masala, lightly mash a few grains, add a little hot water if it is too thick, and simmer.", "hi": {"look": "दाल मलाईदार हो जाती है और चम्मच के पीछे लिपटने लगती है।", "safety": "गरम दाल उछल सकती है, इसलिए लंबे चम्मच से चलाएँ।", "sound": "धीरे-धीरे बुलबुले उठते हैं।", "text": "पकी हुई मूंग पानी समेत मसाले में डालें, कुछ दाने हल्के से मसल दें, ज़्यादा गाढ़ी लगे तो थोड़ा गरम पानी डालें और धीमी आँच पर उबालें।"}, "hi-Latn": {"look": "Dal malaidaar ho jaati hai aur chammach ke peeche lipatne lagti hai.", "safety": "Garam dal uchhal sakti hai, isliye lambe chammach se chalayein.", "sound": "Dheere-dheere bulbule uthte hain.", "text": "Paki hui moong paani samet masale mein daalein, kuch daane halke se masal dein, zyada gaadhi lage to thoda garam paani daalein aur dheemi aanch par ubaalein."}}'::jsonb, (select id from public.techniques where slug = 'simmer'), 480, true, null, 'The dal turns creamy and coats the back of the spoon. It bubbles gently.', '{"en": "The dal turns creamy and coats the back of the spoon. It bubbles gently.", "heat": "low", "look": "The dal turns creamy and coats the back of the spoon.", "sound": "It bubbles gently."}'::jsonb, null, 'Hot dal can splutter, so stir with a long spoon.'),
  ((select id from public.recipes where household_id is null and slug = 'whole-moong'), 7, 'Turn off the heat, stir in the garam masala, top with chopped coriander and a squeeze of lemon if you like, and serve hot.', '{"en": "Turn off the heat, stir in the garam masala, top with chopped coriander and a squeeze of lemon if you like, and serve hot.", "hi": {"smell": "गरम मसाले की ताज़ी, गरम खुशबू आती है।", "text": "आँच बंद करें, गरम मसाला मिलाएँ, ऊपर से कटा हरा धनिया और चाहें तो थोड़ा नींबू निचोड़ें, और गरम परोसें।"}, "hi-Latn": {"smell": "Garam masale ki taazi, garam khushboo aati hai.", "text": "Aanch band karein, garam masala milayein, upar se kata hara dhaniya aur chahein to thoda nimbu nichodein, aur garam parosein."}}'::jsonb, null, null, false, null, 'The garam masala smells fresh and warm.', '{"en": "The garam masala smells fresh and warm.", "smell": "The garam masala smells fresh and warm."}'::jsonb, null, null)
on conflict (recipe_id, step_no) do update set instruction = excluded.instruction,
  instructions = excluded.instructions, technique_id = excluded.technique_id,
  duration_sec = excluded.duration_sec, timer_required = excluded.timer_required,
  whistles = excluded.whistles, sensory_cue = excluded.sensory_cue, sensory_cues = excluded.sensory_cues,
  member_branch = excluded.member_branch, safety_note = excluded.safety_note;
delete from public.recipe_steps where recipe_id = (select id from public.recipes where household_id is null and slug = 'whole-moong') and step_no > 7;

delete from public.recipe_variation_rules where recipe_id = (select id from public.recipes where household_id is null and slug = 'whole-moong');

-- Calendar (48 festivals and fasts, 2026-11-15 to 2027-11-10): global rows in the window are
-- replaced; households' own rows (and copies of fasts they keep) are never touched.
delete from public.calendar_events where household_id is null and event_date between '2026-11-15' and '2027-11-10';
